									,0 FifteenDaysCount		
									,0 TweentyDaysCount
									,0 TwentyFiveyDaysCount
									,0 AS ThirtyDaysCount
									,Count(IR.Id) AS GraterThirtyDaysCount
									,0 AS AllCount
