										,sum(isnull(PolicyRate,0)) Rate
										,sum(isnull(PolicyAmount,0)) Total32Value 
										from trn.InventoryIssueDetail Group by InventoryIssueId) IID ON IID.InventoryIssueId=II.Id		
									Where DATEDIFF(day,II.IssueDate,getdate()) between 0 And 90000000

									AND II.VoucherId IS null AND II.IsPostingRequired=1
									GROUP BY II.CompanyGroupId-- ,II.PlantId	  
								)Res32 ON Res32.CompanyGroupId=cmpGR.Id  --AND Res32.PlantId=p.Id 
								where CMPGR.Active = 1 --AND cmp.Id='C20171'
								)as t  
								--where isnull(CompanyId,'') in('','C20171') AND isnull(PlantId,'') in('','20171') 
								order by SI DESC";

                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }


        public IEnumerable<object> InventoryStatusDashboard(string companyGroupId, string companyId, string factDate, string fromDate, string toDate, string groupName, bool ValueOrNumber, string queryString, string queryStringProcess)
        {
            try
            {
                var ValueOrNumber1 = 0;
                if (ValueOrNumber == false)
                {
                    ValueOrNumber1 = 1;
                }
                else
                {
                    ValueOrNumber1 = 0;
                }

                string paramters = "";
                if (queryString != "")
                {
                    if (paramters == "")
                        paramters += "isnull(opbal.CompanyId,'') in(" + queryString + ")";
                    else
                        paramters += " AND isnull(opbal.CompanyId,'') in(" + queryString + ")";
                }
                if (queryStringProcess != "")
                {
                    if (paramters == "")
                        paramters += " isnull(opbal.PlantId,'') in(" + queryStringProcess + ")";
                    else
                        paramters += " AND isnull(opbal.PlantId,'') in(" + queryStringProcess + ")";
                }

                var sql = "";

                if (groupName == "groupName" && queryString == null)
                {

                    sql = @"SELECT Distinct --CMPGR.Id AS CompanyGroupId
								--, CMPGR.UserName AS GroupName
								 --,cmp.Id AS CompanyId
								--,isnull((case when row_number() over (partition by CMP.UserName  order by (select NULL)) = 1 then CMP.UserName end),'') as ColumnName,
								isnull(MT.UserName,'') MaterialType
								,Sum(isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0)) As OpeningBalance	
								,Sum(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)) AS OpeningBalanceAmount
								,Sum(isnull(opbal2.TransactionQty,0)) ReceivedForThePeriod
								,Sum(isnull(opbal2.TotalMaterialBooksCurrencyAmount,0)) AS ReceivedForThePeriodAmount
								,0 ReturnQty
								,0 ReturnAmount
								,Sum(isnull(IFD1.IssueQty,0)) IssueForThePeriod	
								,Sum(isnull(IFD1.PolicyAmount,0)) IssueForThePeriodAmount	
								,0 IssueReturnQty
								,0 IssueReturnAmount
								,Sum((isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0) + isnull(opbal2.TransactionQty,0))-isnull(IFD1.IssueQty,0)) Closing
								,Sum((isnull(opbal.TotalMaterialBooksCurrencyAmount,0) + isnull(opbal2.TotalMaterialBooksCurrencyAmount,0))-isnull(IFD1.PolicyAmount,0)) ClosingAmount
								from TRN.InventoryMaterial AS IM
								left join ORG.CompanyGroup CMPGR ON CMPGR.Id=IM.CompanyGroupId
								left join  org.company CMP ON CMP.CompanyGroupId = IM.CompanyGroupId	
								left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
								LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
								LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
								LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
								LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
								LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
								LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
								LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
								LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
								left jOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId=IM.Id	
								--left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON IRD.TransactionUoMId=TUoM.Id
								--left JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId=IR.Id
								--left JOIN [SCS].[Currency] AS CU ON IR.CurrencyId=CU.Id
								LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
								left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id	
								left join(  SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount,IR.GRNDate,IR.PlantId
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate) <= '" + fromDate + @"'   group By IRD.InventoryMaterialId,IR.CompanyId,IR.GRNDate,IR.PlantId--) AS opbal ON opbal.InventoryMaterialId=IM.Id AND IM.PlantId='20204'
										UNION ALL
										SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount,IR.GRNDate,IR.PlantId
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate) < '" + fromDate + @"'  group By IRD.InventoryMaterialId,IR.CompanyId,IR.GRNDate,IR.PlantId
										) AS opbal ON opbal.InventoryMaterialId=IM.Id AND opbal.CompanyId=cmp.Id --AND IM.CompanyId='C20202' --AND IM.PlantId='20204'

								left join(  SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate) > '" + toDate + @"'  group By IRD.InventoryMaterialId,IR.CompanyId--) AS opbal1 ON opbal1.InventoryMaterialId=IM.Id AND IM.PlantId='20204'
										UNION ALL
										SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate) = '" + toDate + @"'  group By IRD.InventoryMaterialId,IR.CompanyId
										) AS opbal1 ON opbal1.InventoryMaterialId=IM.Id AND opbal1.CompanyId=cmp.Id --AND IM.CompanyId='C20202' --AND IM.PlantId='20204'

								left join(SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate)		
										BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' group By IRD.InventoryMaterialId,IR.CompanyId
										) AS opbal2 ON opbal2.InventoryMaterialId=IM.Id AND opbal2.CompanyId=cmp.Id --AND IM.CompanyId='C20202' 

								left join (select IID.InventoryMaterialId,II.CompanyId, Sum(IID.TransactionQty) OpeningIssueQty, Sum(IID.PolicyAmount) PolicyAmount
										FROM TRN.InventoryIssueDetail IID  
										LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 									
										WHERE convert(Date,II.IssueDate) < '" + fromDate + @"' 
										 GROUP BY IID.InventoryMaterialId,II.CompanyId
										) IFD3 On IFD3.InventoryMaterialId=IM.Id AND opbal2.CompanyId=cmp.Id--AND IM.CompanyId='C20202' 
								left join (select IID.InventoryMaterialId,II.CompanyId, Sum(IID.TransactionQty) IssueQty , Sum(IID.PolicyAmount) PolicyAmount
										FROM TRN.InventoryIssueDetail IID  
										LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 
										--LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId=IID.Id
										WHERE convert(Date,II.IssueDate) = '" + toDate + @"' --AND II.CompanyId='C20171'  
										GROUP BY IID.InventoryMaterialId,II.CompanyId
										) IFD On IFD.InventoryMaterialId=IM.Id AND opbal2.CompanyId=cmp.Id --AND IM.CompanyId='C20202' 

								left join (select IID.InventoryMaterialId,II.CompanyId
								, Sum(IID.TransactionQty) IssueQty , Sum(IID.PolicyAmount) PolicyAmount
										FROM TRN.InventoryIssueDetail IID  
										LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 
										--LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId=IID.Id
									WHERE convert(Date,II.IssueDate) BETWEEN  '" + fromDate + @"' AND '" + toDate + @"'
									GROUP BY IID.InventoryMaterialId,II.CompanyId
									) IFD1 On IFD1.InventoryMaterialId=IM.Id AND opbal2.CompanyId=cmp.Id--AND IM.CompanyId='C20171' --AND IM.PlantId='20204'
								 --where " + paramters + " And MT.UserName<>'' AND opbal.GRNDate  Between '" + fromDate + @"' AND '" + toDate + @"' AND   
								--where opbal.GRNDate  Between '" + fromDate + @"' AND '" + toDate + @"' AND 
                                    where MM.IsRegular='" + ValueOrNumber1 + @"' 
									group by  
									--CMPGR.Id
									--,CMPGR.UserName 
									--,cmp.Id
									--,CMP.UserName 
									--,opbal.PlantId,
									isnull(MT.UserName,'')";
                }
                else
                {
                    sql = @"SELECT Distinct CMPGR.Id AS CompanyGroupId
								, CMPGR.UserName AS GroupName
								 ,cmp.Id AS CompanyId
								,isnull((case when row_number() over (partition by CMP.UserName  order by (select NULL)) = 1 then CMP.UserName end),'') as ColumnName
								,isnull(MT.UserName,'') MaterialType
								,Sum(isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0)) As OpeningBalance	
								,Sum(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)) AS OpeningBalanceAmount
								,Sum(isnull(opbal2.TransactionQty,0)) ReceivedForThePeriod
								,Sum(isnull(opbal2.TotalMaterialBooksCurrencyAmount,0)) AS ReceivedForThePeriodAmount
								,0 ReturnQty
								,0 ReturnAmount
								,Sum(isnull(IFD1.IssueQty,0)) IssueForThePeriod	
								,Sum(isnull(IFD1.PolicyAmount,0)) IssueForThePeriodAmount	
								,0 IssueReturnQty
								,0 IssueReturnAmount
								,Sum((isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0) + isnull(opbal2.TransactionQty,0))-isnull(IFD1.IssueQty,0)) Closing
								,Sum((isnull(opbal.TotalMaterialBooksCurrencyAmount,0) + isnull(opbal2.TotalMaterialBooksCurrencyAmount,0))-isnull(IFD1.PolicyAmount,0)) ClosingAmount
								from TRN.InventoryMaterial AS IM
								left join ORG.CompanyGroup CMPGR ON CMPGR.Id=IM.CompanyGroupId
								left join  org.company CMP ON CMP.CompanyGroupId = IM.CompanyGroupId	
								left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
								LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
								LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
								LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
								LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
								LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
								LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
								LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
								LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
								left jOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId=IM.Id	
								--left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON IRD.TransactionUoMId=TUoM.Id
								--left JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId=IR.Id
								--left JOIN [SCS].[Currency] AS CU ON IR.CurrencyId=CU.Id
								LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
								left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id	
								left join(  SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount,IR.GRNDate,IR.PlantId
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate) <= '" + fromDate + @"'   group By IRD.InventoryMaterialId,IR.CompanyId,IR.GRNDate,IR.PlantId--) AS opbal ON opbal.InventoryMaterialId=IM.Id AND IM.PlantId='20204'
										UNION ALL
										SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount,IR.GRNDate,IR.PlantId
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate) < '" + fromDate + @"'  group By IRD.InventoryMaterialId,IR.CompanyId,IR.GRNDate,IR.PlantId
										) AS opbal ON opbal.InventoryMaterialId=IM.Id AND opbal.CompanyId=cmp.Id --AND IM.CompanyId='C20202' --AND IM.PlantId='20204'

								left join(  SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate) > '" + toDate + @"'  group By IRD.InventoryMaterialId,IR.CompanyId--) AS opbal1 ON opbal1.InventoryMaterialId=IM.Id AND IM.PlantId='20204'
										UNION ALL
										SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate) = '" + toDate + @"'  group By IRD.InventoryMaterialId,IR.CompanyId
										) AS opbal1 ON opbal1.InventoryMaterialId=IM.Id AND opbal1.CompanyId=cmp.Id --AND IM.CompanyId='C20202' --AND IM.PlantId='20204'

								left join(SELECT IRD.InventoryMaterialId,IR.CompanyId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
										FROM  [TRN].[InventoryReceiveDetail] IRD
										LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
										where convert(Date,IR.GRNDate)		
										BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' group By IRD.InventoryMaterialId,IR.CompanyId
										) AS opbal2 ON opbal2.InventoryMaterialId=IM.Id AND opbal2.CompanyId=cmp.Id --AND IM.CompanyId='C20202' 

								left join (select IID.InventoryMaterialId,II.CompanyId, Sum(IID.TransactionQty) OpeningIssueQty, Sum(IID.PolicyAmount) PolicyAmount
										FROM TRN.InventoryIssueDetail IID  
										LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 									
										WHERE convert(Date,II.IssueDate) < '" + fromDate + @"' 
										 GROUP BY IID.InventoryMaterialId,II.CompanyId
										) IFD3 On IFD3.InventoryMaterialId=IM.Id AND opbal2.CompanyId=cmp.Id--AND IM.CompanyId='C20202' 
								left join (select IID.InventoryMaterialId,II.CompanyId, Sum(IID.TransactionQty) IssueQty , Sum(IID.PolicyAmount) PolicyAmount
										FROM TRN.InventoryIssueDetail IID  
										LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 
										--LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId=IID.Id
										WHERE convert(Date,II.IssueDate) = '" + toDate + @"' --AND II.CompanyId='C20171'  
										GROUP BY IID.InventoryMaterialId,II.CompanyId
										) IFD On IFD.InventoryMaterialId=IM.Id AND opbal2.CompanyId=cmp.Id --AND IM.CompanyId='C20202' 

								left join (select IID.InventoryMaterialId,II.CompanyId
								, Sum(IID.TransactionQty) IssueQty , Sum(IID.PolicyAmount) PolicyAmount
										FROM TRN.InventoryIssueDetail IID  
										LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 
										--LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId=IID.Id
									WHERE convert(Date,II.IssueDate) BETWEEN  '" + fromDate + @"' AND '" + toDate + @"'
									GROUP BY IID.InventoryMaterialId,II.CompanyId
									) IFD1 On IFD1.InventoryMaterialId=IM.Id AND opbal2.CompanyId=cmp.Id--AND IM.CompanyId='C20171' --AND IM.PlantId='20204'
								  where " + paramters + " And MT.UserName<>'' AND opbal.GRNDate  Between '" + fromDate + @"' AND '" + toDate + @"'   
                                  AND MM.IsRegular='" + ValueOrNumber1 + @"' 
									group by  CMPGR.Id
									, CMPGR.UserName 
									,cmp.Id
									,CMP.UserName 
									,opbal.PlantId
									,isnull(MT.UserName,'')";
                }

                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }

        public IEnumerable<object> DymnamicExpenseList(IEnumerable<ChartColumnList> ChartColumnList, int seq, string factDate, string fromDate, string toDate, string companyGroupId, string companyId, string plantId)
        {
            try
            {

                var sql = @"select						
											CompanyGroupId
											,GroupName
											,CompanyId
											, PlantId
											--,ColumnName1
											,isnull((case when row_number() over (partition by ColumnName1  order by (select NULL)) = 1 then ColumnName1 end),'') as ColumnName
											,Category
											,NULLIF(ThreeDaysCount,0) ThreeDaysCount,NULLIF(Total3Value,0) Total3Value
											,NULLIF(FiveDaysCount,0) FiveDaysCount,NULLIF(Total5Value,0) Total5Value
											,NULLIF(TenDaysCount,0) TenDaysCount,NULLIF(Total10Value,0) Total10Value
											,NULLIF(FifteenDaysCount,0) FifteenDaysCount,NULLIF(Total15Value,0) Total15Value
											,NULLIF(TweentyDaysCount,0) TweentyDaysCount,NULLIF(Total20Value,0) Total20Value
											,NULLIF(TwentyFiveyDaysCount,0) TwentyFiveyDaysCount,NULLIF(Total25Value,0) Total25Value
											,NULLIF(ThirtyDaysCount,0) ThirtyDaysCount,NULLIF(Total30Value,0) Total30Value
											,NULLIF(GraterThirtyDaysCount,0) GraterThirtyDaysCount,NULLIF(Total31Value,0) Total31Value	
											,NULLIF(AllCount,0) AllCount,NULLIF(Total32Value,0) Total32Value	
											from(
											SELECT
											CMPGR.Id AS CompanyGroupId
											, CMPGR.UserName AS GroupName
											, cmp.Id AS CompanyId
											,p.Id PlantId
											--, P.UserName AS ColumnName
											,isnull((case when row_number() over (partition by P.UserName  order by (select NULL)) = 1 then P.UserName end),'') as ColumnName1
											,'Pending Requisition' Category, 1 SI
											,isnull(Res3.ThreeDaysCount,0) ThreeDaysCount,isnull(Res3.Total3Value,0) Total3Value
											,isnull(Res5.FiveDaysCount,0) FiveDaysCount,isnull(Res5.Total5Value,0) Total5Value
											,isnull(Res10.TenDaysCount,0) TenDaysCount,isnull(Res10.Total10Value,0) Total10Value
											,isnull(Res15.FifteenDaysCount,0) FifteenDaysCount,isnull(Res15.Total15Value,0) Total15Value
											,isnull(Res20.TweentyDaysCount,0) TweentyDaysCount,isnull(Res20.Total20Value,0) Total20Value
											,isnull(Res25.TwentyFiveyDaysCount,0) TwentyFiveyDaysCount,isnull(Res25.Total25Value,0) Total25Value
											,isnull(Res30.ThirtyDaysCount,0) ThirtyDaysCount,isnull(Res30.Total30Value,0) Total30Value
											,isnull(Res31.GraterThirtyDaysCount,0) GraterThirtyDaysCount,isnull(Res31.Total31Value,0) Total31Value	
											,isnull(Res32.AllCount,0) AllCount,isnull(Res32.Total32Value,0) Total32Value
				
											from ORG.CompanyGroup CMPGR
											left join  org.company CMP ON CMP.CompanyGroupId = CMPGR.Id 
											LEFT JOIN org.Plant p on P.CompanyId=CMP.Id




											LEFT JOIN
												(           select 'Pending Requisition' Category
															--,Count(distinct distinct MRM.Id) ThreeDaysCount
															,Count(MRM.Id) ThreeDaysCount
															, MRM.CompanyId,MRM.PlantId
															,0 AS FiveDaysCount
															,0 AS TenDaysCount
															,0 AS FifteenDaysCount
															,0 AS TweentyDaysCount
															,0 AS TwentyFiveyDaysCount
															,0 AS ThirtyDaysCount
															,0 AS GraterThirtyDaysCount
															,0 AS AllCount
															,sum(MRD.TransactionQty) Qty
															,sum(MRD.EstimatedRate) Rate
															,sum(MRD.TotalAmount) Total3Value
															FROM trn.MaterialRequsitionMaster MRM
															LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId=MRM.id			
															WHERE MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
															and DATEDIFF(day,MRM.RequisitionDate,getdate())>=0  and DATEDIFF(day,MRM.RequisitionDate,getdate())<=3  
															AND MRM.CheckedByStatus !='Reject' AND MRM.InActive=0
															Group BY MRM.CompanyId,MRM.PlantId
											)Res3 ON Res3.CompanyId=cmp.Id AND Res3.PlantId=p.Id	
											LEFT JOIN(
															select 'Pending Requisition' Category
																,Count( distinct MRM.Id) FiveDaysCount
															, MRM.CompanyId,MRM.PlantId
															,0 AS ThreeDaysCount
															,0 TenDaysCount
															,0 FifteenDaysCount
															,0 TweentyDaysCount
															,0 TwentyFiveyDaysCount
															,0 ThirtyDaysCount
															,0 GraterThirtyDaysCount
															,0 AS AllCount
															,sum(MRD.TransactionQty) Qty
															,sum(MRD.EstimatedRate) Rate
															,sum(MRD.TotalAmount) Total5Value
															FROM trn.MaterialRequsitionMaster MRM
															LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId=MRM.id			
															WHERE MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
															and DATEDIFF(day,MRM.RequisitionDate,getdate())>=3  and DATEDIFF(day,MRM.RequisitionDate,getdate())<=5  
															AND MRM.CheckedByStatus !='Reject' AND MRM.InActive=0
															Group BY MRM.CompanyId,MRM.PlantId
											)Res5 ON Res5.CompanyId=cmp.Id AND Res5.PlantId=p.Id	
											LEFT JOIN(
															select 'Pending Requisition' Category
															,Count(distinct MRM.Id) TenDaysCount
															,MRM.CompanyId,MRM.PlantId
															,0 AS ThreeDaysCount
															,0 AS FiveDaysCount
															,0 AS FifteenDaysCount
															,0 AS TweentyDaysCount
															,0 AS TwentyFiveyDaysCount
															,0 AS ThirtyDaysCount
															,0 AS GraterThirtyDaysCount
															,0 AS AllCount
															,sum(MRD.TransactionQty) Qty
															,sum(MRD.EstimatedRate) Rate
															,sum(MRD.TotalAmount) Total10Value
															FROM trn.MaterialRequsitionMaster MRM
															LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId=MRM.id			
															WHERE MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
															and DATEDIFF(day,MRM.RequisitionDate,getdate())>=5 and DATEDIFF(day,MRM.RequisitionDate,getdate())<=10  
															AND MRM.CheckedByStatus !='Reject' AND MRM.InActive=0
															Group BY MRM.CompanyId,MRM.PlantId
											)Res10 ON Res10.CompanyId=cmp.Id AND Res10.PlantId=p.Id	
											LEFT JOIN(
															select 'Pending Requisition' Category
															,Count(distinct MRM.Id) FifteenDaysCount
															,MRM.CompanyId,MRM.PlantId
															,0 AS ThreeDaysCount
															,0 AS FiveDaysCount
															,0 AS TenDaysCount
															,0 AS TweentyDaysCount
															,0 AS TwentyFiveyDaysCount
															,0 AS ThirtyDaysCount
															,0 AS GraterThirtyDaysCount
															,0 AS AllCount
															,sum(MRD.TransactionQty) Qty
															,sum(MRD.EstimatedRate) Rate
															,sum(MRD.TotalAmount) Total15Value
															FROM trn.MaterialRequsitionMaster MRM
															LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId=MRM.id			
															WHERE MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
															and DATEDIFF(day,MRM.RequisitionDate,getdate())>=10  and DATEDIFF(day,MRM.RequisitionDate,getdate())<=15 
																AND MRM.CheckedByStatus !='Reject' AND MRM.InActive=0
															Group BY MRM.CompanyId,MRM.PlantId
											)Res15 ON Res15.CompanyId=cmp.Id AND Res15.PlantId=p.Id	
											LEFT JOIN(
															select 'Pending Requisition' Category
															,Count(distinct MRM.Id) TweentyDaysCount
															,MRM.CompanyId,MRM.PlantId
															,0 AS ThreeDaysCount
															,0 AS FiveDaysCount
															,0 AS TenDaysCount
															,0 FifteenDaysCount
															,0 TwentyFiveyDaysCount
															,0 AS ThirtyDaysCount
															,0 AS GraterThirtyDaysCount
															,0 AS AllCount
															,sum(MRD.TransactionQty) Qty
															,sum(MRD.EstimatedRate) Rate
															,sum(MRD.TotalAmount) Total20Value
															FROM trn.MaterialRequsitionMaster MRM
															LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId=MRM.id			
															WHERE MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
															and DATEDIFF(day,MRM.RequisitionDate,getdate()) >=15 and DATEDIFF(day,MRM.RequisitionDate,getdate()) <=20   
															AND MRM.CheckedByStatus !='Reject' AND MRM.InActive=0
															Group BY MRM.CompanyId,MRM.PlantId
											)Res20 ON Res20.CompanyId=cmp.Id AND Res20.PlantId=p.Id	
											LEFT JOIN(
															select 'Pending Requisition' Category
															,Count(distinct MRM.Id) TwentyFiveyDaysCount
															,MRM.CompanyId,MRM.PlantId
															,0 AS ThreeDaysCount
															,0 AS FiveDaysCount
															,0 AS TenDaysCount
															,0 AS FifteenDaysCount
															,0 AS TweentyDaysCount
															,0 AS ThirtyDaysCount
															,0 AS GraterThirtyDaysCount
															,0 AS AllCount
															,sum(MRD.TransactionQty) Qty
															,sum(MRD.EstimatedRate) Rate
															,sum(MRD.TotalAmount) Total25Value
															FROM trn.MaterialRequsitionMaster MRM
															LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId=MRM.id			
															WHERE MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
															and DATEDIFF(day,MRM.RequisitionDate,getdate())>=20   and DATEDIFF(day,MRM.RequisitionDate,getdate())<=25  
															AND MRM.CheckedByStatus !='Reject' AND MRM.InActive=0
															Group BY MRM.CompanyGroupId, MRM.CompanyId, MRM.PlantId
											)Res25 ON Res25.CompanyId=cmp.Id AND Res25.PlantId=p.Id	
											LEFT JOIN(
															select 'Pending Requisition' Category
															,Count(distinct MRM.Id) ThirtyDaysCount
															,MRM.CompanyId,MRM.PlantId
															,0 AS ThreeDaysCount
															,0 AS FiveDaysCount
															,0 AS TenDaysCount
															,0 AS FifteenDaysCount
															,0 AS TweentyDaysCount
															,0 AS TwentyFiveyDaysCount
															,0 AS GraterThirtyDaysCount
															,0 AS AllCount
															,sum(MRD.TransactionQty) Qty
															,sum(MRD.EstimatedRate) Rate
															,sum(MRD.TotalAmount) Total30Value
															FROM trn.MaterialRequsitionMaster MRM
															LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId=MRM.id			
															WHERE MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
															and DATEDIFF(day,MRM.RequisitionDate,getdate()) >=25  and DATEDIFF(day,MRM.RequisitionDate,getdate())<=30  
															AND MRM.CheckedByStatus !='Reject' AND MRM.InActive=0
															Group BY MRM.CompanyId,MRM.PlantId
											)Res30 ON Res30.CompanyId=cmp.Id AND Res30.PlantId=p.Id	
											LEFT JOIN(
															select 'Pending Requisition' Category 
															,Count(distinct MRM.Id) GraterThirtyDaysCount
															, MRM.CompanyId,MRM.PlantId
															,0 AS ThreeDaysCount
															,0 AS FiveDaysCount
															,0 AS TenDaysCount
															,0 AS FifteenDaysCount
															,0 AS TweentyDaysCount
															,0 AS TwentyFiveyDaysCount
															,0 AS ThirtyDaysCount
															,0 AS AllCount
															,sum(MRD.TransactionQty) Qty
															,sum(MRD.EstimatedRate) Rate
															,sum(MRD.TotalAmount) Total31Value
															FROM trn.MaterialRequsitionMaster MRM
															LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId=MRM.id			
															WHERE MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
															and DATEDIFF(day,MRM.RequisitionDate,getdate())>=30 and DATEDIFF(day,MRM.RequisitionDate,getdate())<=9000000 
															AND MRM.CheckedByStatus !='Reject' AND MRM.InActive=0
															Group BY MRM.CompanyId,MRM.PlantId
					
											)Res31 ON Res31.CompanyId=cmp.Id AND Res31.PlantId=p.Id	
											LEFT JOIN(
															SELECT 'Pending Requisition' Category 
													
															, MRM.CompanyId,MRM.PlantId
															,0 AS ThreeDaysCount
															,0 AS FiveDaysCount
															,0 AS TenDaysCount
															,0 AS FifteenDaysCount
															,0 AS TweentyDaysCount
															,0 AS TwentyFiveyDaysCount
															,0 AS ThirtyDaysCount
															,0 AS GraterThirtyDaysCount
															,Count(distinct MRM.Id) AllCount
															,sum(MRD.TransactionQty) Qty
															,sum(MRD.EstimatedRate) Rate
															,sum(MRD.TotalAmount) Total32Value
															FROM trn.MaterialRequsitionMaster MRM
															LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId=MRM.id			
															WHERE MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
														and DATEDIFF(day,MRM.RequisitionDate,getdate())>=0 and DATEDIFF(day,MRM.RequisitionDate,getdate())<=9000000 
															AND MRM.CheckedByStatus !='Reject' AND MRM.InActive=0
															Group BY MRM.CompanyId	,MRM.PlantId				
											)Res32 ON Res32.CompanyId=cmp.Id AND Res32.PlantId=p.Id									
											where cmp.Active =1 and CMPGR.Active = 1 --AND cmp.Id='C20171'



											UNION ALL

