																,Count(II.Id) AS FiveDaysCount
																,0 AS TenDaysCount
																,0 FifteenDaysCount
																,0 as TweentyDaysCount
																,0 TwentyFiveyDaysCount
																,0 AS ThirtyDaysCount
																,0 AS GraterThirtyDaysCount
																	,0 AS AllCount
