														Where DATEDIFF(day,II.IssueDate,getdate()) >=3  AND   DATEDIFF(day,II.IssueDate,getdate()) <=5   
														AND II.VoucherId IS null
														GROUP BY II.CompanyId  ,II.PlantId	 
											)Res5 ON Res5.CompanyId=cmp.Id AND Res5.PlantId=p.Id	
											Left JOIN(
														SELECT 'Pending Inventory Issue Posting' Category			
														, II.CompanyId		,II.PlantId		
														,0 ThreeDaysCount   
																,0 AS FiveDaysCount
																,Count(II.Id) AS TenDaysCount
																,0 FifteenDaysCount
																,0 as TweentyDaysCount
																,0 TwentyFiveyDaysCount
																,0 AS ThirtyDaysCount
																,0 AS GraterThirtyDaysCount
																	,0 AS AllCount
														    ,sum(isnull(IID.Qty,0)) Qty
															,sum(isnull(IID.Rate,0)) Rate
															,(sum(isnull(IID.Qty,0))* sum(isnull(IID.Rate,0)))Total10Value
															FROM trn.InventoryIssue II
															LEFT JOIN (Select InventoryIssueId,
															sum(isnull(TransactionQty,0)) Qty
															,sum(isnull(PolicyRate,0)) Rate
															,sum(isnull(PolicyAmount,0)) Total10Value 
															from trn.InventoryIssueDetail Group by InventoryIssueId) IID ON IID.InventoryIssueId=II.Id	
														Where DATEDIFF(day,II.IssueDate,getdate()) >=5 AND DATEDIFF(day,II.IssueDate,getdate()) <=10
														AND II.VoucherId IS null
														GROUP BY II.CompanyId  ,II.PlantId	  
											)Res10 ON Res10.CompanyId=cmp.Id AND Res10.PlantId=p.Id	
											Left JOIN(
														SELECT 'Pending Inventory Issue Posting' Category			
														, II.CompanyId,II.PlantId				
														,0 ThreeDaysCount   
																,0 AS FiveDaysCount
																,0 AS TenDaysCount
																,Count(II.Id) FifteenDaysCount
																,0 as TweentyDaysCount
																,0 TwentyFiveyDaysCount
																,0 AS ThirtyDaysCount
																,0 AS GraterThirtyDaysCount
																	,0 AS AllCount
														    ,sum(isnull(IID.Qty,0)) Qty
															,sum(isnull(IID.Rate,0)) Rate
															,(sum(isnull(IID.Qty,0))* sum(isnull(IID.Rate,0))) Total15Value
															FROM trn.InventoryIssue II
															LEFT JOIN (Select InventoryIssueId,
															sum(isnull(TransactionQty,0)) Qty
															,sum(isnull(PolicyRate,0)) Rate
															,sum(isnull(PolicyAmount,0)) Total15Value 
															from trn.InventoryIssueDetail Group by InventoryIssueId) IID ON IID.InventoryIssueId=II.Id	
														Where  DATEDIFF(day,II.IssueDate,getdate()) >=10 AND DATEDIFF(day,II.IssueDate,getdate()) <=15   
														AND II.VoucherId IS null
														GROUP BY II.CompanyId  ,II.PlantId	  

											)Res15 ON Res15.CompanyId=cmp.Id AND Res15.PlantId=p.Id	
											Left JOIN(
														SELECT 'Pending Inventory Issue Posting' Category			
														, II.CompanyId	,II.PlantId			
														,0 ThreeDaysCount   
																,0 AS FiveDaysCount
																,0 AS TenDaysCount
																,0 FifteenDaysCount
																,Count(II.Id) as TweentyDaysCount
																,0 TwentyFiveyDaysCount
																,0 AS ThirtyDaysCount
																,0 AS GraterThirtyDaysCount
																	,0 AS AllCount
														,sum(isnull(IID.Qty,0)) Qty
															,sum(isnull(IID.Rate,0)) Rate
															,(sum(isnull(IID.Qty,0))* sum(isnull(IID.Rate,0))) Total20Value
															FROM trn.InventoryIssue II
															LEFT JOIN (Select InventoryIssueId,
															sum(isnull(TransactionQty,0)) Qty
															,sum(isnull(PolicyRate,0)) Rate
															,sum(isnull(PolicyAmount,0)) Total20Value 
															from trn.InventoryIssueDetail Group by InventoryIssueId) IID ON IID.InventoryIssueId=II.Id	
														Where  DATEDIFF(day,II.IssueDate,getdate()) >=15 AND DATEDIFF(day,II.IssueDate,getdate()) <=20 
														AND II.VoucherId IS null
														GROUP BY II.CompanyId ,II.PlantId	   

											)Res20 ON Res20.CompanyId=cmp.Id AND Res20.PlantId=p.Id	
											Left JOIN(
														SELECT 'Pending Inventory Issue Posting' Category			
														, II.CompanyId	,II.PlantId			
														,0 ThreeDaysCount   
																,0 AS FiveDaysCount
																,0 AS TenDaysCount
																,0 FifteenDaysCount
																,0 as TweentyDaysCount
																,Count(II.Id) TwentyFiveyDaysCount
																,0 AS ThirtyDaysCount
																,0 AS GraterThirtyDaysCount
																	,0 AS AllCount
														,sum(isnull(IID.Qty,0)) Qty
															,sum(isnull(IID.Rate,0)) Rate
															,(sum(isnull(IID.Qty,0))* sum(isnull(IID.Rate,0))) Total25Value
															FROM trn.InventoryIssue II
															LEFT JOIN (Select InventoryIssueId,
															sum(isnull(TransactionQty,0)) Qty
															,sum(isnull(PolicyRate,0)) Rate
															,sum(isnull(PolicyAmount,0)) Total25Value 
															from trn.InventoryIssueDetail Group by InventoryIssueId) IID ON IID.InventoryIssueId=II.Id	
														Where DATEDIFF(day,II.IssueDate,getdate()) >=20 AND DATEDIFF(day,II.IssueDate,getdate()) <=25  
														AND II.VoucherId IS null
														GROUP BY II.CompanyId ,II.PlantId	  
											)Res25 ON Res25.CompanyId=cmp.Id AND Res25.PlantId=p.Id	
											Left JOIN(
														SELECT 'Pending Inventory Issue Posting' Category			
														, II.CompanyId	,II.PlantId			
														,0 ThreeDaysCount   
																,0 AS FiveDaysCount
																,0 AS TenDaysCount
																,0 FifteenDaysCount
																,0 as TweentyDaysCount
																,0 TwentyFiveyDaysCount
																,Count(II.Id)  AS ThirtyDaysCount
																,0 AS GraterThirtyDaysCount
																	,0 AS AllCount
														    ,sum(isnull(IID.Qty,0)) Qty
															,sum(isnull(IID.Rate,0)) Rate
															,(sum(isnull(IID.Qty,0))* sum(isnull(IID.Rate,0))) Total30Value
															FROM trn.InventoryIssue II
															LEFT JOIN (Select InventoryIssueId,
															sum(isnull(TransactionQty,0)) Qty
															,sum(isnull(PolicyRate,0)) Rate
															,sum(isnull(PolicyAmount,0)) Total30Value 
															from trn.InventoryIssueDetail Group by InventoryIssueId) IID ON IID.InventoryIssueId=II.Id		
														Where DATEDIFF(day,II.IssueDate,getdate()) >=25 AND DATEDIFF(day,II.IssueDate,getdate()) <=30
														AND II.VoucherId IS null
														GROUP BY II.CompanyId  ,II.PlantId	 
											)Res30 ON Res30.CompanyId=cmp.Id AND Res30.PlantId=p.Id	
											Left JOIN(
														SELECT 'Pending Inventory Issue Posting' Category			
														, II.CompanyId	,II.PlantId			
														,0 ThreeDaysCount   
																,0 AS FiveDaysCount
																,0 AS TenDaysCount
																,0 FifteenDaysCount
																,0 as TweentyDaysCount
																,0 TwentyFiveyDaysCount
																,0 AS ThirtyDaysCount
																,Count(II.Id)  AS GraterThirtyDaysCount
																	,0 AS AllCount
														,sum(isnull(IID.Qty,0)) Qty
															,sum(isnull(IID.Rate,0)) Rate
															,(sum(isnull(IID.Qty,0))* sum(isnull(IID.Rate,0))) Total31Value
															FROM trn.InventoryIssue II
															LEFT JOIN (Select InventoryIssueId,
															sum(isnull(TransactionQty,0)) Qty
															,sum(isnull(PolicyRate,0)) Rate
															,sum(isnull(PolicyAmount,0)) Total31Value 
															from trn.InventoryIssueDetail Group by InventoryIssueId) IID ON IID.InventoryIssueId=II.Id		
														Where DATEDIFF(day,II.IssueDate,getdate()) >=30 
														AND II.VoucherId IS null
														GROUP BY II.CompanyId ,II.PlantId	  
											)Res31 ON Res31.CompanyId=cmp.Id AND Res31.PlantId=p.Id	

											Left JOIN(
														SELECT 'Pending Inventory Issue Posting' Category			
														, II.CompanyId	,II.PlantId			
														,0 ThreeDaysCount   
																,0 AS FiveDaysCount
																,0 AS TenDaysCount
																,0 FifteenDaysCount
																,0 as TweentyDaysCount
																,0 TwentyFiveyDaysCount
																,0 AS ThirtyDaysCount
																,0  AS GraterThirtyDaysCount
																,Count(II.Id) AS AllCount
															,sum(isnull(IID.Qty,0)) Qty
															,sum(isnull(IID.Rate,0)) Rate
															,(sum(isnull(IID.Qty,0))* sum(isnull(IID.Rate,0))) Total32Value
															FROM trn.InventoryIssue II
															LEFT JOIN (Select InventoryIssueId,
															sum(isnull(TransactionQty,0)) Qty
															,sum(isnull(PolicyRate,0)) Rate
															,sum(isnull(PolicyAmount,0)) Total32Value 
															from trn.InventoryIssueDetail Group by InventoryIssueId) IID ON IID.InventoryIssueId=II.Id		
														Where DATEDIFF(day,II.IssueDate,getdate()) >=0 --AND DATEDIFF(day,II.IssueDate,getdate()) <=9000000000 

														AND II.VoucherId IS null
														GROUP BY II.CompanyId,II.PlantId	   
											)Res32 ON Res32.CompanyId=cmp.Id AND Res32.PlantId=p.Id	
											where cmp.Active =1 and CMPGR.Active = 1 --AND cmp.Id='" + companyId + "' ANd P.Id='" + plantId + @"'
											)as t 
											where PlantId <>'' AND ColumnName1<>'' AND CompanyId='" + companyId + @"'
											order by t.ColumnName1,SI ASC";
                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }
        public IEnumerable<object> InventoryStatusDashboardPlant(IEnumerable<ChartColumnList> ChartColumnList, int seq, string factDate, string fromDate, string toDate, string companyGroupId, string CompanyId, string PlantId, string IsRegular)
        {
            try
            {
                var ValueOrNumber1 = 0;
                if (IsRegular == "False")
                {
                    ValueOrNumber1 = 0;
                }
                else
                {
                    ValueOrNumber1 = 1;
                }
                var sql = @"
                           SELECT DISTINCT CMPGR.Id AS CompanyGroupId
	                        ,CMPGR.UserName AS GroupName
	                        ,cmp.Id AS CompanyId
	                        ,p.Id PlantId
	                        ,isnull((
			                        CASE 
				                        WHEN row_number() OVER (
						                        PARTITION BY P.UserName ORDER BY (
								                        SELECT NULL
								                        )
						                        ) = 1
					                        THEN P.UserName
				                        END
			                        ), '') AS ColumnName
	                        ,isnull(MT.UserName, '') MaterialType
	                        ,Sum(isnull(opbal.TransactionQty, 0) - isnull(IFD3.OpeningIssueQty, 0)) AS OpeningBalance
	                        ,Sum(isnull(opbal.TotalMaterialBooksCurrencyAmount, 0)) AS OpeningBalanceAmount
	                        ,Sum(isnull(opbal2.TransactionQty, 0)) ReceivedForThePeriod
	                        ,Sum(isnull(opbal2.TotalMaterialBooksCurrencyAmount, 0)) AS ReceivedForThePeriodAmount
	                        ,0 ReturnQty
								,0 ReturnAmount
								,Sum(isnull(IFD1.IssueQty,0)) IssueForThePeriod	
								,Sum(isnull(IFD1.PolicyAmount,0)) IssueForThePeriodAmount	
								,0 IssueReturnQty
								,0 IssueReturnAmount
	                        ,Sum((isnull(opbal.TransactionQty, 0) - isnull(IFD3.OpeningIssueQty, 0) + isnull(opbal2.TransactionQty, 0)) - isnull(IFD1.IssueQty, 0)) Closing
	                        ,Sum((isnull(opbal.TotalMaterialBooksCurrencyAmount, 0) + isnull(opbal2.TotalMaterialBooksCurrencyAmount, 0)) - isnull(IFD1.PolicyAmount, 0)) ClosingAmount
                        FROM TRN.InventoryMaterial AS IM
                        LEFT JOIN ORG.CompanyGroup CMPGR ON CMPGR.Id = IM.CompanyGroupId
                        LEFT JOIN org.company CMP ON CMP.CompanyGroupId = IM.CompanyGroupId
                        LEFT JOIN org.Plant p ON P.CompanyId = CMP.Id
                        LEFT JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId = MM.Id
                        LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
                        LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
                        LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
                        LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
                        LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
                        LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
                        LEFT JOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId = IM.Id
                        LEFT JOIN [HKP].[MaterialType] AS MT ON MGM.MaterialTypeId = MT.Id
                        LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId = TUoM.Id
                        LEFT JOIN (
	                        SELECT IRD.InventoryMaterialId
		                        ,IR.CompanyId,IR.PlantId
		                        ,Sum(IRD.TransactionQty) AS TransactionQty
		                        ,Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
	                        FROM [TRN].[InventoryReceiveDetail] IRD
	                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id = IRD.InventoryReceiveId
	                        WHERE convert(DATE, IR.GRNDate) <='" + fromDate + @"' 
	                        GROUP BY IRD.InventoryMaterialId,IR.CompanyId,IR.PlantId 
	
	                        UNION ALL
	
	                        SELECT IRD.InventoryMaterialId
		                        ,IR.CompanyId ,IR.PlantId
		                        ,Sum(IRD.TransactionQty) AS TransactionQty
		                        ,Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
	                        FROM [TRN].[InventoryReceiveDetail] IRD
	                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id = IRD.InventoryReceiveId
	                        WHERE convert(DATE, IR.GRNDate) < '" + fromDate + @"'  
	                        GROUP BY IRD.InventoryMaterialId
		                        ,IR.CompanyId,IR.PlantId
	                        ) AS opbal ON opbal.InventoryMaterialId = IM.Id AND opbal.PlantId=p.Id
                        LEFT JOIN (
	                        SELECT IRD.InventoryMaterialId
		                        ,IR.CompanyId,IR.PlantId
		                        ,Sum(IRD.TransactionQty) AS TransactionQty
		                        ,Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
	                        FROM [TRN].[InventoryReceiveDetail] IRD
	                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id = IRD.InventoryReceiveId
	                        WHERE convert(DATE, IR.GRNDate) > '" + toDate + @"'
	                        GROUP BY IRD.InventoryMaterialId,IR.CompanyId,IR.PlantId
	
	                        UNION ALL
	
	                        SELECT IRD.InventoryMaterialId
		                        ,IR.CompanyId,IR.PlantId
		                        ,Sum(IRD.TransactionQty) AS TransactionQty
		                        ,Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
	                        FROM [TRN].[InventoryReceiveDetail] IRD
	                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id = IRD.InventoryReceiveId
	                        WHERE convert(DATE, IR.GRNDate) = '" + toDate + @"'
	                        GROUP BY IRD.InventoryMaterialId,IR.CompanyId,IR.PlantId
	                        ) AS opbal1 ON opbal1.InventoryMaterialId = IM.Id AND opbal1.PlantId=p.Id
                        LEFT JOIN (
	                        SELECT IRD.InventoryMaterialId
		                        ,IR.CompanyId,IR.PlantId
		                        ,Sum(IRD.TransactionQty) AS TransactionQty
		                        ,Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
	                        FROM [TRN].[InventoryReceiveDetail] IRD
	                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id = IRD.InventoryReceiveId
	                        WHERE convert(DATE, IR.GRNDate) BETWEEN '" + fromDate + @"'
			                        AND '" + toDate + @"'
	                        GROUP BY IRD.InventoryMaterialId
		                        ,IR.CompanyId,IR.PlantId
	                        ) AS opbal2 ON opbal2.InventoryMaterialId = IM.Id AND opbal2.PlantId=p.Id
                        LEFT JOIN (
	                        SELECT IID.InventoryMaterialId
		                        ,II.CompanyId,II.PlantId
		                        ,Sum(IID.TransactionQty) OpeningIssueQty
		                        ,Sum(IID.PolicyAmount) PolicyAmount
	                        FROM TRN.InventoryIssueDetail IID
	                        LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId = II.Id
	                        WHERE convert(DATE, II.IssueDate) < '" + fromDate + @"'  
	                        GROUP BY IID.InventoryMaterialId
		                        ,II.CompanyId,II.PlantId
	                        ) IFD3 ON IFD3.InventoryMaterialId = IM.Id AND IFD3.PlantId=p.Id
                        LEFT JOIN (
	                        SELECT IID.InventoryMaterialId
		                        ,II.CompanyId,II.PlantId
		                        ,Sum(IID.TransactionQty) IssueQty
		                        ,Sum(IID.PolicyAmount) PolicyAmount
	                        FROM TRN.InventoryIssueDetail IID
	                        LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId = II.Id
	                        WHERE convert(DATE, II.IssueDate) = '" + toDate + @"'
	                        GROUP BY IID.InventoryMaterialId
		                        ,II.CompanyId,II.PlantId
	                        ) IFD ON IFD.InventoryMaterialId = IM.Id AND IFD.PlantId=p.Id
                        LEFT JOIN (
	                        SELECT IID.InventoryMaterialId
		                        ,II.CompanyId,II.PlantId
		                        ,Sum(IID.TransactionQty) IssueQty
		                        ,Sum(IID.PolicyAmount) PolicyAmount
	                        FROM TRN.InventoryIssueDetail IID
	                        LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId = II.Id
	                        WHERE convert(DATE, II.IssueDate) BETWEEN '" + fromDate + @"'  
			                        AND '" + toDate + @"'
	                        GROUP BY IID.InventoryMaterialId
		                        ,II.CompanyId,II.PlantId
	                        ) IFD1 ON IFD1.InventoryMaterialId = IM.Id AND IFD1.PlantId=p.Id                      
	                
                        WHERE p.Id <> ''
	                        AND P.UserName <> ''
	                        AND isnull(MT.UserName, '') <> ''
	                        --AND isnull(opbal2.TransactionQty, 0) > 0
							AND IM.CompanyId = '" + CompanyId + @"'
                        AND MM.IsRegular='" + ValueOrNumber1 + @"'
                        GROUP BY CMPGR.Id
	                        ,CMPGR.UserName
	                        ,cmp.Id
	                        ,p.Id
	                        ,P.UserName
	                        ,isnull(MT.UserName, '') 
";
                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }


        public IEnumerable<object> MaterialAgeingDashboardPlant(IEnumerable<ChartColumnList> ChartColumnList, int seq, string factDate, string fromDate, string toDate, string companyGroupId, string CompanyId, string PlantId, string IsRegular)
        {
            try
            {
                var ValueOrNumber1 = 0;
                if (IsRegular == "False")
                {
                    ValueOrNumber1 = 0;
                }
                else
                {
                    ValueOrNumber1 = 1;
                }


                var sql = @"SELECT 
					CompanyGroupId
	                ,GroupName
	                ,CompanyId
					,PlantId

	                ,isnull((CASE WHEN row_number() OVER (PARTITION BY PlantName ORDER BY (SELECT NULL)) = 1THEN PlantName END), '') AS ColumnName
	                --,Category
	                ,MaterialType,IsRegular
	                ,sum(isnull(ThirtyDaysCount, 0)) ThirtyDaysCount
	                ,sum(isnull(Total30Value, 0)) Total30Value
	                ,sum(isnull(FourtyfiveDaysCount, 0)) FourtyfiveDaysCount
	                ,sum(isnull(Total45Value, 0)) Total45Value
	                ,sum(isnull(SixtyDaysCount, 0)) SixtyDaysCount
	                ,sum(isnull(Total60Value, 0)) Total60Value
	                ,sum(isnull(HundredtwentyDaysCount, 0)) HundredtwentyDaysCount
	                ,sum(isnull(Total120Value, 0)) Total120Value
	                ,sum(isnull(ThreeHundredSixtyfiveDaysCount, 0)) ThreeHundredSixtyfiveDaysCount
	                ,sum(isnull(Total365Value, 0)) Total365Value
	                ,sum(isnull(Transaction365QtyGrt, 0)) Transaction365QtyGrt
	                ,sum(isnull(Total366Value, 0)) Total366Value
                FROM (
	                SELECT  CMPGR.Id AS CompanyGroupId
		                ,CMPGR.UserName AS GroupName
		                ,cmp.Id AS CompanyId
		                ,CMP.UserName AS ColumnName
		                ,Res30.MaterialType
		                ,Res30.IsRegular
						, P.Id PlantId
						, P.UserName PlantName
		                --,'Pending Req' Category
		                ,isnull(Res30.ThirtyDaysCount, 0) ThirtyDaysCount
		                ,isnull(Res30.Total30Value, 0) Total30Value
		                ,isnull(Res45.FourtyfiveDaysCount, 0) FourtyfiveDaysCount
		                ,isnull(Res45.Total45Value, 0) Total45Value
		                ,isnull(Res60.SixtyDaysCount, 0) SixtyDaysCount
		                ,isnull(Res60.Total60Value, 0) Total60Value
		                ,isnull(Res120.HundredtwentyDaysCount, 0) HundredtwentyDaysCount
		                ,isnull(Res120.Total120Value, 0) Total120Value
		                ,isnull(Res365.ThreeHundredSixtyfiveDaysCount, 0) ThreeHundredSixtyfiveDaysCount
		                ,isnull(Res365.Total365Value, 0) Total365Value
		                ,isnull(Res366.Transaction365QtyGrt, 0) Transaction365QtyGrt
		                ,isnull(Res366.Total366Value, 0) Total366Value
	                FROM ORG.CompanyGroup CMPGR
	                LEFT JOIN org.company CMP ON CMP.CompanyGroupId = CMPGR.Id
					 LEFT JOIN org.Plant p on P.CompanyId=CMP.Id
	                LEFT JOIN (
		                SELECT DISTINCT CMPGR.Id AS CompanyGroupId
			                ,CMPGR.UserName AS GroupName
			                ,cmp.Id AS CompanyId	
			                ,mm.IsRegular IsRegular
					        ,IR.PlantId
			                ,isnull(MT.UserName, '') MaterialType
			                ,sum(IRD.TransactionQty) ThirtyDaysCount
			                ,0 FourtyfiveDaysCount
			                ,0 SixtyDaysCount
			                ,0 HundredtwentyDaysCount
			                ,0 ThreeHundredSixtyfiveDaysCount
			                ,0 Transaction365QtyGrt
			                ,sum(IRD.TotalMaterialBooksCurrencyAmount) Total30Value
			                ,0 Total45Value
			                ,0 Total60Value
			                ,0 Total120Value
			                ,0 Total365Value
			                ,0 Total366Value
		                FROM TRN.InventoryMaterial AS IM
		                LEFT JOIN ORG.CompanyGroup CMPGR ON CMPGR.Id = IM.CompanyGroupId
		                LEFT JOIN org.company CMP ON CMP.CompanyGroupId = IM.CompanyGroupId
		                LEFT JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId = MM.Id
		                LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
		                LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
		                LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
		                LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
		                LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
		                LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
		                LEFT JOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId = IM.Id
		                LEFT JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId = IR.Id
		                LEFT JOIN [HKP].[MaterialType] AS MT ON MGM.MaterialTypeId = MT.Id
		                LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId = TUoM.Id
		                WHERE DATEDIFF(day, IR.GRNDate, getdate()) > 0
			                AND DATEDIFF(day, IR.GRNDate, getdate()) <= 30
			                AND MT.UserName <> ''
			                  AND MM.IsRegular='" + ValueOrNumber1 + @"'
		                GROUP BY CMPGR.Id
			                ,CMPGR.UserName
			                ,cmp.Id
			                ,CMP.UserName
							,isnull(MT.UserName, '')
							,IR.PlantId
			                ,isnull(MT.UserName, '')
							,mm.IsRegular
		                ) Res30 ON Res30.CompanyId = cmp.Id ANd Res30.PlantId = p.Id
	                LEFT JOIN (
		                --select 'Pending Req' Category
		               SELECT 
			            
			                IR.CompanyId	
			                ,mm.IsRegular IsRegular	
							,IR.PlantId
			                
			                ,isnull(MT.UserName, '') MaterialType
			                ,sum(IRD.TransactionQty) FourtyfiveDaysCount
			                ,0 ThirtyDaysCount
			                ,0 SixtyDaysCount
			                ,0 HundredtwentyDaysCount
			                ,0 ThreeHundredSixtyfiveDaysCount
			                ,0 Transaction365QtyGrt
			                ,sum(IRD.TotalMaterialBooksCurrencyAmount) Total45Value
			                ,0 Total30Value
			                ,0 Total60Value
			                ,0 Total120Value
			                ,0 Total365Value
			                ,0 Total366Value
		                FROM TRN.InventoryMaterial AS IM
		                LEFT JOIN ORG.CompanyGroup CMPGR ON CMPGR.Id = IM.CompanyGroupId
		                LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId = IM.id
		                LEFT JOIN org.company CMP ON CMP.CompanyGroupId = IM.CompanyGroupId
		                LEFT JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId = MM.Id
		                LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
		                LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
		                LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
		                LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
		                LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
		                LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
		                LEFT JOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId = IM.Id
		                LEFT JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId = IR.Id
		                LEFT JOIN [HKP].[MaterialType] AS MT ON MGM.MaterialTypeId = MT.Id
		                LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId = TUoM.Id
		                WHERE DATEDIFF(day, IR.GRNDate, getdate()) > 30
			                AND DATEDIFF(day, IR.GRNDate, getdate()) <= 45
			                AND MT.UserName <> ''
			                   AND MM.IsRegular='" + ValueOrNumber1 + @"'
		                GROUP BY IR.CompanyId				                
			                ,isnull(MT.UserName, '')
							,mm.IsRegular
							,IR.PlantId
		                ) Res45 ON Res45.CompanyId = cmp.Id ANd Res45.PlantId = p.Id
	                LEFT JOIN (
		                --select 'Pending Req' Category
		                SELECT  
						IR.CompanyId
			           ,mm.IsRegular IsRegular	
			          ,IR.PlantId	
			                ,isnull(MT.UserName, '') MaterialType
			                ,sum(IRD.TransactionQty) SixtyDaysCount
			                ,0 ThirtyDaysCount
			                ,0 FourtyfiveDaysCount
			                ,0 HundredtwentyDaysCount
			                ,0 ThreeHundredSixtyfiveDaysCount
			                ,0 Transaction365QtyGrt
			                ,sum(IRD.TotalMaterialBooksCurrencyAmount) Total60Value
			                ,0 Total30Value
			                ,0 Total45Value
			                ,0 Total120Value
			                ,0 Total365Value
			                ,0 Total366Value
		                FROM TRN.InventoryMaterial AS IM
		                LEFT JOIN ORG.CompanyGroup CMPGR ON CMPGR.Id = IM.CompanyGroupId
		                LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId = IM.id
		                LEFT JOIN org.company CMP ON CMP.CompanyGroupId = IM.CompanyGroupId
		                LEFT JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId = MM.Id
		                LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
		                LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
		                LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
		                LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
		                LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
		                LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
		                LEFT JOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId = IM.Id
		                LEFT JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId = IR.Id
		                LEFT JOIN [HKP].[MaterialType] AS MT ON MGM.MaterialTypeId = MT.Id
		                LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId = TUoM.Id
		                WHERE DATEDIFF(day, IR.GRNDate, getdate()) > 60
			                AND DATEDIFF(day, IR.GRNDate, getdate()) <= 120
			                AND MT.UserName <> ''
			              AND MM.IsRegular='" + ValueOrNumber1 + @"'
							 GROUP BY IR.CompanyId		
							,IR.PlantId		                
			                ,isnull(MT.UserName, '')
							,mm.IsRegular
		                ) Res60 ON Res60.CompanyId = cmp.Id ANd Res60.PlantId = p.Id
	                LEFT JOIN (
		                --select 'Pending Req' Category
		                SELECT 
						IR.CompanyId
			           ,mm.IsRegular IsRegular	
			          ,IR.PlantId	
			               
			                ,isnull(MT.UserName, '') MaterialType
			                ,sum(IRD.TransactionQty) HundredtwentyDaysCount
			                ,0 ThirtyDaysCount
			                ,0 FourtyfiveDaysCount
			                ,0 SixtyDaysCount
			                ,0 ThreeHundredSixtyfiveDaysCount
			                ,0 Transaction365QtyGrt
			                ,sum(IRD.TotalMaterialBooksCurrencyAmount) Total120Value
			                ,0 Total30Value
			                ,0 Total45Value
			                ,0 Total60Value
			                ,0 Total365Value
			                ,0 Total366Value
		                FROM TRN.InventoryMaterial AS IM
		                LEFT JOIN ORG.CompanyGroup CMPGR ON CMPGR.Id = IM.CompanyGroupId
		                LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId = IM.id
		                LEFT JOIN org.company CMP ON CMP.CompanyGroupId = IM.CompanyGroupId
		                LEFT JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId = MM.Id
		                LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
		                LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
		                LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
		                LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
		                LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
		                LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
		                LEFT JOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId = IM.Id
		                LEFT JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId = IR.Id
		                LEFT JOIN [HKP].[MaterialType] AS MT ON MGM.MaterialTypeId = MT.Id
		                LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId = TUoM.Id
		                WHERE DATEDIFF(day, IR.GRNDate, getdate()) > 60
			                AND DATEDIFF(day, IR.GRNDate, getdate()) <= 120
			                AND MT.UserName <> ''
			                   AND MM.IsRegular='" + ValueOrNumber1 + @"'
		                	 GROUP BY IR.CompanyId		
							,IR.PlantId		                
			                ,isnull(MT.UserName, '')
							,mm.IsRegular
		                ) Res120 ON Res120.CompanyId = cmp.Id ANd Res120.PlantId = p.Id
	                LEFT JOIN (
		                --select 'Pending Req' Category
		                SELECT 
						IR.CompanyId
			           ,mm.IsRegular IsRegular	
			          ,IR.PlantId	
			                ,isnull(MT.UserName, '') MaterialType
			                ,sum(IRD.TransactionQty) ThreeHundredSixtyfiveDaysCount
			                ,0 ThirtyDaysCount
			                ,0 FourtyfiveDaysCount
			                ,0 SixtyDaysCount
			                ,0 HundredtwentyDaysCount
			                ,0 Transaction365QtyGrt
			                ,sum(IRD.TotalMaterialBooksCurrencyAmount) Total365Value
			                ,0 Total30Value
			                ,0 Total45Value
			                ,0 Total60Value
			                ,0 Total120Value
			                ,0 Total366Value
		                FROM TRN.InventoryMaterial AS IM
		                LEFT JOIN ORG.CompanyGroup CMPGR ON CMPGR.Id = IM.CompanyGroupId
		                LEFT JOIN org.company CMP ON CMP.CompanyGroupId = IM.CompanyGroupId
		                LEFT JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId = MM.Id
		                LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
		                LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
		                LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
		                LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
		                LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
		                LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
		                LEFT JOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId = IM.Id
		                LEFT JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId = IR.Id
		                LEFT JOIN [HKP].[MaterialType] AS MT ON MGM.MaterialTypeId = MT.Id
		                LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId = TUoM.Id
		                WHERE DATEDIFF(day, IR.GRNDate, getdate()) > 120
			                AND DATEDIFF(day, IR.GRNDate, getdate()) <= 365
			                AND MT.UserName <> ''
			                  AND MM.IsRegular='" + ValueOrNumber1 + @"'
		               GROUP BY IR.CompanyId		
							,IR.PlantId		                
			                ,isnull(MT.UserName, '')
							,mm.IsRegular
		                ) Res365 ON Res365.CompanyId = cmp.Id ANd Res365.PlantId = p.Id
	                LEFT JOIN (
		                --select 'Pending Req' Category
		                SELECT 
						IR.CompanyId
			           ,mm.IsRegular IsRegular	
			          ,IR.PlantId	
			                ,isnull(MT.UserName, '') MaterialType
			                ,sum(IRD.TransactionQty) ThreeHundredSixtyfiveDaysCount
			                ,0 ThirtyDaysCount
			                ,0 FourtyfiveDaysCount
			                ,0 SixtyDaysCount
			                ,0 HundredtwentyDaysCount
			                ,0 Transaction365QtyGrt
			                ,sum(IRD.TotalMaterialBooksCurrencyAmount) Total365Value
			                ,0 Total30Value
			                ,0 Total45Value
			                ,0 Total60Value
			                ,0 Total120Value
			                ,0 Total366Value
		                FROM TRN.InventoryMaterial AS IM
		                LEFT JOIN ORG.CompanyGroup CMPGR ON CMPGR.Id = IM.CompanyGroupId
		                LEFT JOIN trn.MaterialRequsitionDetails MRD ON MRD.MaterialReqqusitionMasterId = IM.id
		                LEFT JOIN org.company CMP ON CMP.CompanyGroupId = IM.CompanyGroupId
		                LEFT JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId = MM.Id
		                LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
		                LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
		                LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
		                LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
		                LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
		                LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
		                LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
		                LEFT JOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId = IM.Id
		                LEFT JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId = IR.Id
		                LEFT JOIN [HKP].[MaterialType] AS MT ON MGM.MaterialTypeId = MT.Id
		                LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId = TUoM.Id
		                WHERE DATEDIFF(day, IR.GRNDate, getdate()) > 365
			                AND DATEDIFF(day, IR.GRNDate, getdate()) <= 9000000
			                AND MT.UserName <> ''
			                 AND MM.IsRegular='" + ValueOrNumber1 + @"'
		               GROUP BY IR.CompanyId		
							,IR.PlantId		                
			                ,isnull(MT.UserName, '')
							,mm.IsRegular
		                ) Res366 ON Res366.CompanyId = cmp.Id ANd Res366.PlantId = p.Id
	                WHERE cmp.Active = 1 AND CMPGR.Active = 1 
		                )t	
	                where  IsRegular='" + ValueOrNumber1 + @"' AND CompanyId='" + CompanyId + @"'
		                GROUP BY
					CompanyGroupId, 
	                GroupName
	                ,CompanyId
					,PlantId
					, PlantName
	                ,MaterialType,IsRegular";
                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
