                                        LEFT JOIN MST.BudgetMaster AS BM ON BM.Id = EVD.BudgetMasterId

                                        LEFT JOIN HKP.BudgetCategory AS BC ON BC.Id = BM.BudgetCategoryId

                                        LEFT JOIN HKP.BudgetSubCategory AS BSC ON BSC.Id = BM.BudgetSubCategoryId

                                        LEFT JOIN HKP.Budget AS B ON B.Id = BM.BudgetId

                                        LEFT JOIN HKP.GLGeneralInfo AS GL ON GL.Id = BM.GLGeneralInfoId

                                        LEFT JOIN HKP.AccountGroup AS AG ON AG.Id = GL.AccountGroupId

                                        LEFT JOIN HKP.AccountType AS ACT ON ACT.Id = AG.AccountTypeId

                                        LEFT JOIN ORG.Entity AS ENT ON ENT.Id = V.EntityId

                                        LEFT JOIN(SELECT Id AS EntryPeriodId, PeriodName, StartDate, EndDate FROM SCS.FiscalYearPeriod)

                                                    AS FYPA ON MONTH(CONVERT(DATE, FYPA.EndDate)) = MONTH(CONVERT(DATE, evd.AddedDate))

                                            AND YEAR(CONVERT(DATE, FYPA.EndDate))= YEAR(CONVERT(DATE, evd.AddedDate))

                                        WHERE V.CompanyGroupId = '" + companyGroupId + @"'  AND V.PostingDate BETWEEN (SELECT  StartDate FROM SCS.FiscalYearPeriod where '" + calculatedFromDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + calculatedToDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate) AND V.IsPark = 0 

                                        AND ACT.IsBalanceSheet = 0  AND ACT.Id IN ('Revenue')

                                          GROUP BY EFYP.Id , EFYP.PeriodName,  FYPA.PeriodName, FYPA.EndDate,EFYP.EndDate,FYPA.EntryPeriodId ,ACT.BalanceType
								    ) periodWiseExp

                            GROUP by periodWiseExp.PostingPeriod,periodWiseExp.PostingPeriodId, periodWiseExp.EntryPeriod,periodWiseExp.EntryPeriodId,
                            periodWiseExp.EntryPeriodEndDate, periodWiseExp.PostingPeriodEndDate
                       ) periodWiseExp
									ON periodWiseExp." + periodId + @" = FiscalYear.Id )";
                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }

        public IEnumerable<object> DynamicPeriodWiseRevenueBarChart(IEnumerable<ChartColumnList> ChartColumnList, int seq, string factDate, string fromDate, string toDate, string companyGroupId, string companyId)
        {
            var cList = string.Empty;
            var cListId = string.Empty;
            var join = string.Empty;
            var wc = string.Empty;
            var cListextG = string.Empty;
            var cListextIdG = string.Empty;
            //string expFactDate = string.Empty;
            try
            {
                var expFactDate = string.Empty;
                var condition = string.Empty;
                var grpFactDate = string.Empty;
                var daysOfMonth = DateTime.DaysInMonth(Convert.ToDateTime(toDate).Year, Convert.ToDateTime(toDate).Month);

                DateTime calculatedToDate = new DateTime(Convert.ToDateTime(toDate).Year, Convert.ToDateTime(toDate).Month, daysOfMonth);

                DateTime calculatedFromDate = calculatedToDate.AddMonths(-12);
                var periodId = "";

                if (factDate == "postingDate")
                {
                    expFactDate = "Replace(CONVERT(VARCHAR(11),V.PostingDate,6),' ','-') factDate,";
                    condition = "AND V.PostingDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    grpFactDate = "V.PostingDate";
                    periodId = "PostingPeriodId";
                }
                else if (factDate == "AddedDate")
                {
                    expFactDate = "Replace(CONVERT(VARCHAR(11),V.AddedDate,6),' ','-') factDate,";
                    condition = "AND V.AddedDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    grpFactDate = "V.AddedDate";
                    periodId = "EntryPeriodId";

                }
                seq += 1;
                foreach (var item in ChartColumnList)
                {
                    if (item.Sequence != -2 && item.Sequence != -1)
                    {
                        if (item.Sequence <= seq)
                        {
                            if (item.RType == "Entity")
                            {
                                cList = "," + item.StandardName + ".UserName";
                                cListId = "," + item.StandardName + ".Id";
                                //cListextG = "," + item.ColumnName + "Name";
                                //cListextIdG = "," + item.ColumnName + "Id";
                                if (item.ColumnName == "EmployeeGroup")
                                {
                                    join += "LEFT JOIN [HKP].[" + item.StandardName + "] ON " + item.StandardName + ".Id = ENT." + item.StandardName + "Id\n";
                                }
                                else
                                {
                                    join += "LEFT JOIN [ORG].[" + item.StandardName + "] ON " + item.StandardName + ".Id = ENT." + item.StandardName + "Id\n";
                                }
                            }
                            else
                            {
                                cList = "," + item.StandardName + ".UserName";
                                join += "LEFT JOIN [ORG].[" + item.StandardName + "] ON " + item.StandardName + ".Id = Po." + item.StandardName + "Id\n";
                            }
                        }
                    }
                    if (item.Sequence != -2)
                    {
                        if (item.Sequence == -1)
                        {
                            wc = "  AND CMP.Id ='" + item.Id + "'";
                        }
                        else
                        {
                            if (item.Sequence < seq)
                            {
                                wc += " and " + item.StandardName + ".Id='" + item.Text + "'";
                            }
                        }
                    }
                }
                var sql = @"SELECT ISNULL(Amount,0) Amount, ISNULL(BudgetAmount,0) BudgetAmount
								,FiscalYear.PeriodName PostingPeriod,
                                FiscalYear.Id PostingPeriodId			
								 FROM				
									  (
                                     (SELECT * FROM SCS.FiscalYearPeriod WHERE
									   StartDate BETWEEN (SELECT  StartDate FROM SCS.FiscalYearPeriod where '" + calculatedFromDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + calculatedToDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)
									  ) FiscalYear
									  Left join 
                                    (SELECT
                                         SUM(AnnualBudgetDetail.StandardAmount) BudgetAmount
								        , EFYP.PeriodName PostingPeriod,
                                        EFYP.Id PostingPeriodId
                                        , EFYP.EndDate PostingPeriodEndDate
									     ,    cmp.Id AS CompanyId
								           	" + cList + @" AS ColumnName
									         " + cListId + @" AS UId
									     FROM
										 MST.AnnualBudgetDetail AS AnnualBudgetDetail	
										 Left join SCS.FiscalYearPeriod AS EFYP  ON EFYP.Id = AnnualBudgetDetail.FiscalYearPeriodId
										
										LEFT JOIN  MST.AnnualBudget AS AnnualBudget ON AnnualBudget.Id = AnnualBudgetDetail.AnnualBudgetId
                                        Left JOIN MST.BudgetMaster AS BM ON BM.Id = AnnualBudgetDetail.BudgetMasterId
                                        LEFT JOIN ORG.Company AS CMP ON CMP.Id = AnnualBudget.CompanyId

                                        LEFT JOIN HKP.BudgetCategory AS BC ON BC.Id = BM.BudgetCategoryId

                                        LEFT JOIN HKP.BudgetSubCategory AS BSC ON BSC.Id = BM.BudgetSubCategoryId

                                        LEFT JOIN HKP.GLGeneralInfo AS GL ON GL.Id = BM.GLGeneralInfoId

                                        LEFT JOIN HKP.AccountGroup AS AG ON AG.Id = GL.AccountGroupId

                                        LEFT JOIN HKP.AccountType AS ACT ON ACT.Id = AG.AccountTypeId

                                        LEFT JOIN ORG.Entity AS ENT ON ENT.Id = AnnualBudgetDetail.EntityId       
                                        " + join + @"

                                        WHERE AnnualBudgetDetail.CompanyGroupId = '" + companyGroupId + @"'  AND EFYP.StartDate BETWEEN (SELECT  StartDate FROM SCS.FiscalYearPeriod where '" + calculatedFromDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + calculatedToDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)

                                        AND ACT.IsBalanceSheet = 0  AND ACT.Id IN ('Revenue') " + wc + @"

                                          GROUP BY EFYP.Id , EFYP.PeriodName,EFYP.Id,EFYP.EndDate 	" + cList + @"  " + cListId + @", cmp.Id
								    ) periodWiseExpBudget ON FiscalYear.Id = periodWiseExpBudget.PostingPeriodId

                                    LEFT JOIN
                                    (SELECT SUM(CASE WHEN ISNULL(DRcumulative,0)= 0 THEN periodWiseExp.CRcumulative ELSE periodWiseExp.DRcumulative END) Amount, periodWiseExp.PostingPeriod,
                                periodWiseExp.PostingPeriodId, periodWiseExp.EntryPeriod,periodWiseExp.EntryPeriodId, periodWiseExp.EntryPeriodEndDate
								,periodWiseExp.PostingPeriodEndDate FROM
                                  (SELECT
                                        
                                          DRcumulative = CASE WHEN ACT.BalanceType = 'Debit' THEN SUM(VDC.DrAmount)-SUM(VDC.CrAmount) ELSE 0 END
								        , CRcumulative = CASE WHEN ACT.BalanceType = 'Credit' THEN SUM(VDC.crAmount)-SUM(VDC.DrAmount) ELSE 0 END
								        , EFYP.PeriodName PostingPeriod,
                                        EFYP.Id PostingPeriodId, FYPA.PeriodName AS EntryPeriod,FYPA.EntryPeriodId, FYPA.EndDate EntryPeriodEndDate
                                        , EFYP.EndDate PostingPeriodEndDate
                                            , cmp.Id AS CompanyId

                                               " + cList + @" AS ColumnName

                                             " + cListId + @" AS UId

                                        FROM TRN.VoucherDetailCurrency AS VDC
                                        LEFT JOIN TRN.VoucherDetail AS EVD ON EVD.Id = VDC.VoucherDetailId
                                        LEFT JOIN TRN.Voucher AS V ON V.Id = EVD.VoucherId
                                        LEFT JOIN ORG.Company AS CMP ON CMP.Id = V.CompanyId
                                        LEFT JOIN SCS.FiscalYearPeriod AS EFYP ON EFYP.Id = EVD.FiscalYearPeriodId

                                        LEFT JOIN MST.BudgetMaster AS BM ON BM.Id = EVD.BudgetMasterId

                                        LEFT JOIN HKP.BudgetCategory AS BC ON BC.Id = BM.BudgetCategoryId

                                        LEFT JOIN HKP.BudgetSubCategory AS BSC ON BSC.Id = BM.BudgetSubCategoryId

                                        LEFT JOIN HKP.Budget AS B ON B.Id = BM.BudgetId

                                        LEFT JOIN HKP.GLGeneralInfo AS GL ON GL.Id = BM.GLGeneralInfoId

                                        LEFT JOIN HKP.AccountGroup AS AG ON AG.Id = GL.AccountGroupId

                                        LEFT JOIN HKP.AccountType AS ACT ON ACT.Id = AG.AccountTypeId

                                        LEFT JOIN ORG.Entity AS ENT ON ENT.Id = V.EntityId
                                        " + join + @"

                                        LEFT JOIN(SELECT Id AS EntryPeriodId, PeriodName, StartDate, EndDate FROM SCS.FiscalYearPeriod)

                                                    AS FYPA ON MONTH(CONVERT(DATE, FYPA.EndDate)) = MONTH(CONVERT(DATE, evd.AddedDate))

                                            AND YEAR(CONVERT(DATE, FYPA.EndDate))= YEAR(CONVERT(DATE, evd.AddedDate))

                                        WHERE V.CompanyGroupId = '" + companyGroupId + @"'  AND V.PostingDate BETWEEN(SELECT StartDate FROM SCS.FiscalYearPeriod where '" + calculatedFromDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + calculatedToDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate) AND V.IsPark = 0

                                        AND ACT.IsBalanceSheet = 0  AND ACT.Id IN('Revenue') " + wc + @"

                                          GROUP BY EFYP.Id , EFYP.PeriodName,  FYPA.PeriodName, FYPA.EndDate,EFYP.EndDate,FYPA.EntryPeriodId ,ACT.BalanceType, cmp.Id
                                            " + cList + @"  " + cListId + @"
								    ) periodWiseExp

                            GROUP by periodWiseExp.PostingPeriod,periodWiseExp.PostingPeriodId, periodWiseExp.EntryPeriod,periodWiseExp.EntryPeriodId,
                            periodWiseExp.EntryPeriodEndDate, periodWiseExp.PostingPeriodEndDate
                       ) periodWiseExp
                                    ON periodWiseExp." + periodId + @" = FiscalYear.Id )";
                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }

        public IEnumerable<object> DynamicPeriodWiseExpenseBarChart(IEnumerable<ChartColumnList> ChartColumnList, int seq, string factDate, string fromDate, string toDate, string companyGroupId, string companyId)
        {
            var cList = string.Empty;
            var cListId = string.Empty;
            var join = string.Empty;
            var wc = string.Empty;
            var cListextG = string.Empty;
            var cListextIdG = string.Empty;
            //string expFactDate = string.Empty;
            try
            {
                var expFactDate = string.Empty;
                var condition = string.Empty;
                var grpFactDate = string.Empty;
                var daysOfMonth = DateTime.DaysInMonth(Convert.ToDateTime(toDate).Year, Convert.ToDateTime(toDate).Month);

                DateTime calculatedToDate = new DateTime(Convert.ToDateTime(toDate).Year, Convert.ToDateTime(toDate).Month, daysOfMonth);

                DateTime calculatedFromDate = calculatedToDate.AddMonths(-12);
                var periodId = "";
                if (factDate == "postingDate")
                {
                    expFactDate = "Replace(CONVERT(VARCHAR(11),V.PostingDate,6),' ','-') factDate,";
                    condition = "AND V.PostingDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    grpFactDate = "V.PostingDate";
                    periodId = "PostingPeriodId";
                }
                else if (factDate == "AddedDate")
                {
                    expFactDate = "Replace(CONVERT(VARCHAR(11),V.AddedDate,6),' ','-') factDate,";
                    condition = "AND V.AddedDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    grpFactDate = "V.AddedDate";
                    periodId = "EntryPeriodId";

                }
                seq += 1;
                foreach (var item in ChartColumnList)
                {
                    if (item.Sequence != -2 && item.Sequence != -1)
                    {
                        if (item.Sequence <= seq)
                        {
                            if (item.RType == "Entity")
                            {
                                cList = "," + item.StandardName + ".UserName";
                                cListId = "," + item.StandardName + ".Id";
                                //cListextG = "," + item.ColumnName + "Name";
                                //cListextIdG = "," + item.ColumnName + "Id";
                                if (item.ColumnName == "EmployeeGroup")
                                {
                                    join += "LEFT JOIN [HKP].[" + item.StandardName + "] ON " + item.StandardName + ".Id = ENT." + item.StandardName + "Id\n";
                                }
                                else
                                {
                                    join += "LEFT JOIN [ORG].[" + item.StandardName + "] ON " + item.StandardName + ".Id = ENT." + item.StandardName + "Id\n";
                                }
                            }
                            else
                            {
                                cList = "," + item.StandardName + ".UserName";
                                join += "LEFT JOIN [ORG].[" + item.StandardName + "] ON " + item.StandardName + ".Id = Po." + item.StandardName + "Id\n";
                            }
                        }
                    }
                    if (item.Sequence != -2)
                    {
                        if (item.Sequence == -1)
                        {
                            wc = "  AND CMP.Id ='" + item.Id + "'";
                        }
                        else
                        {
                            if (item.Sequence < seq)
                            {
                                wc += " and " + item.StandardName + ".Id='" + item.Text + "'";
                            }
                        }
                    }
                }
                var sql = @"SELECT ISNULL(Amount,0) Amount, ISNULL(BudgetAmount,0) BudgetAmount
										,FiscalYear.PeriodName PostingPeriod,
                                FiscalYear.Id PostingPeriodId				
								 FROM				
									  (
                                     (SELECT * FROM SCS.FiscalYearPeriod WHERE
									   StartDate BETWEEN (SELECT  StartDate FROM SCS.FiscalYearPeriod where '" + calculatedFromDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + calculatedToDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)
									  ) FiscalYear
									  Left join 
                                    (SELECT
                                         SUM(AnnualBudgetDetail.StandardAmount) BudgetAmount
								        , EFYP.PeriodName PostingPeriod,
                                        EFYP.Id PostingPeriodId
                                        , EFYP.EndDate PostingPeriodEndDate
									     ,    cmp.Id AS CompanyId
								           	" + cList + @" AS ColumnName
									         " + cListId + @" AS UId
									     FROM
										 MST.AnnualBudgetDetail AS AnnualBudgetDetail	
										 Left join SCS.FiscalYearPeriod AS EFYP  ON EFYP.Id = AnnualBudgetDetail.FiscalYearPeriodId
										
										LEFT JOIN  MST.AnnualBudget AS AnnualBudget ON AnnualBudget.Id = AnnualBudgetDetail.AnnualBudgetId
                                        Left JOIN MST.BudgetMaster AS BM ON BM.Id = AnnualBudgetDetail.BudgetMasterId

                                        LEFT JOIN ORG.Company AS CMP ON CMP.Id = AnnualBudget.CompanyId

                                        LEFT JOIN HKP.BudgetCategory AS BC ON BC.Id = BM.BudgetCategoryId

                                        LEFT JOIN HKP.BudgetSubCategory AS BSC ON BSC.Id = BM.BudgetSubCategoryId

                                        LEFT JOIN HKP.GLGeneralInfo AS GL ON GL.Id = BM.GLGeneralInfoId

                                        LEFT JOIN HKP.AccountGroup AS AG ON AG.Id = GL.AccountGroupId

                                        LEFT JOIN HKP.AccountType AS ACT ON ACT.Id = AG.AccountTypeId

                                        LEFT JOIN ORG.Entity AS ENT ON ENT.Id = AnnualBudgetDetail.EntityId   
                                        --LEFT JOIN ORG.Position AS PO ON PO.Id = AnnualBudgetDetail.       

                                        " + join + @"

                                        WHERE AnnualBudgetDetail.CompanyGroupId = '" + companyGroupId + @"'  AND EFYP.StartDate BETWEEN (SELECT  StartDate FROM SCS.FiscalYearPeriod where '" + calculatedFromDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + calculatedToDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)

                                        AND ACT.IsBalanceSheet = 0  AND ACT.Id IN ('Expense') " + wc + @"

                                          GROUP BY EFYP.Id , EFYP.PeriodName,EFYP.Id,EFYP.EndDate " + cList + @"  " + cListId + @", cmp.Id
								    ) periodWiseExpBudget ON FiscalYear.Id = periodWiseExpBudget.PostingPeriodId

                                    left join
                                    (SELECT SUM(CASE WHEN ISNULL(DRcumulative,0)= 0 THEN periodWiseExp.CRcumulative ELSE periodWiseExp.DRcumulative END) Amount, periodWiseExp.PostingPeriod,
                                periodWiseExp.PostingPeriodId, periodWiseExp.EntryPeriod,periodWiseExp.EntryPeriodId, periodWiseExp.EntryPeriodEndDate
								,periodWiseExp.PostingPeriodEndDate FROM
                                  (SELECT
                                        
                                          DRcumulative = CASE WHEN ACT.BalanceType = 'Debit' THEN SUM(VDC.DrAmount)-SUM(VDC.CrAmount) ELSE 0 END
								        , CRcumulative = CASE WHEN ACT.BalanceType = 'Credit' THEN SUM(VDC.crAmount)-SUM(VDC.DrAmount) ELSE 0 END
								        , EFYP.PeriodName PostingPeriod,
                                        EFYP.Id PostingPeriodId, FYPA.PeriodName AS EntryPeriod,FYPA.EntryPeriodId, FYPA.EndDate EntryPeriodEndDate
                                        , EFYP.EndDate PostingPeriodEndDate
                                        , cmp.Id AS CompanyId

                                               " + cList + @" AS ColumnName

                                             " + cListId + @" AS UId

                                        FROM TRN.VoucherDetailCurrency AS VDC
                                        LEFT JOIN TRN.VoucherDetail AS EVD ON EVD.Id = VDC.VoucherDetailId
                                        LEFT JOIN TRN.Voucher AS V ON V.Id = EVD.VoucherId
                                        LEFT JOIN ORG.Company AS CMP ON CMP.Id = V.CompanyId


                                        LEFT JOIN SCS.FiscalYearPeriod AS EFYP ON EFYP.Id = EVD.FiscalYearPeriodId

                                        LEFT JOIN MST.BudgetMaster AS BM ON BM.Id = EVD.BudgetMasterId

                                        LEFT JOIN HKP.BudgetCategory AS BC ON BC.Id = BM.BudgetCategoryId

                                        LEFT JOIN HKP.BudgetSubCategory AS BSC ON BSC.Id = BM.BudgetSubCategoryId

                                        LEFT JOIN HKP.Budget AS B ON B.Id = BM.BudgetId

                                        LEFT JOIN HKP.GLGeneralInfo AS GL ON GL.Id = BM.GLGeneralInfoId

                                        LEFT JOIN HKP.AccountGroup AS AG ON AG.Id = GL.AccountGroupId

                                        LEFT JOIN HKP.AccountType AS ACT ON ACT.Id = AG.AccountTypeId

                                        LEFT JOIN ORG.Entity AS ENT ON ENT.Id = V.EntityId
                                        " + join + @"

                                        LEFT JOIN(SELECT Id AS EntryPeriodId, PeriodName, StartDate, EndDate FROM SCS.FiscalYearPeriod)

                                                    AS FYPA ON MONTH(CONVERT(DATE, FYPA.EndDate)) = MONTH(CONVERT(DATE, evd.AddedDate))

                                            AND YEAR(CONVERT(DATE, FYPA.EndDate))= YEAR(CONVERT(DATE, evd.AddedDate))

                                        WHERE V.CompanyGroupId = '" + companyGroupId + @"'  AND V.PostingDate BETWEEN(SELECT StartDate FROM SCS.FiscalYearPeriod where '" + calculatedFromDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + calculatedToDate.ToString("dd-MMM-yyyy") + @"' between StartDate and EndDate) AND V.IsPark = 0

                                        AND ACT.IsBalanceSheet = 0  AND ACT.Id IN('Expense') " + wc + @"

                                          GROUP BY EFYP.Id , EFYP.PeriodName,  FYPA.PeriodName, FYPA.EndDate,EFYP.EndDate,FYPA.EntryPeriodId ,ACT.BalanceType
                                            " + cList + @"  " + cListId + @", cmp.Id
								    ) periodWiseExp

                            GROUP by periodWiseExp.PostingPeriod,periodWiseExp.PostingPeriodId, periodWiseExp.EntryPeriod,periodWiseExp.EntryPeriodId,
                            periodWiseExp.EntryPeriodEndDate, periodWiseExp.PostingPeriodEndDate
                       ) periodWiseExp
                                    ON periodWiseExp." + periodId + @" = FiscalYear.Id )";
                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }

        #endregion Budget Wise Expense Bar Chart

        //------------------------------------------Modals-----------------------------------------------------//
        public IEnumerable<object> ModalBudgetWiseExpense(string Category, string days, string companyId, string PlantId)
        {
            var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
            string fromDate = "";
            string toDate = "";
            string RequestDay = "";
            if (days == "3") { fromDate = "0"; toDate = "3"; RequestDay = "3"; }
            if (days == "5") { fromDate = "4"; toDate = "5"; RequestDay = "5"; }
            if (days == "10") { fromDate = "6"; toDate = "10"; RequestDay = "10"; }
            if (days == "15") { fromDate = "11"; toDate = "15"; RequestDay = "15"; }
            if (days == "20") { fromDate = "16"; toDate = "20"; RequestDay = "20"; }
            if (days == "25") { fromDate = "21"; toDate = "25"; RequestDay = "25"; }
            if (days == "30") { fromDate = "26"; toDate = "30"; RequestDay = "30"; }
            if (days == "31") { fromDate = "31"; toDate = "90000000"; RequestDay = "31"; }
            if (days == "32") { fromDate = "0"; toDate = "90000000"; RequestDay = "32"; }
            try
            {
                var sql = "";
                if (companyId == null && PlantId == null)
                {
                    #region Pending Req for approval

                    if (Category == "Pending Requisition For Approval" && days == RequestDay)
                    {
                        sql = @"select 'Pending Requisition For Approval' Category
							,MRM.CompanyGroupId, MRM.CompanyId
							,CG.UserName CompanyGroup
							,C.UserName Company
							,P.UserName PlantName
							,MRM.Id RequisitionNo
							,MRM.RequisitionType
							,MRM.RequirmentType
							,EI2.EmployeeName PreparedBy
							,DaysCount=CASE WHEN DATEDIFF(day,MRM.RequisitionDate,getdate()) between 0 and 3 THEN DATEDIFF(day,MRM.RequisitionDate,getdate())
							 ELSE 0	END
							, REPLACE(CONVERT(CHAR(11), MRM.RequisitionDate, 106),' ','-') AS RequisitionDate
							,EI.EmployeeName   CheckedBy
							,MRM.CheckedByStatus
							--,MRM.AuthorizedByStatus
                                  --,AuthorizedByStatus=CASE WHEN MRM.AuthorizedByStatus='Approval' 
								--THEN 'Approved' 
								--WHEN MRM.CheckedByStatus='For Checking'OR  MRM.CheckedByStatus='Hold' THEN ''   
								--ELSE 'For Approving' END
							,AuthorizedByStatus=CASE WHEN MRM.AuthorizedByStatus='Approved'  THEN 'Approved' 
								WHEN MRM.CheckedByStatus='Checked'  ANd  MRM.AuthorizedByStatus='For Approval' THEN 'To be approved'								
								WHEN MRM.CheckedByStatus='Checked'  ANd  MRM.AuthorizedByStatus='Hold' THEN 'Hold' 
								WHEN MRM.CheckedByStatus='Hold' ANd  isnull(MRM.AuthorizedByStatus,'')='' THEN 'To be Checked' 
								WHEN MRM.CheckedByStatus='For Checking' ANd  isnull(MRM.AuthorizedByStatus,'')='' THEN 'To be Checked' 
							 ELSE '' END
							,EI1.EmployeeName AuthorizedBy
							,FORMAT(CONVERT(NUMERIC(18,2),sum(MRD.Amount)),'#,#') Amount
							,CONVERT(NUMERIC(18,2),sum(MRD.Qty)) Qty
							,CONVERT(NUMERIC(18,2),(sum(MRD.Amount/MRD.Qty))) AvarageRate
							FROM trn.MaterialRequsitionMaster MRM
							LEFT JOIN( Select MaterialReqqusitionMasterId ,POQtyStatus,sum(TotalAmount) Amount,sum(TransactionQty) Qty 
										FROM  trn.MaterialRequsitionDetails GROUP by MaterialReqqusitionMasterId,POQtyStatus
							) MRD ON MRD.MaterialReqqusitionMasterId=MRM.id
							LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=MRM.CheckedBy
							LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=MRM.AuthorizedBy
							LEFT JOIN dbo.EmployeeInformation EI2 ON EI2.SystemId=MRM.ReqEmpId
							LEFT JOIN ORG.CompanyGroup CG ON CG.Id=MRM.CompanyGroupId
							LEFT JOIN ORG.Company C ON C.Id=MRM.CompanyId
							LEFT JOIN ORG.Plant P ON p.Id=MRM.PlantId
							WHERE DATEDIFF(day,MRM.RequisitionDate,getdate()) between '" + fromDate + @"' and '" + toDate + @"'  							
                            AND (MRM.CheckedByStatus ='Checked' OR MRM.CheckedByStatus ='Hold')
							AND (isnull(MRM.AuthorizedByStatus,'') ='For Approval' OR MRM.AuthorizedByStatus IS NULL)		
							AND MRM.InActive=0 	AND MRD.POQtyStatus=0
							Group BY DATEDIFF(day,MRM.RequisitionDate,getdate()),MRM.CompanyGroupId, MRM.CompanyId,MRM.Id	
							,MRM.RequisitionType,MRM.RequirmentType,EI2.EmployeeName, MRM.RequisitionDate,EI.EmployeeName
							,MRM.CheckedByStatus,MRM.AuthorizedByStatus,EI1.EmployeeName,CG.UserName,C.UserName,P.UserName";


                    }


                    #endregion
                    #region Pending Req for PO
                    if (Category == "Pending Requisition For PO" && days == RequestDay)
                    {
                        sql = @"select 'Pending Requisition For PO' Category
							,MRM.CompanyGroupId, MRM.CompanyId
							,CG.UserName CompanyGroup
							,C.UserName Company
							,P.UserName PlantName
							,MRM.Id RequisitionNo
							,MRM.RequisitionType
							,MRM.RequirmentType
							,EI2.EmployeeName PreparedBy
							,DaysCount=CASE WHEN DATEDIFF(day,MRM.RequisitionDate,getdate()) between 0 and 3 THEN DATEDIFF(day,MRM.RequisitionDate,getdate())
							 ELSE 0	END
							, REPLACE(CONVERT(CHAR(11), MRM.RequisitionDate, 106),' ','-') AS RequisitionDate
							,EI.EmployeeName   CheckedBy
							,MRM.CheckedByStatus
							--,MRM.AuthorizedByStatus
                                  --,AuthorizedByStatus=CASE WHEN MRM.AuthorizedByStatus='Approval' 
								--THEN 'Approved' 
								--WHEN MRM.CheckedByStatus='For Checking'OR  MRM.CheckedByStatus='Hold' THEN ''   
								--ELSE 'For Approving' END
							,AuthorizedByStatus=CASE WHEN MRM.AuthorizedByStatus='Approved'  THEN 'Approved' 
								WHEN MRM.CheckedByStatus='Checked'  ANd  MRM.AuthorizedByStatus='For Approval' THEN 'To be approved'								
								WHEN MRM.CheckedByStatus='Checked'  ANd  MRM.AuthorizedByStatus='Hold' THEN 'Hold' 
								WHEN MRM.CheckedByStatus='Hold' ANd  isnull(MRM.AuthorizedByStatus,'')='' THEN 'To be Checked' 
								WHEN MRM.CheckedByStatus='For Checking' ANd  isnull(MRM.AuthorizedByStatus,'')='' THEN 'To be Checked' 
							 ELSE '' END
                             ,PendingStatus=Case WHEN sum(isnull(MRD.PORcvQty,0)) = 0 THEN 'Full Pending'
							                     WHEN sum(isnull(MRD.PORcvQty,0)) > 0 THEN  'Partial Pending' 
												 WHEN sum(isnull(MRD.PORcvQty,0)) = CONVERT(NUMERIC(18,2),sum(MRD.Qty)) THEN  'No Pending'
												 ELSE ''
												 END
							,EI1.EmployeeName AuthorizedBy
							,FORMAT(CONVERT(NUMERIC(18,2),sum(MRD.Amount)),'#,#') Amount
							,CONVERT(NUMERIC(18,2),sum(MRD.Qty)) Qty
							,CONVERT(NUMERIC(18,2),(sum(MRD.Amount/MRD.Qty))) AvarageRate
							FROM trn.MaterialRequsitionMaster MRM
							LEFT JOIN( Select MaterialReqqusitionMasterId ,POQtyStatus,sum(TotalAmount) Amount,sum(TransactionQty) Qty 
										,sum(isnull(PORcvQty,0)) PORcvQty FROM  trn.MaterialRequsitionDetails GROUP by MaterialReqqusitionMasterId,POQtyStatus
							) MRD ON MRD.MaterialReqqusitionMasterId=MRM.id
							LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=MRM.CheckedBy
							LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=MRM.AuthorizedBy
							LEFT JOIN dbo.EmployeeInformation EI2 ON EI2.SystemId=MRM.ReqEmpId
							LEFT JOIN ORG.CompanyGroup CG ON CG.Id=MRM.CompanyGroupId
							LEFT JOIN ORG.Company C ON C.Id=MRM.CompanyId
							LEFT JOIN ORG.Plant P ON p.Id=MRM.PlantId
							WHERE DATEDIFF(day,MRM.RequisitionDate,getdate()) between '" + fromDate + @"' and '" + toDate + @"'   							
                            AND MRM.CheckedByStatus ='Checked' AND isnull(MRM.AuthorizedByStatus,'') ='Approved'	
							AND MRM.InActive=0 AND MRD.POQtyStatus=0
							Group BY DATEDIFF(day,MRM.RequisitionDate,getdate()),MRM.CompanyGroupId, MRM.CompanyId,MRM.Id	
							,MRM.RequisitionType,MRM.RequirmentType,EI2.EmployeeName, MRM.RequisitionDate,EI.EmployeeName
							,MRM.CheckedByStatus,MRM.AuthorizedByStatus,EI1.EmployeeName,CG.UserName,C.UserName,P.UserName";


                    }
                    #endregion
                    #region Pending PO For Approval
                    if (Category == "PO Pending For Approval" && days == RequestDay)
                    {
                        sql = @"select 'PO Pending For Approval' Category	
								,PO.CompanyId		
								,CG.UserName CompanyGroup
								,C.UserName Company
								,P1.UserName PlantName
								,DaysCount=CASE WHEN DATEDIFF(day,PO.PODate,getdate()) >0 AND DATEDIFF(day,PO.PODate,getdate())<=3 THEN DATEDIFF(day,PO.PODate,getdate())
								 ELSE 0	END
								,PO.Id PONo, REPLACE(CONVERT(CHAR(11), po.PODate, 106),' ','-') AS PODate
								,PO.DocRefNo
								,PO.DocDate
								,p.UserName PartyName
								,PO.AddedBy PreparedBy
								,EI.EmployeeName CheckedBy
								,PO.CheckedByStatus
								,EI1.EmployeeName AuthorizedBy
								--,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval' 
										--THEN 'Approved' 
										--WHEN PO.CheckedByStatus='Pending'OR  PO.CheckedByStatus='Hold'OR PO.CheckedByStatus='' THEN ''   
										--ELSE 'For Approving' END
                                 ,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval'  THEN 'Approved' 
								  WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus is null THEN 'To be approved'  
								  WHEN PO.CheckedByStatus='Checked'  ANd  isnull(PO.AuthorizedByStatus,'')='' THEN 'To be approved'  
								  WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus='Hold' THEN 'Hold' 
								  WHEN PO.CheckedByStatus='Hold'  THEN 'To be Checked' 
								  WHEN PO.CheckedByStatus='Pending'  THEN 'To be Checked' else '' END

								,FORMAT(CONVERT(NUMERIC(10,2),sum(POD.BaseAmount)),'#,#') Amount
								,CONVERT(NUMERIC(10,2),sum(POD.TransactionQty)) Qty
								,CONVERT(NUMERIC(10,2),(sum(POD.BaseAmount)/sum(POD.TransactionQty))) AvarageRate
								FROM trn.PurchaseOrder PO
								LEFT JOIN TRN.PurchaseOrderDetail POD ON POD.InventoryReceiveId=PO.id 
								LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=PO.CheckedBy
								LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=PO.AuthorizedBy
								LEFT JOIN hkp.Party p ON p.id=PO.PartyId
								LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PO.CompanyGroupId
								LEFT JOIN ORG.Company C ON C.Id=PO.CompanyId
								LEFT JOIN ORG.Plant P1 ON p1.Id=PO.PlantId
								where DATEDIFF(day,PO.PODate,getdate()) Between '" + fromDate + @"' and '" + toDate + @"' 
								AND (PO.CheckedByStatus ='Checked' OR PO.CheckedByStatus ='Hold')
								AND (PO.AuthorizedByStatus='For Approval' OR PO.AuthorizedByStatus IS NULL)
								AND PO.IsClosed=0 AND POD.QtyStatus=0
								AND PO.ContractId is NUll AND PO.PurchaseLCId IS NULL
								GROUp BY PO.CompanyId,PO.Id	,PO.AddedBy,EI.EmployeeName,EI1.EmployeeName,p.UserName,DATEDIFF(day,PO.PODate,getdate())
								,PO.DocRefNo,PO.DocDate,PO.CheckedByStatus,PO.AuthorizedByStatus,CG.UserName,C.UserName,P1.UserName,po.PODate";

                    }
                    #endregion
                    #region Pending PO For Purchase
                    if (Category == "PO Pending For Purchase" && days == RequestDay)
                    {
                        sql = @"select 'PO Pending For Purchase' Category	
								,PO.CompanyId		
								,CG.UserName CompanyGroup
								,C.UserName Company
								,P1.UserName PlantName
								,DaysCount=CASE WHEN DATEDIFF(day,PO.PODate,getdate()) >0 AND DATEDIFF(day,PO.PODate,getdate())<=3 THEN DATEDIFF(day,PO.PODate,getdate())
								 ELSE 0	END
								,PO.Id PONo, REPLACE(CONVERT(CHAR(11), po.PODate, 106),' ','-') AS PODate
								,PO.DocRefNo
								,PO.DocDate
								,p.UserName PartyName
								,PO.AddedBy PreparedBy
								,EI.EmployeeName CheckedBy
								,PO.CheckedByStatus
								,EI1.EmployeeName AuthorizedBy
                                 ,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approved'  THEN 'Approved' 
									WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus ='For Approval' THEN 'To be approved'  
									WHEN PO.CheckedByStatus='Checked'  ANd  isnull(PO.AuthorizedByStatus,'')='' THEN 'To be approved'  
									WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus='Hold' THEN 'Hold' 
									WHEN PO.CheckedByStatus='Hold'  THEN 'To be Checked' 
									WHEN PO.CheckedByStatus='Pending'  THEN 'To be Checked' else '' END
                                  ,PendingStatus=Case WHEN sum(isnull(POD.GRNRcvQty,0)) = 0 THEN 'Full Pending'
							                     WHEN sum(isnull(POD.GRNRcvQty,0)) > 0 THEN  'Partial Pending' 
												 WHEN sum(isnull(POD.GRNRcvQty,0)) = sum(isnull(POD.TransactionQty,0)) THEN  'No Pending'
												 ELSE ''
												 END
								,FORMAT(CONVERT(NUMERIC(10,2),sum(POD.BaseAmount)),'#,#') Amount
								,CONVERT(NUMERIC(10,2),sum(POD.TransactionQty)) Qty
								,CONVERT(NUMERIC(10,2),(sum(POD.BaseAmount)/sum(POD.TransactionQty))) AvarageRate
								FROM trn.PurchaseOrder PO
								LEFT JOIN TRN.PurchaseOrderDetail POD ON POD.InventoryReceiveId=PO.id 
								LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=PO.CheckedBy
								LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=PO.AuthorizedBy
								LEFT JOIN hkp.Party p ON p.id=PO.PartyId
								LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PO.CompanyGroupId
								LEFT JOIN ORG.Company C ON C.Id=PO.CompanyId
								LEFT JOIN ORG.Plant P1 ON p1.Id=PO.PlantId
								where DATEDIFF(day,PO.PODate,getdate()) Between '" + fromDate + @"' and '" + toDate + @"' 
								AND PO.CheckedByStatus ='Checked' AND PO.AuthorizedByStatus ='Approved' 
								AND PO.IsClosed=0 AND POD.QtyStatus=0
								AND PO.ContractId is NUll AND PO.PurchaseLCId IS NULL
								--ANd PO.Id not in(Select distinct POId from trn.InventoryReceivedetail where POId is not null)	
								GROUp BY PO.CompanyId,PO.Id	,PO.AddedBy,EI.EmployeeName,EI1.EmployeeName,p.UserName,DATEDIFF(day,PO.PODate,getdate())
								,PO.DocRefNo,PO.DocDate,PO.CheckedByStatus,PO.AuthorizedByStatus,CG.UserName,C.UserName,P1.UserName,po.PODate";

                    }
                    #endregion

                    #region PO Pending For LC Taging
                    if (Category == "PO Pending For LC Taging" && days == RequestDay)
                    {
                        sql = @"SELECT 'PO Pending For LC Taging' Category	
						,PO.CompanyId	
						,CG.UserName CompanyGroup
						,C.UserName Company
						,P1.UserName PlantName
						,DaysCount=CASE WHEN DATEDIFF(day,PO.PODate,getdate()) >0 AND DATEDIFF(day,PO.PODate,getdate())<=3 THEN DATEDIFF(day,PO.PODate,getdate()) ELSE 0 END
						,PO.Id PONo
						,REPLACE(CONVERT(CHAR(11), po.PODate, 106),' ','-') AS PODate
						,PO.DocRefNo
						,PO.DocDate
						,PO.ContractId
						,PO.PurchaseLCId
						,PT.PaymentMode
						,PO.AddedBy PreparedBy
						,EI.EmployeeName CheckedBy
						,PO.CheckedByStatus
						,EI1.EmployeeName AuthorizedBy
						,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approved' 
								THEN 'Approved' 
								WHEN PO.CheckedByStatus='Pending' OR  PO.CheckedByStatus='Hold' OR PO.CheckedByStatus='' THEN ''   
								ELSE 'For Approving' 
								END
						,0 AS FiveDaysCount
						,0 AS TenDaysCount
						,0 AS FifteenDaysCount
						,0 AS TweentyDaysCount
						,0 AS TwentyFiveyDaysCount
						,0 AS ThirtyDaysCount
						,0 AS GraterThirtyDaysCount
						,0 AS AllCount
						,sum(POD.Qty) Qty
						,sum(POD.Rate) Rate
						,FORMAT((sum(POD.Qty)* sum(POD.Rate)),'#,#') Amount
					    FROM trn.PurchaseOrder PO
						LEFT JOIN (Select InventoryReceiveId,sum(TransactionQty) Qty,sum(TransactionRate) Rate,Sum(BaseAmount) Amount 
						FROM TRN.PurchaseOrderDetail GROUP BY InventoryReceiveId
						) POD ON POD.InventoryReceiveId=PO.id 
						LEFT JOIN [MST].[PaymentTerm] PT ON PT.id=PO.PaymentTermId 	
						LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=PO.CheckedBy
						LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=PO.AuthorizedBy
						LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PO.CompanyGroupId
						LEFT JOIN ORG.Company C ON C.Id=PO.CompanyId
						LEFT JOIN ORG.Plant P1 ON p1.Id=PO.PlantId
					where PO.Id not in(Select distinct POId from trn.InventoryReceivedetail where POId is not null)				
						AND DATEDIFF(day,PO.PODate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
						AND PO.CheckedByStatus !='Reject' AND PO.IsClosed=0
						AND PO.POType='PO' AND PT.PaymentMode = 'LC' AND PO.PurchaseLCId IS NULL 
						--AND PO.CompanyId=''
					GROUp BY PO.CompanyId,PO.Id,PO.PODate,PO.DocRefNo,PO.DocDate,PO.ContractId
					,PO.PurchaseLCId,PT.PaymentMode,PO.AddedBy,EI.EmployeeName
					,EI1.EmployeeName,PO.CheckedByStatus,PO.AuthorizedByStatus ,CG.UserName,C.UserName,P1.UserName ,po.PODate";

                    }
