                        sql = @"SELECT 'Acceptance Pending For GRN' Category
								,PDA.CompanyGroupId--,PDA.PlantId		
								,CG.UserName CompanyGroup
								,C.UserName Company
								,P2.UserName PlantName	
								,DaysCount=CASE WHEN DATEDIFF(day,PDA.EntryDate,getdate()) >0  ANd DATEDIFF(day,PDA.EntryDate,getdate())<=3 THEN DATEDIFF(day,PDA.EntryDate,getdate()) ELSE 0 END
								,PDA.AcceptanceDate
								,PDA.AcceptanceNo
								,PDA.AcceptanceRate
								,PDA.PurchaseLCId	
								,PDA.PrePurchaseInvoiceId
								,sum(PDAD.Qty) Qty
								,sum(PDAD.Total3Value)/sum(PDAD.Qty) Rate
								,sum(PDAD.Total3Value) Amount,PDA.Id

						FROM trn.PurchaseDocAcceptance PDA
						LEFT JOIN (Select PurchaseDocAcceptanceId ,Sum(TransactionQty) Qty,Sum(MaterialTranAmount) Total3Value from TRN.PurchaseDocAcceptanceDetail GROUp bY PurchaseDocAcceptanceId) AS PDAD ON PDAD.PurchaseDocAcceptanceId=PDA.Id
						LEFT JOIN [dbo].[PrePurchaseInvoice] PPI ON PPI.Id=PDA.PrePurchaseInvoiceId
							LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PDA.CompanyGroupId
							LEFT JOIN ORG.Company C ON C.Id=PDA.CompanyId
							LEFT JOIN ORG.Plant P2 ON p2.Id=PDA.PlantId
						WHERE PDA.Id not in (select PurchaseDocAcceptanceId from trn.InventoryReceive where PurchaseDocAcceptanceId is not null)	
						AND DATEDIFF(day,PDA.EntryDate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
						GROUP BY PDA.CompanyGroupId,DATEDIFF(day,PDA.EntryDate,getdate()),CG.UserName,C.UserName,P2.UserName,PDA.AcceptanceDate,PDA.AcceptanceNo,PDA.AcceptanceRate,PDA.PurchaseLCId,PDA.PrePurchaseInvoiceId,PDA.Id";

