                }
                else if (companyId != null)
                {
                    #region Pending Req For Approval

                    if (Category == "Pending Requisition For Approval" && days == RequestDay)
                    {
                        sql = @"select 'Pending Requisition For Approval' Category
							,MRM.CompanyGroupId, MRM.CompanyId
							,CG.UserName CompanyGroup
							,C.UserName Company
							,P.UserName PlantName
							,MRM.Id RequisitionNo
							,MRM.RequisitionType
							,MRM.RequirmentType
							,EI2.EmployeeName PreparedBy
							,DaysCount=CASE WHEN DATEDIFF(day,MRM.RequisitionDate,getdate()) Between 0 and 3 THEN DATEDIFF(day,MRM.RequisitionDate,getdate())
							 ELSE 0	END
							, REPLACE(CONVERT(CHAR(11), MRM.RequisitionDate, 106),' ','-') AS RequisitionDate
							,EI.EmployeeName   CheckedBy
							,MRM.CheckedByStatus
							--,MRM.AuthorizedByStatus
                                  --,AuthorizedByStatus=CASE WHEN MRM.AuthorizedByStatus='Approval' 
								--THEN 'Approved' 
								--WHEN MRM.CheckedByStatus='For Checking'OR  MRM.CheckedByStatus='Hold' THEN ''   
								--ELSE 'For Approving' END
							,AuthorizedByStatus=CASE WHEN MRM.AuthorizedByStatus='Approval'  THEN 'Approved' 
								WHEN MRM.CheckedByStatus='Checked'  ANd  MRM.AuthorizedByStatus is null THEN 'To be approved'  
								WHEN MRM.CheckedByStatus='Checked'  ANd  isnull(MRM.AuthorizedByStatus,'')='' THEN 'To be approved'  
								WHEN MRM.CheckedByStatus='Checked'  ANd  MRM.AuthorizedByStatus='Hold' THEN 'Hold' 
								WHEN MRM.CheckedByStatus='Hold'  THEN 'To be Checked' 
								WHEN MRM.CheckedByStatus='For Checking'  THEN 'To be Checked' 
							 ELSE '' END
							,EI1.EmployeeName AuthorizedBy
							,FORMAT(CONVERT(NUMERIC(18,2),sum(MRD.Amount)),'#,#') Amount
							,CONVERT(NUMERIC(18,2),sum(MRD.Qty)) Qty
							,CONVERT(NUMERIC(18,2),(sum(MRD.Amount/MRD.Qty))) AvarageRate
							FROM trn.MaterialRequsitionMaster MRM
							LEFT JOIN(
										Select MaterialReqqusitionMasterId ,POQtyStatus,sum(TotalAmount) Amount,sum(TransactionQty) Qty 
										FROM  trn.MaterialRequsitionDetails 
										Group by MaterialReqqusitionMasterId,POQtyStatus
							) MRD ON MRD.MaterialReqqusitionMasterId=MRM.id
							LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=MRM.CheckedBy
							LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=MRM.AuthorizedBy
							LEFT JOIN dbo.EmployeeInformation EI2 ON EI2.SystemId=MRM.ReqEmpId
							LEFT JOIN ORG.CompanyGroup CG ON CG.Id=MRM.CompanyGroupId
							LEFT JOIN ORG.Company C ON C.Id=MRM.CompanyId
							LEFT JOIN ORG.Plant P ON p.Id=MRM.PlantId
							WHERE --MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
							DATEDIFF(day,MRM.RequisitionDate,getdate()) between '" + fromDate + @"' and '" + toDate + @"'
							AND (MRM.CheckedByStatus ='Checked' OR MRM.CheckedByStatus ='Hold')
							AND (isnull(MRM.AuthorizedByStatus,'') ='For Approval' OR MRM.AuthorizedByStatus IS NULL)		
							AND MRM.InActive=0 	AND MRD.POQtyStatus=0
                            AND MRM.CompanyId='" + companyId + @"' AND MRM.PlantId='" + PlantId + @"'
							Group BY DATEDIFF(day,MRM.RequisitionDate,getdate())
							,MRM.CompanyGroupId, MRM.CompanyId,MRM.Id,MRM.RequisitionType,MRM.RequirmentType
							,EI2.EmployeeName, REPLACE(CONVERT(CHAR(11), MRM.RequisitionDate, 106), ' ', '-')
							,EI.EmployeeName,MRM.CheckedByStatus,MRM.AuthorizedByStatus,EI1.EmployeeName ,CG.UserName ,C.UserName,P.UserName";


                    }

                    #endregion
                    #region Pending Req for PO

                    if (Category == "Pending Requisition For PO" && days == RequestDay)
                    {
                        sql = @"select 'Pending Requisition For PO' Category
							,MRM.CompanyGroupId, MRM.CompanyId
							,CG.UserName CompanyGroup
							,C.UserName Company
							,P.UserName PlantName
							,MRM.Id RequisitionNo
							,MRM.RequisitionType
							,MRM.RequirmentType
							,EI2.EmployeeName PreparedBy
							,DaysCount=CASE WHEN DATEDIFF(day,MRM.RequisitionDate,getdate()) Between 0 and 3 THEN DATEDIFF(day,MRM.RequisitionDate,getdate())
							 ELSE 0	END
							, REPLACE(CONVERT(CHAR(11), MRM.RequisitionDate, 106),' ','-') AS RequisitionDate
							,EI.EmployeeName   CheckedBy
							,MRM.CheckedByStatus
							--,MRM.AuthorizedByStatus
                                  --,AuthorizedByStatus=CASE WHEN MRM.AuthorizedByStatus='Approval' 
								--THEN 'Approved' 
								--WHEN MRM.CheckedByStatus='For Checking'OR  MRM.CheckedByStatus='Hold' THEN ''   
								--ELSE 'For Approving' END
							,AuthorizedByStatus=CASE WHEN MRM.AuthorizedByStatus='Approval'  THEN 'Approved' 
								WHEN MRM.CheckedByStatus='Checked'  ANd  MRM.AuthorizedByStatus is null THEN 'To be approved'  
								WHEN MRM.CheckedByStatus='Checked'  ANd  isnull(MRM.AuthorizedByStatus,'')='' THEN 'To be approved'  
								WHEN MRM.CheckedByStatus='Checked'  ANd  MRM.AuthorizedByStatus='Hold' THEN 'Hold' 
								WHEN MRM.CheckedByStatus='Hold'  THEN 'To be Checked' 
								WHEN MRM.CheckedByStatus='For Checking'  THEN 'To be Checked' 
							 ELSE '' END
							,EI1.EmployeeName AuthorizedBy
							,FORMAT(CONVERT(NUMERIC(18,2),sum(MRD.Amount)),'#,#') Amount
							,CONVERT(NUMERIC(18,2),sum(MRD.Qty)) Qty
							,CONVERT(NUMERIC(18,2),(sum(MRD.Amount/MRD.Qty))) AvarageRate
							FROM trn.MaterialRequsitionMaster MRM
							LEFT JOIN(
										Select MaterialReqqusitionMasterId ,POQtyStatus,sum(TotalAmount) Amount,sum(TransactionQty) Qty 
										FROM  trn.MaterialRequsitionDetails 
										Group by MaterialReqqusitionMasterId,POQtyStatus
							) MRD ON MRD.MaterialReqqusitionMasterId=MRM.id
							LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=MRM.CheckedBy
							LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=MRM.AuthorizedBy
							LEFT JOIN dbo.EmployeeInformation EI2 ON EI2.SystemId=MRM.ReqEmpId
							LEFT JOIN ORG.CompanyGroup CG ON CG.Id=MRM.CompanyGroupId
							LEFT JOIN ORG.Company C ON C.Id=MRM.CompanyId
							LEFT JOIN ORG.Plant P ON p.Id=MRM.PlantId
							WHERE --MRM.Id not in(Select distinct RequisitionId from trn.PurchaseOrderDetail where RequisitionId is not null)
							DATEDIFF(day,MRM.RequisitionDate,getdate()) between '" + fromDate + @"' and '" + toDate + @"'
							AND MRM.CheckedByStatus ='Checked' AND isnull(MRM.AuthorizedByStatus,'') ='Approved'	
							AND MRM.InActive=0 AND MRD.POQtyStatus=0 
                            AND MRM.CompanyId='" + companyId + @"' AND MRM.PlantId='" + PlantId + @"'
							Group BY DATEDIFF(day,MRM.RequisitionDate,getdate())
							,MRM.CompanyGroupId, MRM.CompanyId,MRM.Id,MRM.RequisitionType,MRM.RequirmentType
							,EI2.EmployeeName, REPLACE(CONVERT(CHAR(11), MRM.RequisitionDate, 106), ' ', '-')
							,EI.EmployeeName,MRM.CheckedByStatus,MRM.AuthorizedByStatus,EI1.EmployeeName ,CG.UserName ,C.UserName,P.UserName";


                    }

                    #endregion
                    #region Pending PO for Approval
                    if (Category == "PO Pending For Approval" && days == RequestDay)
                    {
                        sql = @"select 'PO Pending For Approval' Category	
								,PO.CompanyId		
								,CG.UserName CompanyGroup
								,C.UserName Company
								,P1.UserName PlantName
								,DaysCount=CASE WHEN DATEDIFF(day,PO.PODate,getdate()) >0 AND DATEDIFF(day,PO.PODate,getdate())<=3 THEN DATEDIFF(day,PO.PODate,getdate())
								 ELSE 0	END
								,PO.Id AS PONo, REPLACE(CONVERT(CHAR(11), po.PODate, 106),' ','-') AS PODate
								,PO.DocRefNo
								,PO.DocDate
								,p.UserName PartyName
								,PO.AddedBy PreparedBy
								,EI.EmployeeName CheckedBy
								,PO.CheckedByStatus
								,EI1.EmployeeName AuthorizedBy
								--,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval' 
										--THEN 'Approved' 
										--WHEN PO.CheckedByStatus='Pending'OR  PO.CheckedByStatus='Hold'OR PO.CheckedByStatus='' THEN ''   
										--ELSE 'For Approving' END
                                 ,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval'  THEN 'Approved' 
								  WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus is null THEN 'To be approved'  
								  WHEN PO.CheckedByStatus='Checked'  ANd  isnull(PO.AuthorizedByStatus,'')='' THEN 'To be approved'  
								  WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus='Hold' THEN 'Hold' 
								  WHEN PO.CheckedByStatus='Hold'  THEN 'To be Checked' 
								  WHEN PO.CheckedByStatus='Pending'  THEN 'To be Checked' else '' END
								,FORMAT(CONVERT(NUMERIC(10,2),sum(POD.BaseAmount)),'#,#') Amount
								,CONVERT(NUMERIC(10,2),sum(POD.TransactionQty)) Qty
								,CONVERT(NUMERIC(10,2),(sum(POD.BaseAmount)/sum(POD.TransactionQty))) AvarageRate
								,RequisitionNo=	STUFF((select distinct ','+XVD.Id from trn.MaterialRequsitionMaster XVD 
														 join TRN.PurchaseOrderDetail xPOD on  xPOD.RequisitionId=XVD.Id and xPOD.InventoryReceiveId=PO.Id
														  for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '')
								FROM trn.PurchaseOrder PO
								LEFT JOIN TRN.PurchaseOrderDetail POD ON POD.InventoryReceiveId=PO.id 
                                LEFT JOIN [MST].[PaymentTerm] PT ON PT.id=PO.PaymentTermId 	
								LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=PO.CheckedBy
								LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=PO.AuthorizedBy
								LEFT JOIN hkp.Party p ON p.id=PO.PartyId
								LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PO.CompanyGroupId
								LEFT JOIN ORG.Company C ON C.Id=PO.CompanyId
								LEFT JOIN ORG.Plant P1 ON p1.Id=PO.PlantId
								WHERE DATEDIFF(day,PO.PODate,getdate()) Between '" + fromDate + @"' And '" + toDate + @"'	
								AND (PO.CheckedByStatus ='Checked' OR PO.CheckedByStatus ='Hold')
								AND (PO.AuthorizedByStatus='For Approval' OR PO.AuthorizedByStatus IS NULL)
								AND PO.IsClosed=0 AND POD.QtyStatus=0
							    AND PO.PurchaseLCId IS NULL AND ISNULL(PT.PaymentMode,'') <> 'LC'
								AND PO.CompanyId='" + companyId + @"' AND PO.PlantId='" + PlantId + @"'  
								GROUp BY PO.CompanyId,PO.Id	,PO.AddedBy,EI.EmployeeName,EI1.EmployeeName,p.UserName,DATEDIFF(day,PO.PODate,getdate())
								,PO.DocRefNo,PO.DocDate,PO.CheckedByStatus,PO.AuthorizedByStatus,CG.UserName,C.UserName,P1.UserName,po.PODate";

                    }

					#endregion
					#region Pending PO for Approval
					if (Category == "PO Pending For Approval" && days == RequestDay)
					{
						sql = @"select 'PO Pending For Approval' Category	
								,PO.CompanyId		
								,CG.UserName CompanyGroup
								,C.UserName Company
								,P1.UserName PlantName
								,DaysCount=CASE WHEN DATEDIFF(day,PO.PODate,getdate()) >0 AND DATEDIFF(day,PO.PODate,getdate())<=3 THEN DATEDIFF(day,PO.PODate,getdate())
								 ELSE 0	END
								,PO.Id AS PONo, REPLACE(CONVERT(CHAR(11), po.PODate, 106),' ','-') AS PODate
								,PO.DocRefNo
								,PO.DocDate
								,p.UserName PartyName
								,PO.AddedBy PreparedBy
								,EI.EmployeeName CheckedBy
								,PO.CheckedByStatus
								,EI1.EmployeeName AuthorizedBy
								--,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval' 
										--THEN 'Approved' 
										--WHEN PO.CheckedByStatus='Pending'OR  PO.CheckedByStatus='Hold'OR PO.CheckedByStatus='' THEN ''   
										--ELSE 'For Approving' END
                                 ,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval'  THEN 'Approved' 
								  WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus is null THEN 'To be approved'  
								  WHEN PO.CheckedByStatus='Checked'  ANd  isnull(PO.AuthorizedByStatus,'')='' THEN 'To be approved'  
								  WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus='Hold' THEN 'Hold' 
								  WHEN PO.CheckedByStatus='Hold'  THEN 'To be Checked' 
								  WHEN PO.CheckedByStatus='Pending'  THEN 'To be Checked' else '' END
								,FORMAT(CONVERT(NUMERIC(10,2),sum(POD.BaseAmount)),'#,#') Amount
								,CONVERT(NUMERIC(10,2),sum(POD.TransactionQty)) Qty
								,CONVERT(NUMERIC(10,2),(sum(POD.BaseAmount)/sum(POD.TransactionQty))) AvarageRate
								,RequisitionNo=	STUFF((select distinct ','+XVD.Id from trn.MaterialRequsitionMaster XVD 
														 join TRN.PurchaseOrderDetail xPOD on  xPOD.RequisitionId=XVD.Id and xPOD.InventoryReceiveId=PO.Id
														  for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '')
								FROM trn.PurchaseOrder PO
								LEFT JOIN TRN.PurchaseOrderDetail POD ON POD.InventoryReceiveId=PO.id 
                                LEFT JOIN [MST].[PaymentTerm] PT ON PT.id=PO.PaymentTermId 	
								LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=PO.CheckedBy
								LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=PO.AuthorizedBy
								LEFT JOIN hkp.Party p ON p.id=PO.PartyId
								LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PO.CompanyGroupId
								LEFT JOIN ORG.Company C ON C.Id=PO.CompanyId
								LEFT JOIN ORG.Plant P1 ON p1.Id=PO.PlantId
								WHERE DATEDIFF(day,PO.PODate,getdate()) Between '" + fromDate + @"' And '" + toDate + @"'	
								--AND (PO.CheckedByStatus ='Checked' OR PO.CheckedByStatus ='Hold')
								AND (PO.CheckedByStatus='ForChecked')
								AND PO.IsClosed=0 AND POD.QtyStatus=0
							    AND PO.PurchaseLCId IS NULL AND ISNULL(PT.PaymentMode,'') <> 'LC'
								AND PO.CompanyId='" + companyId + @"' AND PO.PlantId='" + PlantId + @"'  
								GROUp BY PO.CompanyId,PO.Id	,PO.AddedBy,EI.EmployeeName,EI1.EmployeeName,p.UserName,DATEDIFF(day,PO.PODate,getdate())
								,PO.DocRefNo,PO.DocDate,PO.CheckedByStatus,PO.AuthorizedByStatus,CG.UserName,C.UserName,P1.UserName,po.PODate";

					}

					#endregion
					#region Pending PO For Purchase
					if (Category == "PO Pending For Purchase" && days == RequestDay)
                    {
                        sql = @"select 'PO Pending For Purchase' Category	
								,PO.CompanyId		
								,CG.UserName CompanyGroup
								,C.UserName Company
								,P1.UserName PlantName
								,DaysCount=CASE WHEN DATEDIFF(day,PO.PODate,getdate()) >0 AND DATEDIFF(day,PO.PODate,getdate())<=3 THEN DATEDIFF(day,PO.PODate,getdate())
								 ELSE 0	END
								,PO.Id AS PONo,PO.Id , REPLACE(CONVERT(CHAR(11), po.PODate, 106),' ','-') AS PODate
								,PO.DocRefNo
								,PO.DocDate
								,p.UserName PartyName
								,PO.AddedBy PreparedBy
								,EI.EmployeeName CheckedBy
								,PO.CheckedByStatus
								,EI1.EmployeeName AuthorizedBy
								--,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval' 
										--THEN 'Approved' 
										--WHEN PO.CheckedByStatus='Pending'OR  PO.CheckedByStatus='Hold'OR PO.CheckedByStatus='' THEN ''   
										--ELSE 'For Approving' END
                                 ,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval'  THEN 'Approved' 
								  WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus ='For Approval' THEN 'To be approved'  
								  WHEN PO.CheckedByStatus='Checked'  ANd  isnull(PO.AuthorizedByStatus,'')='' THEN 'To be approved'  
								  WHEN PO.CheckedByStatus='Checked'  ANd  PO.AuthorizedByStatus='Hold' THEN 'Hold' 
								  WHEN PO.CheckedByStatus='Hold'  THEN 'To be Checked' 
								  WHEN PO.CheckedByStatus='Pending'  THEN 'To be Checked' else '' END

								--,FORMAT(CONVERT(NUMERIC(10,2),sum(POD.BaseAmount)),'#,#') Amount
								--,CONVERT(NUMERIC(10,2),sum(POD.TransactionQty)) Qty
								--,CONVERT(NUMERIC(10,2),(sum(POD.BaseAmount)/sum(POD.TransactionQty))) AvarageRate
,CONVERT(DECIMAL(18,2),sum(POD.BaseAmount))Amount
								,CONVERT(DECIMAL(18,2),sum(POD.TransactionQty))Qty
								,CONVERT(DECIMAL(18,4),(sum(POD.BaseAmount)/sum(POD.TransactionQty))) AvarageRate
								,RequisitionNo=	STUFF((select distinct ','+XVD.Id from trn.MaterialRequsitionMaster XVD 
														 join TRN.PurchaseOrderDetail xPOD on  xPOD.RequisitionId=XVD.Id and xPOD.InventoryReceiveId=PO.Id
														  for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '')
								FROM trn.PurchaseOrder PO
								LEFT JOIN TRN.PurchaseOrderDetail POD ON POD.InventoryReceiveId=PO.id 
                                LEFT JOIN [MST].[PaymentTerm] PT ON PT.id=PO.PaymentTermId 	
								LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=PO.CheckedBy
								LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=PO.AuthorizedBy
								LEFT JOIN hkp.Party p ON p.id=PO.PartyId
								LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PO.CompanyGroupId
								LEFT JOIN ORG.Company C ON C.Id=PO.CompanyId
								LEFT JOIN ORG.Plant P1 ON p1.Id=PO.PlantId
								where DATEDIFF(day,PO.PODate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
								AND PO.CheckedByStatus ='Checked' AND PO.AuthorizedByStatus ='Approved' 
								AND PO.IsClosed=0 AND POD.QtyStatus=0
								 AND PO.PurchaseLCId IS NULL AND ISNULL(PT.PaymentMode,'') <> 'LC'
								AND PO.CompanyId='" + companyId + @"' AND PO.PlantId='" + PlantId + @"'  
								GROUp BY PO.CompanyId,PO.Id	,PO.AddedBy,EI.EmployeeName,EI1.EmployeeName,p.UserName,DATEDIFF(day,PO.PODate,getdate())
								,PO.DocRefNo,PO.DocDate,PO.CheckedByStatus,PO.AuthorizedByStatus,CG.UserName,C.UserName,P1.UserName,po.PODate";

                    }


                    #endregion


                    #region PO Pending For LC Taging
                    if (Category == "PO Pending For LC Taging" && days == RequestDay)
                    {
                        sql = @"SELECT 'PO Pending For LC Taging' Category	
						,PO.CompanyId	
						,CG.UserName CompanyGroup
						,C.UserName Company
						,P1.UserName PlantName
						,DaysCount=CASE WHEN DATEDIFF(day,PO.PODate,getdate()) >0 AND DATEDIFF(day,PO.PODate,getdate())<=3 THEN DATEDIFF(day,PO.PODate,getdate()) ELSE 0 END
						,PO.Id AS PONo
						,REPLACE(CONVERT(CHAR(11), po.PODate, 106),' ','-') AS PODate
						,PO.DocRefNo
						,PO.DocDate
						,PO.ContractId
						,PO.PurchaseLCId
						,PT.PaymentMode
						,PO.AddedBy PreparedBy
						,EI.EmployeeName CheckedBy
						,PO.CheckedByStatus
						,EI1.EmployeeName AuthorizedBy
						,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval' 
								THEN 'Approved' 
								WHEN PO.CheckedByStatus='Pending' OR  PO.CheckedByStatus='Hold' OR PO.CheckedByStatus='' THEN ''   
								ELSE 'For Approving' 
								END
						,0 AS FiveDaysCount
						,0 AS TenDaysCount
						,0 AS FifteenDaysCount
						,0 AS TweentyDaysCount
						,0 AS TwentyFiveyDaysCount
						,0 AS ThirtyDaysCount
						,0 AS GraterThirtyDaysCount
						,0 AS AllCount
						,sum(POD.Qty) Qty
						,sum(POD.Rate) Rate
						,(sum(POD.Qty)* sum(POD.Rate)) Amount
					    FROM trn.PurchaseOrder PO
						LEFT JOIN (Select InventoryReceiveId,sum(TransactionQty) Qty,sum(TransactionRate) Rate,Sum(BaseAmount) Amount 
						FROM TRN.PurchaseOrderDetail GROUP BY InventoryReceiveId
						) POD ON POD.InventoryReceiveId=PO.id 
						LEFT JOIN [MST].[PaymentTerm] PT ON PT.id=PO.PaymentTermId 	
						LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=PO.CheckedBy
						LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=PO.AuthorizedBy
						LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PO.CompanyGroupId
						LEFT JOIN ORG.Company C ON C.Id=PO.CompanyId
						LEFT JOIN ORG.Plant P1 ON p1.Id=PO.PlantId
					where PO.Id not in(Select distinct POId from trn.InventoryReceivedetail where POId is not null)				
						AND DATEDIFF(day,PO.PODate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
						AND PO.CheckedByStatus !='Reject' AND PO.IsClosed=0 AND PO.CompanyId='" + companyId + @"' AND PO.PlantId='" + PlantId + @"'  
						AND PO.POType='PO' AND PT.PaymentMode = 'LC' AND PO.PurchaseLCId IS NULL 
						--AND PO.CompanyId=''
					GROUp BY PO.CompanyId,PO.Id,PO.PODate,PO.DocRefNo,PO.DocDate,PO.ContractId
					,PO.PurchaseLCId,PT.PaymentMode,PO.AddedBy,EI.EmployeeName
					,EI1.EmployeeName,PO.CheckedByStatus,PO.AuthorizedByStatus ,CG.UserName,C.UserName,P1.UserName ,po.PODate";

                    }


                    #endregion
                    #region Invoice Pending for Acceptance
                    if (Category == "Invoice Pending For Acceptance" && days == RequestDay)
                    {
                        sql = @"SELECT 'Invoice Pending For Acceptance' Category
								,PDA.CompanyGroupId--,PDA.PlantId		
								,CG.UserName CompanyGroup
								,C.UserName Company
								,P2.UserName PlantName	
								,DaysCount=CASE WHEN DATEDIFF(day,PDA.EntryDate,getdate()) >0  ANd DATEDIFF(day,PDA.EntryDate,getdate())<=3 THEN DATEDIFF(day,PDA.EntryDate,getdate()) ELSE 0 END
								,PDA.AcceptanceDate
								,PDA.AcceptanceNo
								,PDA.AcceptanceRate
								,PDA.PurchaseLCId	
								,PDA.PrePurchaseInvoiceId
								,sum(PDAD.Qty) Qty
								,sum(PDAD.Total3Value)/sum(PDAD.Qty) Rate
								,sum(PDAD.Total3Value) Amount,PDA.Id

						FROM trn.PurchaseDocAcceptance PDA
						LEFT JOIN (Select PurchaseDocAcceptanceId ,Sum(TransactionQty) Qty,Sum(MaterialTranAmount) Total3Value from TRN.PurchaseDocAcceptanceDetail GROUp bY PurchaseDocAcceptanceId) AS PDAD ON PDAD.PurchaseDocAcceptanceId=PDA.Id
						LEFT JOIN [dbo].[PrePurchaseInvoice] PPI ON PPI.Id=PDA.PrePurchaseInvoiceId
							LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PDA.CompanyGroupId
							LEFT JOIN ORG.Company C ON C.Id=PDA.CompanyId
							LEFT JOIN ORG.Plant P2 ON p2.Id=PDA.PlantId
						WHERE PDA.PrePurchaseInvoiceId is null AND PDA.CompanyId='" + companyId + @"' AND PDA.PlantId='" + PlantId + @"'  
						AND DATEDIFF(day,PDA.EntryDate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
						GROUP BY PDA.CompanyGroupId,DATEDIFF(day,PDA.EntryDate,getdate()),CG.UserName,C.UserName,P2.UserName,PDA.AcceptanceDate,PDA.AcceptanceNo,PDA.AcceptanceRate,PDA.PurchaseLCId,PDA.PrePurchaseInvoiceId,PDA.Id";

                    }


                    #endregion
                    #region PO Pending For Acceptance
                    if (Category == "PO Pending For Acceptance" && days == RequestDay)
                    {
                        sql = @"SELECT 'PO Pending For Acceptance' Category	
									,PO.CompanyId	
									,CG.UserName CompanyGroup
									,C.UserName Company
									,P1.UserName PlantName
									,DaysCount=CASE WHEN DATEDIFF(day,PO.PODate,getdate()) >0 AND DATEDIFF(day,PO.PODate,getdate())<=3 THEN DATEDIFF(day,PO.PODate,getdate()) ELSE 0 END
									,PO.Id PONo
									, REPLACE(CONVERT(CHAR(11), PO.PODate, 106), ' ', '-') PODate
									,PO.DocRefNo
									,REPLACE(CONVERT(CHAR(11), PO.DocDate, 106), ' ', '-') DocDate 
									,PO.ContractId
									,PO.PurchaseLCId
									,PT.PaymentMode
									,PO.AddedBy PreparedBy
									,EI.EmployeeName CheckedBy
									,PO.CheckedByStatus
									,EI1.EmployeeName AuthorizedBy
									,AuthorizedByStatus=CASE WHEN PO.AuthorizedByStatus='Approval' 
										THEN 'Approved' 
										WHEN PO.CheckedByStatus='Pending' OR  PO.CheckedByStatus='Hold' OR PO.CheckedByStatus='' THEN ''   
										ELSE 'For Approving' 
										END
									,0 AS FiveDaysCount
									,0 AS TenDaysCount
									,0 AS FifteenDaysCount
									,0 AS TweentyDaysCount
									,0 AS TwentyFiveyDaysCount
									,0 AS ThirtyDaysCount
									,0 AS GraterThirtyDaysCount
									,0 AS AllCount
									,sum(POD.Qty) Qty
									,sum(POD.Rate) Rate
									,FORMAT((sum(POD.Qty)*sum(POD.Rate)),'#,#') Amount
							FROM trn.PurchaseOrder PO	
									LEFT JOIN (Select InventoryReceiveId,sum(TransactionQty) Qty,sum(TransactionRate) Rate,Sum(BaseAmount) Total3Value from TRN.PurchaseOrderDetail GROUP BY InventoryReceiveId) POD ON POD.InventoryReceiveId=PO.id 
									LEFT JOIN dbo.PurchaseLC PLC  ON PO.PurchaseLCId=PLC.Id
									LEFT JOIN [MST].[PaymentTerm] PT ON PT.id=PO.PaymentTermId 
									LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=PO.CheckedBy
									LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=PO.AuthorizedBy
									LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PO.CompanyGroupId
									LEFT JOIN ORG.Company C ON C.Id=PO.CompanyId
									LEFT JOIN ORG.Plant P1 ON p1.Id=PO.PlantId
							WHERE PO.Id not in(Select distinct POId from trn.InventoryReceivedetail where POId is not null)	AND PO.CompanyId='" + companyId + @"' AND PO.PlantId='" + PlantId + @"' 			
									AND DATEDIFF(day,PO.PODate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
									AND PO.CheckedByStatus !='Reject' AND PO.IsClosed=0 AND PLC.Status='Active'		
							GROUP BY PO.CompanyId,PO.Id,PO.PODate,PO.DocRefNo,PO.DocDate,PO.ContractId,PO.PurchaseLCId,PT.PaymentMode,PO.AddedBy,EI.EmployeeName,EI1.EmployeeName,PO.CheckedByStatus,PO.AuthorizedByStatus,CG.UserName,C.UserName,P1.UserName";

                    }


                    #endregion
                    #region Acceptance Pending For GRN
                    if (Category == "Acceptance Pending For GRN" && days == RequestDay)
                    {
                        sql = @"SELECT 'Invoice Pending For Acceptance' Category
								,PDA.CompanyGroupId--,PDA.PlantId		
								,CG.UserName CompanyGroup
								,C.UserName Company
								,P2.UserName PlantName	
								,DaysCount=CASE WHEN DATEDIFF(day,PDA.EntryDate,getdate()) >0  ANd DATEDIFF(day,PDA.EntryDate,getdate())<=3 THEN DATEDIFF(day,PDA.EntryDate,getdate()) ELSE 0 END
								,PDA.AcceptanceDate
								,PDA.AcceptanceNo
								,PDA.AcceptanceRate
								,PDA.PurchaseLCId	
								,PDA.PrePurchaseInvoiceId
								,sum(PDAD.Qty) Qty
								,sum(PDAD.Total3Value)/sum(PDAD.Qty) Rate
								,sum(PDAD.Total3Value) Amount,PDA.Id

						FROM trn.PurchaseDocAcceptance PDA
						LEFT JOIN (Select PurchaseDocAcceptanceId ,Sum(TransactionQty) Qty,Sum(MaterialTranAmount) Total3Value from TRN.PurchaseDocAcceptanceDetail GROUp bY PurchaseDocAcceptanceId) AS PDAD ON PDAD.PurchaseDocAcceptanceId=PDA.Id
						LEFT JOIN [dbo].[PrePurchaseInvoice] PPI ON PPI.Id=PDA.PrePurchaseInvoiceId
							LEFT JOIN ORG.CompanyGroup CG ON CG.Id=PDA.CompanyGroupId
							LEFT JOIN ORG.Company C ON C.Id=PDA.CompanyId
							LEFT JOIN ORG.Plant P2 ON p2.Id=PDA.PlantId
						WHERE PDA.Id not in (select PurchaseDocAcceptanceId from trn.InventoryReceive where PurchaseDocAcceptanceId is not null)	AND PDA.CompanyId='" + companyId + @"' AND PDA.PlantId='" + PlantId + @"' 
						AND DATEDIFF(day,PDA.EntryDate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
						GROUP BY PDA.CompanyGroupId,DATEDIFF(day,PDA.EntryDate,getdate()),CG.UserName,C.UserName,P2.UserName,PDA.AcceptanceDate,PDA.AcceptanceNo,PDA.AcceptanceRate,PDA.PurchaseLCId,PDA.PrePurchaseInvoiceId,PDA.Id";

                    }


                    #endregion
                    //#endregion


                    #region Pending For GRN
                    if (Category == "Pending For GRN" && days == RequestDay)
                    {
                        sql = @"SELECT 'Pending GRN' Category
								,G.CompanyId,G.Id AS GateEntryNo,G.PlantId,G.EntryDate,isnull(P1.UserName,'') UserName,G.PackageQty,G.ModeofTransport,G.Bill,G.PersonName,G.MobileNo,G.GateEntryType	
								,CG.UserName CompanyGroup
								,C.UserName Company
								,P2.UserName PlantName
								,DaysCount=CASE WHEN DATEDIFF(day,G.EntryDate,getdate()) >0  THEN DATEDIFF(day,G.EntryDate,getdate()) ELSE 0 END
								,isnull(ei2.EmployeeName,'') EmployeeName
								--,sum(IRD.TransactionQty) Qty
								--,sum(IRD.MaterialTranRate) Rate
								--,sum(IRD.TotalMaterialBooksCurrencyAmount) Total3Value
							FROM TRN.[GateEntry] G
							LEFT Join hkp.Party p ON P.Id= G.PartyId
							LEFT Join ORG.CompanyGroup CG ON CG .Id= G.CompanyGroupId
							LEFT Join ORG.Company C ON C.Id= G.CompanyId
							LEFT Join ORG.Plant P2 ON P2.Id= G.PlantId
							Left join trn.InventoryReceive IR ON IR.GateEntryNo=G.Id
							LEFT JOIN trn.InventoryReceiveDetail IRD ON IRD.InventoryReceiveId=IR.Id
							LEFT JOin dbo.EmployeeInformation EI ON  EI.SystemId=G.EmployeeId
							LEFT JOin dbo.EmployeeInformation EI1 ON  EI1.SystemId=G.EmployeeIdForGateEntry
							LEFT JOIN dbo.PlantWiseGate PWG ON PWG.Id=G.PlantWiseGateId
							Left JOIN SEC.UserPlantGate UPG ON UPG.PlantGateId=PWG.Id
							LEFT JOIN hkp.Party p1 ON p1.Code=G.PartyId
							LEFT JOIn employeeinformation ei2 on ei2.systemid=G.EmployeeIdForGateEntry
							Where G.FlagStatus!='Cancel' AND G.CompanyId='" + companyId + @"' AND G.PlantId='" + PlantId + @"' 
							AND G.Id not in (select GateEntryNo from trn.InventoryReceive where GateEntryNo is not null)
							AND G.Id  not in(select GateEntryNo from [TRN].[ServiceAcknowledgementMaster] where GateEntryNo is not null)
							--AND  CONVERT(DATE, G.EntryDate)<Convert(date,GETDATE())
							AND DATEDIFF(day,G.EntryDate,getdate()) between '" + fromDate + "' and '" + toDate + @"'
							GROUP BY G.CompanyId, G.Id,G.PlantId,G.EntryDate,G.PartyId,G.PackageQty,G.ModeofTransport
							,G.Bill,G.PersonName,G.MobileNo,G.GateEntryType,P1.UserName,CG.UserName,C.UserName,P2.UserName,ei2.EmployeeName";

                    }

                    #endregion
                    #region Pending GRN For Approval
                    if (Category == "Pending GRN For Approval" && days == RequestDay)
                    {
                        sql = @"SELECT 'Pending GRN For Approval' Category
							,G.CompanyId,G.Id GateEntryNo,G.PlantId,G.EntryDate,isnull(P1.UserName,'') UserName,G.PackageQty,G.ModeofTransport,G.Bill,G.PersonName,G.MobileNo,G.GateEntryType	
							,CG.UserName CompanyGroup
							,C.UserName Company
							,P2.UserName PlantName
							,DaysCount=CASE WHEN DATEDIFF(day,G.EntryDate,getdate()) >0  THEN DATEDIFF(day,G.EntryDate,getdate()) ELSE 0 END
							,isnull(ei2.EmployeeName,'') EmployeeName
							,sum(IRD.TransactionQty) Qty
							,sum(IRD.MaterialTranRate) Rate
							,FORMAT(sum(IRD.TotalMaterialBooksCurrencyAmount),'#,#') Amount,IR.Id GRNNo
							,ApprovedBY.EmployeeName ApproveBy
						FROM trn.InventoryReceive IR 
						LEFT JOIN TRN.[GateEntry] G ON IR.GateEntryNo=G.Id
						LEFT Join hkp.Party p ON P.Id= G.PartyId
						LEFT Join ORG.CompanyGroup CG ON CG .Id= G.CompanyGroupId
						LEFT Join ORG.Company C ON C.Id= G.CompanyId
						LEFT Join ORG.Plant P2 ON P2.Id= G.PlantId
						LEFT JOIN (select InventoryReceiveId,sum(TransactionQty) TransactionQty
																,sum(MaterialTranRate) MaterialTranRate
																,sum(TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount 
															from  trn.InventoryReceiveDetail
														Group By InventoryReceiveId)IRD ON IRD.InventoryReceiveId=IR.Id
						LEFT JOin dbo.EmployeeInformation EI ON  EI.SystemId=G.EmployeeId
						LEFT JOin dbo.EmployeeInformation EI1 ON  EI1.SystemId=G.EmployeeIdForGateEntry
						LEFT JOIN dbo.PlantWiseGate PWG ON PWG.Id=G.PlantWiseGateId
						Left JOIN SEC.UserPlantGate UPG ON UPG.PlantGateId=PWG.Id
						LEFT JOIN hkp.Party p1 ON p1.Code=G.PartyId
						LEFT JOIn employeeinformation ei2 on ei2.systemid=G.EmployeeIdForGateEntry
						LEFT JOIn employeeinformation ApprovedBY on ApprovedBY.systemid=IR.AuthorizedBy
						Where IR.AuthorizedByStatus='For Approval' 	
						--Where  Isnull(IR.AuthorizedByStatus,'') != 'Approved' AND (Isnull(IR.CheckedByStatus,'') != 'Reject' OR  IR.AuthorizedByStatus='Reject')
						AND G.CompanyId='" + companyId + @"' AND G.PlantId='" + PlantId + @"' 	
						AND DATEDIFF(day,G.EntryDate,getdate()) between '" + fromDate + "' and '" + toDate + @"'
						GROUP BY G.CompanyId, G.Id,G.PlantId,G.EntryDate,G.PartyId,G.PackageQty,G.ModeofTransport
						,G.Bill,G.PersonName,G.MobileNo,G.GateEntryType,P1.UserName,CG.UserName,C.UserName,P2.UserName,ei2.EmployeeName,IR.Id,ApprovedBY.EmployeeName";

                    }

					#endregion
					#region Pending GRN Posting
					if (Category == "Pending GRN For Checking" && days == RequestDay)
					{
						sql = @"SELECT 'Pending GRN For Checking' Category
							,IR.CompanyId
							,CG.UserName CompanyGroup
							,C.UserName Company
							,P2.UserName PlantName
							,DaysCount=CASE WHEN DATEDIFF(day,IR.GRNDate,getdate()) Between 0 and 3 THEN DATEDIFF(day,IR.GRNDate,getdate()) ELSE 0 END
							,IR.Id GRNNo
							,IR.DocDate
							,IR.DocRefNo
							,EI.EmployeeName  CheckedBy
							,IR.CheckedByStatus
							,EI1.EmployeeName AuthorizedBy
							,IR.AuthorizedByStatus
							,sum(IRD.TransactionQty) Qty
							,sum(IRD.MaterialTranRate) Rate
							,FORMAT(sum(IRD.TotalMaterialBooksCurrencyAmount),'#,#') Amount
							,REPLACE(CONVERT(CHAR(11), IR.GRNDate, 106),' ','-') AS GRNDate
							,p3.UserName PartyName,IR.GateEntryNo
							FROM trn.InventoryReceive IR 
							LEFT JOIN ( select IRD.InventoryReceiveId,sum(IRD.TransactionQty) TransactionQty
														,sum(IRD.MaterialTranRate) MaterialTranRate
														,sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
														from trn.InventoryReceiveDetail IRD group by IRD.InventoryReceiveId) IRD ON IRD.InventoryReceiveId=IR.Id   
							LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=IR.CheckedBy
							LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=IR.AuthorizedBy
							LEFT JOIN ORG.CompanyGroup CG ON CG.Id=IR.CompanyGroupId
							LEFT JOIN ORG.Company C ON C.Id=IR.CompanyId
							LEFT JOIN ORG.Plant P2 ON p2.Id=IR.PlantId
							LEFT JOIN HKP.Party P3 ON p3.Id=IR.PartyId
							Where IR.CheckedByStatus='ForChecked'
											ANd IR.CheckedBy is not null
											AND IR.Status is null 
											AND DATEDIFF(day,IR.GRNDate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
							AND IR.CompanyId='" + companyId + @"' AND IR.PlantId='" + PlantId + @"' 						
							 GROUP BY IR.CompanyId,IR.Id,IR.DocDate,IR.DocRefNo,EI.EmployeeName,IR.CheckedByStatus,IR.GateEntryNo	,EI1.EmployeeName ,IR.AuthorizedByStatus,DATEDIFF(day,IR.GRNDate,getdate()),CG.UserName,C.UserName,P2.UserName,IR.GRNDate,p3.UserName";

					}

					#endregion
					#region Pending GRN Posting
					if (Category == "Pending GRN Posting" && days == RequestDay)
                    {
                        sql = @"SELECT 'Pending GRN Posting' Category
							,IR.CompanyId
							,CG.UserName CompanyGroup
							,C.UserName Company
							,P2.UserName PlantName
							,DaysCount=CASE WHEN DATEDIFF(day,IR.GRNDate,getdate()) Between 0 and 3 THEN DATEDIFF(day,IR.GRNDate,getdate()) ELSE 0 END
							,IR.Id GRNNo
							,IR.DocDate
							,IR.DocRefNo
							,EI.EmployeeName  CheckedBy
							,IR.CheckedByStatus
							,EI1.EmployeeName AuthorizedBy
							,IR.AuthorizedByStatus
							,sum(IRD.TransactionQty) Qty
							,sum(IRD.MaterialTranRate) Rate
							,FORMAT(sum(IRD.TotalMaterialBooksCurrencyAmount),'#,#') Amount
							,REPLACE(CONVERT(CHAR(11), IR.GRNDate, 106),' ','-') AS GRNDate
							,p3.UserName PartyName
							FROM trn.InventoryReceive IR 
							LEFT JOIN ( select IRD.InventoryReceiveId,sum(IRD.TransactionQty) TransactionQty
														,sum(IRD.MaterialTranRate) MaterialTranRate
														,sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
														from trn.InventoryReceiveDetail IRD group by IRD.InventoryReceiveId) IRD ON IRD.InventoryReceiveId=IR.Id   
							LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=IR.CheckedBy
							LEFT JOIN dbo.EmployeeInformation EI1 ON EI1.SystemId=IR.AuthorizedBy
							LEFT JOIN ORG.CompanyGroup CG ON CG.Id=IR.CompanyGroupId
							LEFT JOIN ORG.Company C ON C.Id=IR.CompanyId
							LEFT JOIN ORG.Plant P2 ON p2.Id=IR.PlantId
							LEFT JOIN HKP.Party P3 ON p3.Id=IR.PartyId
							Where IR.CheckedByStatus='Checked'
											And IR.AuthorizedByStatus='Approved' 
											ANd IR.CheckedBy is not null
											And IR.AuthorizedBy is not null		
											AND IR.CheckedByStatus !='Reject'
											AND IR.AuthorizedByStatus !='Reject'
											AND IR.Status is null 
											AND DATEDIFF(day,IR.GRNDate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
							AND IR.CompanyId='" + companyId + @"' AND IR.PlantId='" + PlantId + @"' 						
							 GROUP BY IR.CompanyId,IR.Id,IR.DocDate,IR.DocRefNo,EI.EmployeeName,IR.CheckedByStatus	,EI1.EmployeeName ,IR.AuthorizedByStatus,DATEDIFF(day,IR.GRNDate,getdate()),CG.UserName,C.UserName,P2.UserName,IR.GRNDate,p3.UserName";

                    }

                    #endregion
                    #region Pending  Issue Request  For Approval
                    if (Category == "Pending  Issue Request  For Approval" && days == RequestDay)
                    {
                        sql = @"SELECT 'Pending  Issue Request  For Approval' Category		
								,IRM.CompanyId
									,CG.UserName CompanyGroup
									,C.UserName Company
									,P2.UserName PlantName
									,DaysCount=CASE WHEN DATEDIFF(day,IRM.AddedDate,getdate()) >0  ANd DATEDIFF(day,IRM.AddedDate,getdate())<=3 THEN DATEDIFF(day,IRM.AddedDate,getdate()) ELSE 0 END
								,IRM.Id	IssueRequestNo
								,EI.EmployeeName PreparedBy
								,sum(isnull(IR.RequestedQty,0)) Qty
								,sum(isnull(0,0)) Rate
								,FORMAT(sum(isnull(0,0)),'#,#') Amount,REPLACE(CONVERT(CHAR(11), IRM.AddedDate, 106),' ','-') AS IssueRequestDate
								FROM trn.IssueRequestMaster IRM
								LEFT JOIN trn.IssueRequest IR ON IRM.Id=IR.IssueRequestMasterId   
								LEFT JOIN dbo.EmployeeInformation EI ON EI.SystemId=IRM.AddedBy
									LEFT JOIN ORG.CompanyGroup CG ON CG.Id=IRM.CompanyGroupId
									LEFT JOIN ORG.Company C ON C.Id=IRM.CompanyId
									LEFT JOIN ORG.Plant P2 ON p2.Id=IRM.PlantId
								Where DATEDIFF(day,IRM.AddedDate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'  
							    AND IRM.CompanyId='" + companyId + @"' AND IRM.PlantId='" + PlantId + @"' 
								AND (IRM.CheckedByStatus !='Reject'And IRM.CheckedByStatus !='ForChecked' ) AND (irm.AuthorizedByStatus!='Approved' and irm.AuthorizedByStatus!='Reject')
								AND IRM.Id not in(select IssueRequestMasterId from trn.InventoryIssue where IssueRequestMasterId is not null)								
								GROUP BY IRM.CompanyId,IRM.Id,EI.EmployeeName,DATEDIFF(day,IRM.AddedDate,getdate()),CG.UserName,C.UserName,P2.UserName,IRM.AddedDate";

                    }

                    #endregion
                    #region pending expense booking
                    if (Category == "Pending Inventory Issue Posting" && days == RequestDay)
                    {
                        sql = @"SELECT 'Pending Inventory Issue Posting' Category			
									, II.CompanyId	
									,CG.UserName CompanyGroup
									,C.UserName Company
									,P2.UserName PlantName
									,DaysCount=CASE WHEN DATEDIFF(day,II.AddedDate,getdate()) >0  ANd DATEDIFF(day,II.AddedDate,getdate())<=3 THEN DATEDIFF(day,II.AddedDate,getdate()) ELSE 0 END
									,II.Id AS IssueNo
									,II.AddedBy
									,sum(isnull(IID.TransactionQty,0)) Qty
									,sum(isnull(IID.PolicyRate,0)) Rate
									,FORMAT(sum(isnull(IID.PolicyAmount,0)),'#,#') Amount
									,REPLACE(CONVERT(CHAR(11), II.AddedDate, 106),' ','-') AS IssueDate
								FROM trn.InventoryIssue II
									 JOIN trn.InventoryIssueDetail IID ON IID.InventoryIssueId=II.Id
									--LEFT JOIN trn.InventoryIssueHistory IIH ON IIH.InventoryIssueDetailId=IID.Id
									LEFT JOIN ORG.CompanyGroup CG ON CG.Id=II.CompanyGroupId
									LEFT JOIN ORG.Company C ON C.Id=II.CompanyId
									LEFT JOIN ORG.Plant P2 ON p2.Id=II.PlantId
									Where DATEDIFF(day,II.IssueDate,getdate()) Between '" + fromDate + @"' ANd '" + toDate + @"'
									AND II.CompanyId='" + companyId + @"' AND II.PlantId='" + PlantId + @"' 
									AND II.VoucherId IS null AND ii.IssueType='Revenue' AND II.IsPostingRequired=1
								GROUP BY II.CompanyId,II.Id,II.AddedBy,DATEDIFF(day,II.AddedDate,getdate()),CG.UserName,C.UserName,P2.UserName,II.AddedDate";

                    }

                    #endregion




                }
                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Accounts.ToString()));
            }
        }

        public IEnumerable<object> ModalExpenseDetail(IEnumerable<ChartColumnList> ChartColumnList, int seq
            , string budgetId, string factDate, string fromDate, string toDate, string companyGroupId, string companyId, string entryPeriodId, string postingPeriodId, string expenseORRevenue, string periodType)
        {
            var cList = string.Empty;
            var cListId = string.Empty;
            var join = string.Empty;
            var wc = string.Empty;
            var cListextG = string.Empty;
            var cListextIdG = string.Empty;
            //Array[] ChartColumnListM2 = ChartColumnListM;

            var id = string.Empty;
            var columnName = string.Empty;
            var rType = string.Empty;
            var sequence = string.Empty;
            var text = string.Empty;

            try
            {
                var expFactDate = string.Empty;
                var condition = string.Empty;

                expFactDate = "AND CONVERT(DATE,V.PostingDate) <= CONVERT(DATE,GETDATE())";
                if (factDate == "postingDate")
                {
                    if (periodType == "ALL")
                    {
                        condition = " AND V.PostingDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "FORTHEDAY")
                    {
                        condition = "AND V.PostingDate BETWEEN CONVERT(DATE,'" + toDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "FORTHEPERIOD")
                    {
                        condition = @" AND V.PostingDate BETWEEN (SELECT  StartDate FROM SCS.FiscalYearPeriod where '" + toDate + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + toDate + @"' between StartDate and EndDate)";
                    }
                    if (periodType == "")

                    {
                        condition = "AND FYPA.EntryPeriodId = '" + entryPeriodId + @"' AND EFYP.Id = '" + postingPeriodId + @"' AND V.PostingDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "DELAY")
                    {
                        condition = @"AND CONVERT(DATE,V.AddedDate) = CONVERT(DATE, '" + toDate + @"') AND MONTH(V.PostingDate) < MONTH('" + toDate + @"') AND YEAR(V.PostingDate) <= YEAR('" + toDate + @"')";
                    }
                }
                else if (factDate == "AddedDate")
                {
                    if (periodType == "ALL")
                    {
                        condition = "AND V.AddedDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "FORTHEDAY")
                    {
                        condition = "AND V.AddedDate BETWEEN CONVERT(DATE,'" + toDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "FORTHEPERIOD")
                    {
                        condition = @" AND V.AddedDate BETWEEN (SELECT  StartDate FROM SCS.FiscalYearPeriod where '" + toDate + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + toDate + @"' between StartDate and EndDate)";
                    }
                    if (periodType == "")

                    {
                        condition = "AND FYPA.EntryPeriodId = '" + entryPeriodId + @"' AND EFYP.Id = '" + postingPeriodId + @"' AND V.AddedDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "DELAY")
                    {
                        condition = @"AND CONVERT(DATE,V.AddedDate) = CONVERT(DATE, '" + toDate + @"') AND MONTH(V.PostingDate) < MONTH('" + toDate + @"') AND YEAR(V.PostingDate) <= YEAR('" + toDate + @"')";
                    }
                }
                else
                {
                    condition = "";
                }
                seq += 1;
                foreach (var item in ChartColumnList)
                {
                    if (item.Sequence != -2 && item.Sequence != -1)
                    {
                        if (item.RType == "Entity")
                        {
                            cList += "," + item.StandardName + ".UserName " + item.StandardName + " ";

                            if (item.ColumnName == "EmployeeGroup")
                            {
                                join += "LEFT JOIN [HKP].[" + item.StandardName + "] ON " + item.StandardName + ".Id = E." + item.StandardName + "Id\n";
                            }
                            else
                            {
                                join += "LEFT JOIN [ORG].[" + item.StandardName + "] ON " + item.StandardName + ".Id = E." + item.StandardName + "Id\n";
                            }
                        }
                        //else
                        //{
                        //	cList += "," + item.ColumnName + ".UserName " + item.ColumnName + " ";
                        //	join += "LEFT JOIN [ORG].[" + item.ColumnName + "] ON " + item.ColumnName + ".Id = Po." + item.ColumnName + "Id\n";

                        //}
                    }

                    if (item.Sequence != -2)
                    {
                        if (item.Sequence == -1)
                        {
                            wc = " and  C.Id ='" + item.Id + "'";
                        }
                        else
                        {
                            if (item.Sequence < seq)
                            {
                                wc += " AND " + item.StandardName + ".Id='" + item.Text + "'";
                            }
                        }
                    }
                }

                var sql = @"SELECT	BC.UserName AS BudgetCategoryName,B.Id BudgetId
							    " + cList + @"
								,cmp.Id AS CompanyId
								,BSC.UserName AS BudgetSubCategoryName
								,B.UserName AS BudgetName
                                ,Amount=CASE WHEN (CASE WHEN ACT.BalanceType = 'Debit' THEN VDC.DrAmount-VDC.CrAmount ELSE 0 END)=0 then 
								CASE WHEN ACT.BalanceType = 'Credit' THEN VDC.crAmount-VDC.DrAmount ELSE 0 END ELSE (CASE WHEN ACT.BalanceType = 'Debit' THEN VDC.DrAmount-VDC.CrAmount ELSE 0 END) END
								 
								,V.Id VoucherId,V.VoucherNo,v.DocRefNo,Replace(CONVERT(VARCHAR(11), V.DocDate, 106), ' ', '-') DocDate,Replace(CONVERT(VARCHAR(11), V.PostingDate, 106), ' ', '-') PostingDate
								FROM TRN.VoucherDetailCurrency AS VDC
								JOIN TRN.VoucherDetail AS VD ON VD.Id=VDC.VoucherDetailId
								JOIN TRN.Voucher AS V ON V.Id =VD.VoucherId
								LEFT JOIN ORG.Company AS CMP on CMP.Id = V.CompanyId
								LEFT JOIN ORG.CompanyGroup AS CMPGR on CMPGR.Id = V.CompanyGroupId
								LEFT JOIN MST.BudgetMaster AS BM ON BM.Id =VD.BudgetMasterId
								LEFT JOIN HKP.Budget AS B ON B.Id=BM.BudgetId
								LEFT JOIN HKP.BudgetSubCategory AS BSC ON BSC.Id=BM.BudgetSubCategoryId
								LEFT JOIN HKP.BudgetCategory AS BC ON BC.Id=BM.BudgetCategoryId
								LEFT JOIN ORG.Entity AS E ON E.Id = VD.EntityId
                                LEFT JOIN HKP.GLGeneralInfo AS GL ON GL.Id=BM.GLGeneralInfoId
					            LEFT JOIN HKP.AccountGroup AS AG ON AG.Id=GL.AccountGroupId
					            LEFT JOIN HKP.AccountType AS ACT ON ACT.Id=AG.AccountTypeId
								LEFT JOIN SCS.FiscalYearPeriod AS EFYP ON EFYP.Id=VD.FiscalYearPeriodId
                                LEFT OUTER JOIN (SELECT Id AS EntryPeriodId, PeriodName,StartDate,EndDate FROM SCS.FiscalYearPeriod  )AS
								    FYPA ON MONTH(CONVERT(DATE,FYPA.EndDate))=MONTH(CONVERT(DATE,VD.AddedDate))
								    AND  YEAR(CONVERT(DATE,FYPA.EndDate))=YEAR(CONVERT(DATE,VD.AddedDate))
								LEFT JOIN ORG.Company AS C ON C.Id = V.CompanyId
											" + join + @"
								LEFT JOIN (SELECT * FROM SCS.CompanyParallelCurrency WHERE ParallelCurrencyType='CompanyCurrency') as CPC ON CPC.CurrencyId=VDC.ParallelCurrencyId
								WHERE  VD.BudgetMasterId  IS NOT NULL " + condition + @" AND  CPC.ParallelCurrencyType='CompanyCurrency' AND V.IsPark = 0
								 AND	BM.BudgetId = " + budgetId + @" and FYPA.EntryPeriodId = '" + entryPeriodId + @"' and EFYP.Id = '" + postingPeriodId + @"'  AND ACT.IsBalanceSheet =  0  AND ACT.Id = '" + expenseORRevenue + @"' ";

                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Accounts.ToString()));
            }
        }

        public GridModel ModalVoucharDetail(GridParameter parameter, string voucharNo, string budgetId, string factDate, string fromDate, string toDate, string companyGroupId, string companyId, string expenseORRevenue, string periodType)
        {
            string cList = string.Empty;
            string cListId = string.Empty;
            string join = string.Empty;
            string wc = string.Empty;
            string cListextG = string.Empty;
            string cListextIdG = string.Empty;

            try
            {
                string expFactDate = string.Empty;
                string condition = string.Empty;

                IEnumerable<OrgStructureListViewModel> OrgStrList = OrgStructureListM(companyGroupId, companyId);
                expFactDate = "AND CONVERT(DATE,V.PostingDate) <= CONVERT(DATE,GETDATE())";
                if (factDate == "postingDate")
                {
                    if (periodType == "ALL")
                    {
                        condition = "AND V.PostingDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "FORTHEDAY")
                    {
                        condition = "AND V.PostingDate BETWEEN CONVERT(DATE,'" + toDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "FORTHEPERIOD")
                    {
                        condition = @" AND V.PostingDate BETWEEN (SELECT  StartDate FROM SCS.FiscalYearPeriod where '" + toDate + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + toDate + @"' between StartDate and EndDate)";
                    }

                }
                else if (factDate == "AddedDate")
                {
                    if (periodType == "ALL")
                    {
                        condition = "AND V.AddedDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "FORTHEDAY")
                    {
                        condition = "AND V.AddedDate BETWEEN CONVERT(DATE,'" + toDate + @"') AND CONVERT(DATE,'" + toDate + @"')";
                    }
                    if (periodType == "FORTHEPERIOD")
                    {
                        condition = @" AND V.AddedDate BETWEEN (SELECT  StartDate FROM SCS.FiscalYearPeriod where '" + toDate + @"' between StartDate and EndDate)
                                              AND(SELECT  EndDate FROM SCS.FiscalYearPeriod where '" + toDate + @"' between StartDate and EndDate)";
                    }
                }
                else
                {
                    condition = "";
                }
                foreach (var item in OrgStrList)
                {
                    if (item.RType == "Entity")
                    {
                        cList += "," + item.StandardName + ".UserName " + item.StandardName + " ";

                        if (item.StandardName == "EmployeeGroup")
                        {
                            join += "LEFT JOIN [HKP].[" + item.StandardName + "] AS " + item.StandardName + " ON " + item.StandardName + ".Id = E." + item.StandardName + "Id\n";
                        }
                        else
                        {
                            join += "LEFT JOIN [ORG].[" + item.StandardName + "] AS " + item.StandardName + " ON " + item.StandardName + ".Id = E." + item.StandardName + "Id\n";
                        }
                    }
                    else
                    {
                        //cGList += "," + item.ColumnName + ".UserName";
                        cList += "," + item.StandardName + ".UserName " + item.StandardName + " ";
                        join += "LEFT JOIN [ORG].[" + item.StandardName + "] AS " + item.StandardName + " ON " + item.StandardName + ".Id = Po." + item.StandardName + "Id\n";
                    }
                }

                parameter.CmdText = @"SELECT  GLGI.AccountCode+' - '+GLGI.UserName AS GLGeneralInfoName, PT.Code+' - '+PT.UserName As PartyName, VD.BudgetMasterId,B.Id BudgetId, B.UserName AS BudgetName, VD.ActivityId, A.UserName AS ActivityName,
                                        V.VoucherNo, Replace(CONVERT(VARCHAR(11), V.DocDate, 106), ' ', '-') DocDate ,Replace(CONVERT(VARCHAR(11), V.PostingDate, 106), ' ', '-') PostingDate, VD.DocRefNo, V.Narration, VD.EntityId,VD.PlantId,  VD.VoucherId,
                                        VD.Id AS VoucherDetailId, V.CurrencyId, C.Code AS CurrencyCode, VD.PartyId,
										CC.CompanyCurrencyId, CC.CompanyFromCurrencyId, CC.ToCurrencyId, CC.CompanyCurrencyRate,CC.CompanyCurrencyDrAmount,CC.CompanyCurrencyCrAmount, CC.CompanyCurrencyConversion,
										GC.CompanyGroupCurrencyId, GC.CompanyGroupFromCurrencyId, GC.CompanyGroupCurrencyAmount,GC.CompanyGroupCurrencyRate, GC.CompanyGroupCurrencyConversion,
										HC.HardCurrencyId, HC.HardFromCurrencyId, HC.HardCurrencyRate, HC.HardCurrencyConversion
                                               FROM
											   [TRN].[VoucherDetail] AS VD
                                               LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
                                               LEFT JOIN [HKP].[GLGeneralInfo] AS GLGI ON GLGI.Id=VD.GLGeneralInfoId
                							   LEFT JOIN [MST].[BudgetMaster] AS BM ON BM.Id=VD.BudgetMasterId
                							   LEFT JOIN [HKP].[Budget] AS B ON B.Id=BM.BudgetId
                							   LEFT JOIN [HKP].[Activity] AS A ON A.Id=VD.ActivityId
                                               LEFT JOIN [SCS].[Currency] AS C ON C.Id=V.CurrencyId
                                               LEFT JOIN [HKP].[Party] AS PT ON PT.Id=VD.PartyId
	                                           LEFT JOIN HKP.GLGeneralInfo AS GL ON GL.Id=BM.GLGeneralInfoId
					                           LEFT JOIN HKP.AccountGroup AS AG ON AG.Id=GL.AccountGroupId
					                           LEFT JOIN HKP.AccountType AS ACT ON ACT.Id=AG.AccountTypeId
                						LEFT JOIN (
                						SELECT VDC.ParallelCurrencyId AS CompanyCurrencyId, VDC.FromCurrencyId AS CompanyFromCurrencyId, VDC.ToCurrencyId,
                						VDC.ToCurrencyRate AS CompanyCurrencyRate, VDC.ToCurrencyConversion AS CompanyCurrencyConversion, VDC.DrAmount AS CompanyCurrencyDrAmount,VDC.CrAmount AS CompanyCurrencyCrAmount, VDC.VoucherDetailId
                						FROM [TRN].[VoucherDetailCurrency] AS VDC
                						JOIN [SCS].[CompanyParallelCurrency] AS CPC ON CPC.CurrencyId=VDC.ParallelCurrencyId
                						WHERE CPC.ParallelCurrencyType='CompanyCurrency' AND CPC.CompanyId='" + companyId + @"'
										) AS CC ON CC.VoucherDetailId=VD.Id
										LEFT JOIN (
										SELECT VDC.ParallelCurrencyId AS CompanyGroupCurrencyId, VDC.FromCurrencyId AS CompanyGroupFromCurrencyId, VDC.ToCurrencyId,
											VDC.ToCurrencyRate AS CompanyGroupCurrencyRate, VDC.ToCurrencyConversion AS CompanyGroupCurrencyConversion, VDC.DrAmount AS CompanyGroupCurrencyAmount, VDC.VoucherDetailId
											FROM [TRN].[VoucherDetailCurrency] AS VDC
											JOIN [SCS].[CompanyParallelCurrency] AS CPC ON CPC.CurrencyId=VDC.ParallelCurrencyId
											WHERE CPC.ParallelCurrencyType='CompanyGroupCurrency' AND CPC.CompanyId='" + companyId + @"'
										) AS GC ON GC.VoucherDetailId=VD.Id
										LEFT JOIN (
											SELECT VDC.ParallelCurrencyId AS HardCurrencyId, VDC.FromCurrencyId AS HardFromCurrencyId, VDC.ToCurrencyId,
											VDC.ToCurrencyRate AS HardCurrencyRate, VDC.ToCurrencyConversion AS HardCurrencyConversion, VDC.DrAmount AS HardCurrencyAmount, VDC.VoucherDetailId
											FROM [TRN].[VoucherDetailCurrency] AS VDC
											JOIN [SCS].[CompanyParallelCurrency] AS CPC ON CPC.CurrencyId=VDC.ParallelCurrencyId
											WHERE CPC.ParallelCurrencyType='HardCurrency' AND CPC.CompanyId= '" + companyId + @"'
										) AS HC ON HC.VoucherDetailId=VD.Id
										WHERE  V.VoucherNo='" + voucharNo + @"' AND V.IsPark = 0 ";

                return _sqlRepository.GetGridData(parameter);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Accounts.ToString()));
            }
        }

        public IEnumerable<object> GetBudgetMasterWiseAmount(string companyGroupId, string companyId, string plantId, string divisionId, string subDivisionId, string unitId, string budgetCategory, string budgetSubCategory, string budget, string Activity, string budgetMasterId, string fromDate, string toDate, string periodName, string dateType, string dayOrPeriod, string PostingPeriodId, string EntryPeriodId)
        {
            var bCId = string.Empty; var bCSId = string.Empty; var bId = string.Empty;
            var company = string.Empty;
            var plant = string.Empty;
            var division = string.Empty;
            var subDivision = string.Empty;
            var unit = string.Empty;
            var periodChange = string.Empty;

            if (dayOrPeriod == "day")
                fromDate = toDate;

            try
            {
                var cmdText = @"SELECT  BC.UserName AS [BudgetCategory],BSC.UserName AS [BudgetSubCategory],B.UserName AS [Budget]
									,Amount=CASE WHEN ISNULL(VDC.DrAmount,0)=0 THEN VDC.CrAmount ELSE VDC.DrAmount END
									,EFYP.PeriodName PostingPeriod,FYPA.PeriodName EntryPeriod
									,EVD.BudgetMasterId,EVD.Id,EVD.VoucherId,FYPA.PeriodName as EntryPeriod
									,V.VoucherNo,REPLACE(CONVERT(VARCHAR(11),V.VoucherDate, 106), ' ', '-') VoucherDate
                                    ,V.VoucherNo,REPLACE(CONVERT(VARCHAR(11),V.PostingDate, 106), ' ', '-') PostingDate
									FROM TRN.VoucherDetailCurrency AS VDC
									LEFT JOIN TRN.VoucherDetail AS EVD ON EVD.Id=VDC.VoucherDetailId
									LEFT JOIN TRN.Voucher AS V ON V.Id=EVD.VoucherId
									LEFT JOIN SCS.FiscalYearPeriod AS EFYP ON EFYP.Id=EVD.FiscalYearPeriodId
									LEFT JOIN MST.BudgetMaster AS BM ON BM.Id=EVD.BudgetMasterId
									LEFT JOIN HKP.BudgetCategory AS BC ON BC.Id=BM.BudgetCategoryId
									LEFT JOIN HKP.BudgetSubCategory AS BSC ON BSC.Id=BM.BudgetSubCategoryId
									LEFT JOIN HKP.Budget AS B ON B.Id=BM.BudgetId
									LEFT JOIN ORG.Entity AS ENT ON ENT.Id=V.EntityId
								    LEFT OUTER JOIN (SELECT Id AS EntryPeriodId, PeriodName,StartDate,EndDate FROM SCS.FiscalYearPeriod  )AS
								    FYPA ON MONTH(CONVERT(DATE,FYPA.EndDate))=MONTH(CONVERT(DATE,EVD.AddedDate))
								    AND  YEAR(CONVERT(DATE,FYPA.EndDate))=YEAR(CONVERT(DATE,EVD.AddedDate))

									WHERE  CONVERT(DATE, V." + dateType + ") BETWEEN CONVERT(DATE, '" + fromDate + "') AND   CONVERT(DATE, '" + toDate + @"')
                                    AND EFYP.Id ='" + PostingPeriodId + @"' AND FYPA.EntryPeriodId = '" + EntryPeriodId + @"' and AND EVD.IsPark = 0

                                  AND EVD.BudgetMasterId = '" + budgetMasterId + @"'";

                if (!string.IsNullOrEmpty(companyId))
                    cmdText += "AND V.CompanyId='" + companyId + "'";
                if (!string.IsNullOrEmpty(plantId))
                    cmdText += "AND ENT.PlantId='" + plantId + "' ";
                if (!string.IsNullOrEmpty(divisionId))
                    cmdText += "AND ENT.DivisionId ='" + divisionId + "' ";
                if (!string.IsNullOrEmpty(subDivisionId))
                    cmdText += "AND ENT.SubDivisionId='" + subDivisionId + "' ";
                if (!string.IsNullOrEmpty(unitId))
                    cmdText += "AND ENT.UnitId ='" + unitId + "' ";
                if (!string.IsNullOrEmpty(budgetCategory))
                    cmdText += "AND  BBM.budgetCategoryId = '" + budgetCategory + @"'";
                if (!string.IsNullOrEmpty(budgetSubCategory))
                    cmdText += "and BBM.budgetSubCategoryId = '" + budgetSubCategory + "'";
                if (!string.IsNullOrEmpty(budget))
                    cmdText += "and BBM.budgetId = '" + budget + "'";
                if (!string.IsNullOrEmpty(Activity))
                    cmdText += "AND EVD.ActivityId='" + Activity + @"'";

                cmdText += " ORDER BY  V." + dateType + "";

                return _sqlRepository.GetDataCollection(cmdText);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Accounts.ToString()));
            }
        }
        public void UpdateInActive(string ReqId)
        {
            try
            {
                var sql = "update [TRN].[MaterialRequsitionMaster] set InActive=1 where Id='" + ReqId + "'";
                _sqlRepository.GetDataCollection(sql);

            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, "",
                ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }
        public void UpdateInActivePO(string PO)
        {
            try
            {
                var sql = "update [TRN].[PurchaseOrder] set IsClosed=1 where Id='" + PO + "'";
                _sqlRepository.GetDataCollection(sql);

            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, "",
                ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }



        #region Inventory Dashbord status
        public IEnumerable<object> InventoryDashboardStatus(string companyGroupId, string companyId, string plantId, string factDate, string fromDate, string toDate, string groupName, bool ValueOrNumber, string queryString, string queryStringProcess)
        {
            try
            {
                var ValueOrNumber1 = 0;
                if (ValueOrNumber == false)
                {
                    ValueOrNumber1 = 1;
                }
                else
                {
                    ValueOrNumber1 = 0;
                }

                string paramters = "";
                if (queryString != "")
                {
                    if (paramters == "")
                        paramters += "isnull(IM.CompanyId,'') in(" + queryString + ")";
                    else
                        paramters += " AND isnull(IM.CompanyId,'') in(" + queryString + ")";
                }
                if (queryStringProcess != "")
                {
                    if (paramters == "")
                        paramters += " isnull(IM.PlantId,'') in(" + queryStringProcess + ")";
                    else
                        paramters += " AND isnull(IM.PlantId,'') in(" + queryStringProcess + ")";
                }

                var sql = "";

                if (groupName == "groupName" && string.IsNullOrEmpty(fromDate))

                {

                    sql = @"SELECT Res.MaterialType,Res.MaterialTypeID,Res.Sequence

									,Round(sum(Res.opbalTransactionQty-Res.OpeningIssueQty),0) OpeningBalance
									,Round(Sum(Res.opbalTotalMaterialBooksCurrencyAmount-Res.PolicyAmount) ,0)OpeningBalanceAmount

									,Round(sum(Res.ReceivedForThePeriod),0) ReceivedForThePeriod
									,Round(sum(Res.ReceivedForThePeriodAmount),0)  ReceivedForThePeriodAmount

									,Round(Sum(Res.IssueForThePeriod),0) IssueForThePeriod
									,Round(Sum(Res.IssueForThePeriodAmount),0) IssueForThePeriodAmount

									,Round(SUM(Res.IssueReturnQtyForThePeriod),0) IssueReturnQtyForThePeriod
									,Round(SUM(Res.IssueReturnForThePeriodAmount),0) IssueReturnForThePeriodAmount

									,Round(Sum(Res.PurchaseReturnQtyForThePeriod),0)	 PurchaseReturnQtyForThePeriod
									,Round(Sum(Res.PurchaseReturnForThePeriodAmount),0)	 PurchaseReturnForThePeriodAmount

									,Round(Sum(Res.AdjustmentQtyForThePeriod),0)	 AdjustmentQtyForThePeriod
									,Round(Sum(Res.AdjustmentForThePeriodAmount),0)	 AdjustmentForThePeriodAmount

									,Round(Sum(Res.InventorySalesQtyForThePeriod),0)	 InventorySalesQtyForThePeriod
									,Round(Sum(Res.InventorySalesForThePeriodAmount),0)	InventorySalesForThePeriodAmount

									,Round(Sum(Res.InventoryScrapQtyForThePeriod),0)	InventoryScrapQtyForThePeriod
									,Round(Sum(Res.InventoryScrapForThePeriodAmount),0)	InventoryScrapForThePeriodAmount

									,Round(Sum(Res.InventoryTransferQtyForThePeriod),0)	InventoryTransferQtyForThePeriod
									,Round(Sum(Res.InventoryTransferForThePeriodAmount),0) InventoryTransferForThePeriodAmount
									,Round(SUM((((((((isnull(Res.opbalTransactionQty,0)-isnull(Res.OpeningIssueQty,0) + isnull(Res.ReceivedForThePeriod,0))-isnull(Res.IssueForThePeriod,0)-isnull(Res.PurchaseReturnQtyForThePeriod,0))-isnull(Res.AdjustmentQtyForThePeriod,0))+isnull(Res.IssueReturnQtyForThePeriod,0))-isnull(Res.InventorySalesQtyForThePeriod,0))-isnull(Res.InventoryScrapQtyForThePeriod,0))-isnull(Res.InventoryTransferQtyForThePeriod,0))),0) Closing 
									,Round(SUM((((((((isnull(Res.opbalTotalMaterialBooksCurrencyAmount,0)-isnull(Res.PolicyAmount,0) + isnull(Res.ReceivedForThePeriodAmount,0))-isnull(Res.IssueForThePeriodAmount,0)-isnull(Res.AdjustmentForThePeriodAmount,0))-isnull(Res.PurchaseReturnForThePeriodAmount,0))+isnull(Res.IssueReturnForThePeriodAmount,0)-isnull(Res.InventorySalesForThePeriodAmount,0))-isnull(Res.InventoryScrapForThePeriodAmount,0))-isnull(Res.InventoryTransferForThePeriodAmount,0)))),0) ClosingAmount
									FROM (
									--Opening 
									SELECT   
										MT.UserName MaterialType
										,MT.Id MaterialTypeID
										,MT.Sequence 
										,Isnull(opbal.TransactionQty,0) opbalTransactionQty
										,Isnull(opbal.TotalMaterialBooksCurrencyAmount,0) opbalTotalMaterialBooksCurrencyAmount
										--Opening Balance
										--,Round(SUM(isnull(ROUND(opbal.TransactionQty,0),0)-isnull(Round(IFD3.OpeningIssueQty,0),0)),0) As OpeningBalance	
										--,Round(SUM(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)-isnull(IFD3.PolicyAmount,0)),0) AS OpeningBalanceAmount

										--Receive

										,0 AS ReceivedForThePeriod
										,0 AS ReceivedForThePeriodAmount
										----Issue
                         
										,0 IssueForThePeriod	
										,0 IssueForThePeriodAmount	

										--Issue Return
										,0 IssueReturnQtyForThePeriod	
										,0 IssueReturnForThePeriodAmount	

										--Purchase Return
										,0 PurchaseReturnQtyForThePeriod	
										,0 PurchaseReturnForThePeriodAmount	

										--Adjust Return
										,0 AdjustmentQtyForThePeriod	
										,0 AdjustmentForThePeriodAmount	

										--Inventory Sales
										,0 InventorySalesQtyForThePeriod	
										,0 InventorySalesForThePeriodAmount	
										--Inventory Scrap
										,0 InventoryScrapQtyForThePeriod	
										,0 InventoryScrapForThePeriodAmount	

										--Inventory Transfer Data
										,0 InventoryTransferQtyForThePeriod	
										,0 InventoryTransferForThePeriodAmount
										--Opening Issue 
										,0 OpeningIssueQty	
										,0 PolicyAmount


									FROM TRN.InventoryMaterial AS IM
									left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
									LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
									LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
									LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
									LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
									LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
									LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
									LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
									left join( select t.InventoryMaterialId,t.MaterialStorageId,t.IsAsset, t.TransactionQty TransactionQty,t.TotalMaterialBooksCurrencyAmount TotalMaterialBooksCurrencyAmount 
												from (
														SELECT IRD.InventoryMaterialId, IRD.MaterialStorageId,IRD.IsAsset,IRD.TransactionQty AS TransactionQty, IRD.TotalMaterialBooksCurrencyAmount TotalMaterialBooksCurrencyAmount
														FROM [TRN].[InventoryReceiveDetail] IRD
														LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
														where convert(Date,IR.GRNDate) <= '" + toDate + @"' AND IR.OpeningBalanceId IS NOT NULL --group By IRD.InventoryMaterialId,IRD.MaterialStorageId,IRD.IsAsset
														UNION ALL
														SELECT IRD.InventoryMaterialId, IRD.MaterialStorageId,IRD.IsAsset,IRD.TransactionQty AS TransactionQty, IRD.TotalMaterialBooksCurrencyAmount TotalMaterialBooksCurrencyAmount
														FROM [TRN].[InventoryReceiveDetail] IRD
														LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
														where convert(Date,IR.GRNDate) < '" + toDate + @"' AND IR.OpeningBalanceId IS NULL --group By IRD.InventoryMaterialId,IRD.MaterialStorageId,IRD.IsAsset
												)as t --group by t.InventoryMaterialId,t.MaterialStorageId,t.IsAsset
												) AS opbal ON opbal.InventoryMaterialId=IM.Id AND " + paramters + @"
									left join [HKP].[MaterialStorage] MS on ms.id=opbal.MaterialStorageId
									LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
									left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id
									where MM.IsRegular='" + ValueOrNumber1 + @"'  AND MM.UserName is not null

									--Receive
									UNION ALL
									SELECT   MT.UserName MaterialType
										,MT.Id MaterialTypeID
										,MT.Sequence 
										,0 opbalTransactionQty
										,0 opbalTotalMaterialBooksCurrencyAmount
										--Opening Balance
										--,Round(SUM(isnull(ROUND(opbal.TransactionQty,0),0)-isnull(Round(IFD3.OpeningIssueQty,0),0)),0) As OpeningBalance	
										--,Round(SUM(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)-isnull(IFD3.PolicyAmount,0)),0) AS OpeningBalanceAmount

										--Receive

										,Isnull(opbal2.TransactionQty,0) ReceivedForThePeriod
										,Isnull(opbal2.TotalMaterialBooksCurrencyAmount,0) AS ReceivedForThePeriodAmount
										----Issue
                         
										,0 IssueForThePeriod	
										,0 IssueForThePeriodAmount	

										--Issue Return
										,0 IssueReturnQtyForThePeriod	
										,0 IssueReturnForThePeriodAmount	
										--Purchase Return
										,0 PurchaseReturnQtyForThePeriod	
										,0 PurchaseReturnForThePeriodAmount	

										--Adjust Return
										,0 AdjustmentQtyForThePeriod	
										,0 AdjustmentForThePeriodAmount	

										--Inventory Sales
										,0 InventorySalesQtyForThePeriod	
										,0 InventorySalesForThePeriodAmount	
										--Inventory Scrap
										,0 InventoryScrapQtyForThePeriod	
										,0 InventoryScrapForThePeriodAmount	

										--Inventory Transfer Data
										,0 InventoryTransferQtyForThePeriod	
										,0 InventoryTransferForThePeriodAmount
										--Opening Issue 
										,0 OpeningIssueQty	
										,0 PolicyAmount


									FROM TRN.InventoryMaterial AS IM
									left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
									LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
									LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
									LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
									LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
									LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
									LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
									LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
									left join(SELECT IRD.InventoryMaterialId,IRD.MaterialStorageId, IRD.TransactionQty AS TransactionQty,IRD.TotalMaterialBooksCurrencyAmount TotalMaterialBooksCurrencyAmount
												FROM  [TRN].[InventoryReceiveDetail] IRD
												LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
												where convert(Date,IR.GRNDate)	= '" + toDate + @"' AND IR.OpeningBalanceId IS  NULL --group By IRD.InventoryMaterialId
												) AS opbal2 ON opbal2.InventoryMaterialId=IM.Id AND " + paramters + @"
									--left join [HKP].[MaterialStorage] MS on ms.id=opbal2.MaterialStorageId
									LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
									left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id
									where MM.IsRegular='" + ValueOrNumber1 + @"'  AND MM.UserName is not null

									-- Issue ----
									UNION ALL
									SELECT   MT.UserName MaterialType
										,MT.Id MaterialTypeID
										,MT.Sequence 
										 --Opening Balance
										,0 opbalTransactionQty
										,0 opbalTotalMaterialBooksCurrencyAmount

										--Receive

										,0 ReceivedForThePeriod
										,0 AS ReceivedForThePeriodAmount
	 
										--Issue
                         
										,isnull(IFD1.IssueQty,0) IssueForThePeriod	
										,isnull(IFD1.PolicyAmount,0) IssueForThePeriodAmount	
										--Issue Return
										,0 IssueReturnQtyForThePeriod	
										,0 IssueReturnForThePeriodAmount	

										--Purchase Return
										,0 PurchaseReturnQtyForThePeriod	
										,0 PurchaseReturnForThePeriodAmount	

										--Adjust Return
										,0 AdjustmentQtyForThePeriod	
										,0 AdjustmentForThePeriodAmount	

										--Inventory Sales
										,0 InventorySalesQtyForThePeriod	
										,0 InventorySalesForThePeriodAmount
	
										--Inventory Scrap
