									left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id
									where MM.IsRegular='" + ValueOrNumber1 + @"'  AND MM.UserName is not null

									--Inventory Scrap
									UNION ALL
									SELECT   MT.UserName MaterialType
										,MT.Id MaterialTypeID
										,MT.Sequence 
										 --Opening Balance
										,0 opbalTransactionQty
										,0 opbalTotalMaterialBooksCurrencyAmount

										--Receive

										,0 ReceivedForThePeriod
										,0 AS ReceivedForThePeriodAmount
	 
