										,0 InventoryScrapQtyForThePeriod	
										,0 InventoryScrapForThePeriodAmount	

										--Inventory Transfer Data
										,isnull(InventoryTransferData.Qty,0) InventoryTransferQtyForThePeriod	
										,isnull(InventoryTransferData.InventoryTransferAmount,0) InventoryTransferForThePeriodAmount
										--Opening Issue 
										,0 OpeningIssueQty	
										,0 PolicyAmount


									FROM TRN.InventoryMaterial AS IM
									left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
									LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
									LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
									LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
									LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
									LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
									LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
									LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
									Left join ( SELECT IRD.InventoryMaterialId,IRD.MaterialStorageId, IRD.InventoryTransferQty Qty,IRD.MaterialTranRate Rate, (IRD.InventoryTransferQty*IRD.MaterialTranRate) InventoryTransferAmount 
												FROM [TRN].[InventoryTransferHistory] ITH
												Left JOIN [TRN].[InventoryReceiveDetail] IRD on IRD.Id=ITH.InventoryReceiveDetailId
												Left join [TRN].[InventoryReceive] IR on IR.Id=IRD.InventoryReceiveId
												WHERE convert(Date,IR.GRNDate) = '" + toDate + @"' --AND IR.PlantId='" + plantId + @"'
												--GROUP BY IRD.InventoryMaterialId
											)InventoryTransferData ON InventoryTransferData.InventoryMaterialId=IM.Id AND " + paramters + @"     
									--left join [HKP].[MaterialStorage] MS on ms.id=InventoryTransferData.MaterialStorageId
									LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
									left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id
									where MM.IsRegular='" + ValueOrNumber1 + @"'  AND MM.UserName is not null


									--Opening Issue Balance
									UNION ALL
									SELECT   MT.UserName MaterialType
										,MT.Id MaterialTypeID
										,MT.Sequence 
										 --Opening Balance
										,0 opbalTransactionQty
										,0 opbalTotalMaterialBooksCurrencyAmount

										--Receive

										,0 ReceivedForThePeriod
										,0 AS ReceivedForThePeriodAmount
	 
										--Issue
                         
										,0 IssueForThePeriod	
										,0 IssueForThePeriodAmount	

										--Issue Return
										,0 IssueReturnQtyForThePeriod	
										,0 IssueReturnForThePeriodAmount	

										--Purchase Return
										,0 PurchaseReturnQtyForThePeriod	
										,0 PurchaseReturnForThePeriodAmount	

										--Adjust Return
										,0 AdjustmentQtyForThePeriod	
										,0 AdjustmentForThePeriodAmount	

										--Inventory Sales
										,0 InventorySalesQtyForThePeriod	
										,0 InventorySalesForThePeriodAmount	

										--Inventory Scrap
										,0 InventoryScrapQtyForThePeriod	
										,0 InventoryScrapForThePeriodAmount	

										--Inventory Transfer Data
										,0 InventoryTransferQtyForThePeriod	
										,0 InventoryTransferForThePeriodAmount
										--Opening Issue 
										,isnull(IFD3.OpeningIssueQty,0) OpeningIssueQty	
										,isnull(IFD3.PolicyAmount,0) PolicyAmount


									FROM TRN.InventoryMaterial AS IM
									left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
									LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
									LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
									LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
									LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
									LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
									LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
									LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
									left join (select IID.InventoryMaterialId, IIH.Qty OpeningIssueQty,IIH.TotalAmount PolicyAmount--IID.TransactionQty OpeningIssueQty, IID.PolicyAmount PolicyAmount
												FROM TRN.InventoryIssueDetail IID  
												LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 	
												left join trn.InventoryIssueHistory IIH ON IIH.InventoryIssueDetailId=IID.Id
												LEFT JOIN TRN.InventoryReceiveDetail IRD ON IRD.Id=IIH.InventoryReceiveDetailId
												WHERE convert(Date,II.IssueDate) < '" + toDate + @"' --AND II.PlantId='" + plantId + @"' --GROUP BY IID.InventoryMaterialId
											  ) IFD3 On IFD3.InventoryMaterialId=IM.Id AND " + paramters + @"
									--left join [HKP].[MaterialStorage] MS on ms.id=IFD3.MaterialStorageId
									LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
									left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id
									where MM.IsRegular='" + ValueOrNumber1 + @"'  AND MM.UserName is not null
									) Res
									Group BY  Res.MaterialType,Res.MaterialTypeID,Res.Sequence
									ORDER BY Res.Sequence ASC  ";
                }

                else
                {
                    sql = @"SELECT Res.MaterialType,Res.MaterialTypeID,Res.Sequence

									--,sum(Res.OpeningIssueQty) OpeningIssueQty
									--,sum(Res.PolicyAmount) PolicyAmount
									,Round(sum(Res.opbalTransactionQty-Res.OpeningIssueQty),0) OpeningBalance
									,Round(Sum(Res.opbalTotalMaterialBooksCurrencyAmount-Res.PolicyAmount) ,0)OpeningBalanceAmount

									,Round(sum(Res.ReceivedForThePeriod),0) ReceivedForThePeriod
									,Round(sum(Res.ReceivedForThePeriodAmount),0)  ReceivedForThePeriodAmount

									,Round(Sum(Res.IssueForThePeriod),0) IssueForThePeriod
									,Round(Sum(Res.IssueForThePeriodAmount),0) IssueForThePeriodAmount

									,Round(SUM(Res.IssueReturnQtyForThePeriod),0) IssueReturnQtyForThePeriod
									,Round(SUM(Res.IssueReturnForThePeriodAmount),0) IssueReturnForThePeriodAmount

									,Round(Sum(Res.PurchaseReturnQtyForThePeriod),0)	 PurchaseReturnQtyForThePeriod
									,Round(Sum(Res.PurchaseReturnForThePeriodAmount),0)	 PurchaseReturnForThePeriodAmount

									,Round(Sum(Res.AdjustmentQtyForThePeriod),0)	 AdjustmentQtyForThePeriod
									,Round(Sum(Res.AdjustmentForThePeriodAmount),0)	 AdjustmentForThePeriodAmount

									,Round(Sum(Res.InventorySalesQtyForThePeriod),0)	 InventorySalesQtyForThePeriod
									,Round(Sum(Res.InventorySalesForThePeriodAmount),0)	InventorySalesForThePeriodAmount

									,Round(Sum(Res.InventoryScrapQtyForThePeriod),0)	InventoryScrapQtyForThePeriod
									,Round(Sum(Res.InventoryScrapForThePeriodAmount),0)	InventoryScrapForThePeriodAmount

									,Round(Sum(Res.InventoryTransferQtyForThePeriod),0)	InventoryTransferQtyForThePeriod
									,Round(Sum(Res.InventoryTransferForThePeriodAmount),0) InventoryTransferForThePeriodAmount
									,Round(SUM((((((((isnull(Res.opbalTransactionQty,0)-isnull(Res.OpeningIssueQty,0) + isnull(Res.ReceivedForThePeriod,0))-isnull(Res.IssueForThePeriod,0)-isnull(Res.PurchaseReturnQtyForThePeriod,0))-isnull(Res.AdjustmentQtyForThePeriod,0))+isnull(Res.IssueReturnQtyForThePeriod,0))-isnull(Res.InventorySalesQtyForThePeriod,0))-isnull(Res.InventoryScrapQtyForThePeriod,0))-isnull(Res.InventoryTransferQtyForThePeriod,0))),0) Closing 
									,Round(SUM((((((((isnull(Res.opbalTotalMaterialBooksCurrencyAmount,0)-isnull(Res.PolicyAmount,0) + isnull(Res.ReceivedForThePeriodAmount,0))-isnull(Res.IssueForThePeriodAmount,0)-isnull(Res.AdjustmentForThePeriodAmount,0))-isnull(Res.PurchaseReturnForThePeriodAmount,0))+isnull(Res.IssueReturnForThePeriodAmount,0)-isnull(Res.InventorySalesForThePeriodAmount,0))-isnull(Res.InventoryScrapForThePeriodAmount,0))-isnull(Res.InventoryTransferForThePeriodAmount,0)))),0) ClosingAmount
									FROM (
									--Opening 
									SELECT   
										MT.UserName MaterialType
										,MT.Id MaterialTypeID
										,MT.Sequence 
										,Isnull(opbal.TransactionQty,0) opbalTransactionQty
										,Isnull(opbal.TotalMaterialBooksCurrencyAmount,0) opbalTotalMaterialBooksCurrencyAmount
										--Opening Balance
										--,Round(SUM(isnull(ROUND(opbal.TransactionQty,0),0)-isnull(Round(IFD3.OpeningIssueQty,0),0)),0) As OpeningBalance	
										--,Round(SUM(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)-isnull(IFD3.PolicyAmount,0)),0) AS OpeningBalanceAmount

										--Receive

										,0 AS ReceivedForThePeriod
										,0 AS ReceivedForThePeriodAmount
										----Issue
                         
										,0 IssueForThePeriod	
										,0 IssueForThePeriodAmount	

										--Issue Return
										,0 IssueReturnQtyForThePeriod	
										,0 IssueReturnForThePeriodAmount	

										--Purchase Return
										,0 PurchaseReturnQtyForThePeriod	
										,0 PurchaseReturnForThePeriodAmount	

										--Adjust Return
										,0 AdjustmentQtyForThePeriod	
										,0 AdjustmentForThePeriodAmount	

										--Inventory Sales
										,0 InventorySalesQtyForThePeriod	
										,0 InventorySalesForThePeriodAmount	
										--Inventory Scrap
										,0 InventoryScrapQtyForThePeriod	
										,0 InventoryScrapForThePeriodAmount	

										--Inventory Transfer Data
										,0 InventoryTransferQtyForThePeriod	
										,0 InventoryTransferForThePeriodAmount
										--Opening Issue 
										,0 OpeningIssueQty	
										,0 PolicyAmount


									FROM TRN.InventoryMaterial AS IM
									left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
									LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
									LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
									LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
									LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
									LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
									LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
									LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
									left join( select t.InventoryMaterialId,t.MaterialStorageId,t.IsAsset, t.TransactionQty TransactionQty,t.TotalMaterialBooksCurrencyAmount TotalMaterialBooksCurrencyAmount 
												from (
														SELECT IRD.InventoryMaterialId, IRD.MaterialStorageId,IRD.IsAsset,IRD.TransactionQty AS TransactionQty, IRD.TotalMaterialBooksCurrencyAmount TotalMaterialBooksCurrencyAmount
														FROM [TRN].[InventoryReceiveDetail] IRD
														LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
														where convert(Date,IR.GRNDate) <= '" + fromDate + @"' AND IR.OpeningBalanceId IS NOT NULL --group By IRD.InventoryMaterialId,IRD.MaterialStorageId,IRD.IsAsset
														UNION ALL
														SELECT IRD.InventoryMaterialId, IRD.MaterialStorageId,IRD.IsAsset,IRD.TransactionQty AS TransactionQty, IRD.TotalMaterialBooksCurrencyAmount TotalMaterialBooksCurrencyAmount
														FROM [TRN].[InventoryReceiveDetail] IRD
														LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
														where convert(Date,IR.GRNDate) < '" + fromDate + @"' AND IR.OpeningBalanceId IS NULL --group By IRD.InventoryMaterialId,IRD.MaterialStorageId,IRD.IsAsset
												)as t --group by t.InventoryMaterialId,t.MaterialStorageId,t.IsAsset
												) AS opbal ON opbal.InventoryMaterialId=IM.Id AND " + paramters + @"
									left join [HKP].[MaterialStorage] MS on ms.id=opbal.MaterialStorageId
									LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
									left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id
									where MM.IsRegular='" + ValueOrNumber1 + @"'  AND MM.UserName is not null

									--Receive
									UNION ALL
									SELECT   MT.UserName MaterialType
										,MT.Id MaterialTypeID
										,MT.Sequence 
										,0 opbalTransactionQty
										,0 opbalTotalMaterialBooksCurrencyAmount
										--Opening Balance
										--,Round(SUM(isnull(ROUND(opbal.TransactionQty,0),0)-isnull(Round(IFD3.OpeningIssueQty,0),0)),0) As OpeningBalance	
										--,Round(SUM(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)-isnull(IFD3.PolicyAmount,0)),0) AS OpeningBalanceAmount

										--Receive

										,Isnull(opbal2.TransactionQty,0) ReceivedForThePeriod
										,Isnull(opbal2.TotalMaterialBooksCurrencyAmount,0) AS ReceivedForThePeriodAmount
										----Issue
                         
										,0 IssueForThePeriod	
										,0 IssueForThePeriodAmount	

										--Issue Return
										,0 IssueReturnQtyForThePeriod	
										,0 IssueReturnForThePeriodAmount	
										--Purchase Return
										,0 PurchaseReturnQtyForThePeriod	
										,0 PurchaseReturnForThePeriodAmount	

										--Adjust Return
										,0 AdjustmentQtyForThePeriod	
										,0 AdjustmentForThePeriodAmount	

										--Inventory Sales
										,0 InventorySalesQtyForThePeriod	
										,0 InventorySalesForThePeriodAmount	
										--Inventory Scrap
										,0 InventoryScrapQtyForThePeriod	
										,0 InventoryScrapForThePeriodAmount	

										--Inventory Transfer Data
										,0 InventoryTransferQtyForThePeriod	
										,0 InventoryTransferForThePeriodAmount
										--Opening Issue 
										,0 OpeningIssueQty	
										,0 PolicyAmount


									FROM TRN.InventoryMaterial AS IM
									left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
									LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
									LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
									LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
									LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
									LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
									LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
									LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
									LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
									left join(SELECT IRD.InventoryMaterialId,IRD.MaterialStorageId, IRD.TransactionQty AS TransactionQty,IRD.TotalMaterialBooksCurrencyAmount TotalMaterialBooksCurrencyAmount
												FROM  [TRN].[InventoryReceiveDetail] IRD
												LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
												where convert(Date,IR.GRNDate)	BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' AND IR.OpeningBalanceId IS  NULL --group By IRD.InventoryMaterialId
												) AS opbal2 ON opbal2.InventoryMaterialId=IM.Id AND " + paramters + @"
									--left join [HKP].[MaterialStorage] MS on ms.id=opbal2.MaterialStorageId
									LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
									left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id
									where MM.IsRegular='" + ValueOrNumber1 + @"'  AND MM.UserName is not null

									-- Issue ----
									UNION ALL
									SELECT   MT.UserName MaterialType
