									left join (SELECT IID.InventoryMaterialId,IRD.MaterialStorageId, IH.Qty IssueQty,IH.TotalAmount PolicyAmount--IID.TransactionQty IssueQty , IID.PolicyAmount PolicyAmount
												FROM TRN.InventoryIssueDetail IID  
