									left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id
									where MM.IsRegular='" + ValueOrNumber1 + @"'  AND MM.UserName is not null 
									) Res
									Where Res.MaterialTypeID='" + MaterialTypeID + @"'
									Group BY  Res.MaterialType,Res.MaterialTypeID,Res.Sequence,Res.MaterialGroup,Res.MaterialGroupID
									ORDER BY Res.Sequence ASC  ";
